(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,52947,e=>{"use strict";var t=e.i(89841);let a=[(0,t.sc)({id:"airway-01",title:"Dyspnea with Tripod Positioning",category:"airway",difficulty:"foundational",source:t.NATIONAL,dispatch:"32 y/o male, difficulty breathing, sitting on porch. Caller says he looks scared and won't lie down.",scene:"Residential porch, afternoon, well lit. One adult bystander. No hazards. Patient sitting forward on a chair, hands on knees.",presentation:"Alert, speaking in short phrases, audible wheezing, using accessory muscles, tripod posture. Denies trauma. Says 'I can't get air.'",vitals:{hr:118,rr:28,spo2:90,bp:"142/88",skin:"pale, diaphoretic",gcs:"15"},startNodeId:"a01-n1",nodes:[{id:"a01-n1",prompt:"After scene safety and BSI, what is your first priority?",options:[{id:"a01-n1-best",text:"Assess airway patency and work of breathing while keeping the patient in a position of comfort (tripod/sitting)",quality:"best",next:"a01-n2",feedback:"Correct. Position of comfort supports ventilation; simultaneously evaluate the airway and breathing effort."},{id:"a01-n1-ok",text:"Obtain a full SAMPLE history before touching the patient",quality:"incorrect",next:"a01-n2",feedback:"History matters, but life threats to airway and breathing come first in primary assessment.",delayedCritical:!0},{id:"a01-n1-bad",text:"Lay the patient flat to take a blood pressure",quality:"harmful",next:"a01-n2",feedback:"Forcing a dyspneic patient flat can worsen respiratory distress. Keep them upright if tolerated.",delayedCritical:!0},{id:"a01-n1-wrong",text:"Focus only on pulse and skin color; breathing can wait until transport",quality:"incorrect",next:"a01-n2",feedback:"Breathing assessment is part of the ABCs and cannot be deferred.",delayedCritical:!0}]},{id:"a01-n2",prompt:"SpO₂ is 90% on room air; patient remains upright and alert. Best next action?",vitals:{hr:120,rr:28,spo2:90,bp:"144/90"},options:[{id:"a01-n2-best",text:"Apply high-flow oxygen per protocol and reassess work of breathing and SpO₂",quality:"best",next:"a01-n3",feedback:"Correct. Hypoxemic dyspnea needs oxygen while you continue assessment and prepare for ALS/transport."},{id:"a01-n2-ok",text:"Coach slow breathing only; withhold oxygen until SpO₂ drops further",quality:"incorrect",next:"a01-n3",feedback:"Coaching may help, but SpO₂ 90% with distress warrants oxygen now.",delayedCritical:!0},{id:"a01-n2-bad",text:"Begin immediate bag-valve-mask ventilations on this alert, speaking patient",quality:"harmful",next:"a01-n3",feedback:"BVM is for inadequate ventilation or failure—not an alert patient who is still moving air with distress."},{id:"a01-n2-acc",text:"Apply oxygen and simultaneously ask about asthma, inhaler use, and onset",quality:"acceptable",next:"a01-n3",feedback:"Acceptable. Oxygen plus focused history is appropriate once ABCs are addressed."}]},{id:"a01-n3",prompt:"After oxygen, SpO₂ rises to 94% but accessory muscle use continues. What should guide your transport plan?",vitals:{hr:112,rr:26,spo2:94,bp:"140/86"},options:[{id:"a01-n3-best",text:"Treat as priority respiratory distress: keep upright, ongoing oxygen, rapid transport, request ALS if available",quality:"best",next:"a01-n4",feedback:"Correct. Persistent work of breathing after oxygen is a high-priority medical emergency."},{id:"a01-n3-ok",text:"Stay on scene to complete a full secondary survey before moving",quality:"incorrect",next:"a01-n4",feedback:"Do not delay transport for exhaustive secondary exam when the patient remains in respiratory distress.",delayedCritical:!0},{id:"a01-n3-bad",text:"Have the patient walk to the ambulance to 'expand the lungs'",quality:"harmful",next:"a01-n4",feedback:"Exertion can worsen hypoxia and fatigue. Move the patient with assistance, minimizing effort."},{id:"a01-n3-wrong",text:"Cancel ALS because SpO₂ improved slightly",quality:"incorrect",next:"a01-n4",feedback:"A small SpO₂ rise does not erase ongoing distress or the need for advanced support."}]},{id:"a01-n4",prompt:"En route the patient becomes drowsy and speaks only single words. Best action?",sceneUpdate:"Patient slumps slightly but still has a pulse; respirations become shallow.",vitals:{hr:128,rr:8,spo2:88,bp:"100/70",gcs:"12"},options:[{id:"a01-n4-best",text:"Open the airway as needed and assist ventilations with a BVM and oxygen; prepare for deterioration",quality:"best",next:"end",feedback:"Correct. Fatigue and declining mental status mean inadequate ventilation—assist breaths immediately."},{id:"a01-n4-ok",text:"Increase oxygen flow only and continue coaching",quality:"incorrect",next:"end",feedback:"Shallow, slow respirations need assisted ventilation, not oxygen alone.",delayedCritical:!0},{id:"a01-n4-bad",text:"Insert an OPA in this semi-responsive patient with a gag reflex without assessing need",quality:"harmful",next:"end",feedback:"OPA is contraindicated if gag reflex is present; it can cause vomiting and aspiration."},{id:"a01-n4-acc",text:"Assist ventilations and update ALS/receiving facility on decline",quality:"acceptable",next:"end",feedback:"Acceptable. Ventilatory support plus early notification is appropriate."}]}],correctSequence:["Keep upright; assess airway and work of breathing","High-flow oxygen per protocol; reassess SpO₂ and effort","Priority transport upright with ongoing oxygen; request ALS","If ventilation fails, assist with BVM and oxygen"],keyTakeaway:"Tripod dyspnea gets position of comfort and oxygen first; falling mental status means switch from oxygen alone to assisted ventilation."}),(0,t.sc)({id:"airway-02",title:"Asthma Exacerbation",category:"airway",difficulty:"application",source:t.NATIONAL,dispatch:"19 y/o female, known asthma, severe shortness of breath after soccer practice. Mother on scene with inhaler.",scene:"School athletic field, clear weather. Coach and parent present. No safety hazards.",presentation:"Sitting forward, prolonged expiratory wheezes, speaking 2–3 words at a time. Used her prescribed inhaler once with little relief. Denies chest trauma. Anxious.",vitals:{hr:124,rr:32,spo2:91,bp:"128/78",skin:"flushed, sweaty",gcs:"15"},startNodeId:"a02-n1",nodes:[{id:"a02-n1",prompt:"Primary assessment findings confirm respiratory distress. Best immediate management?",options:[{id:"a02-n1-best",text:"Keep seated upright, apply oxygen per protocol, and assess for prescribed inhaler assist per protocol",quality:"best",next:"a02-n2",feedback:"Correct. Position, oxygen, and protocol-guided inhaler assist are core EMT asthma care."},{id:"a02-n1-bad",text:"Lay her supine and begin aggressive abdominal thrusts",quality:"harmful",next:"a02-n2",feedback:"This is asthma, not choking. Supine positioning harms ventilation."},{id:"a02-n1-wrong",text:"Withhold oxygen because asthmatics should always stay hypoxic to 'drive breathing'",quality:"incorrect",next:"a02-n2",feedback:"That myth is dangerous. Treat hypoxia; monitor closely.",delayedCritical:!0},{id:"a02-n1-acc",text:"Oxygen first, then confirm inhaler is prescribed to the patient before assisting",quality:"acceptable",next:"a02-n2",feedback:"Acceptable sequence—verify the medication belongs to the patient."}]},{id:"a02-n2",prompt:"Mother hands you the patient's prescribed MDI. Patient is alert and cooperative. What is correct?",options:[{id:"a02-n2-best",text:"Confirm it is her prescribed inhaler, check indications/contraindications per protocol, then assist as allowed",quality:"best",next:"a02-n3",feedback:"Correct. EMTs assist with the patient's prescribed inhaler under protocol—never invent a dose."},{id:"a02-n2-bad",text:"Give several extra puffs beyond what protocol allows because she looks bad",quality:"harmful",next:"a02-n3",feedback:"Do not exceed protocol. Overuse risks toxicity and arrhythmia."},{id:"a02-n2-wrong",text:"Refuse any inhaler assist and only drive without treatment",quality:"incorrect",next:"a02-n3",feedback:"If protocol allows assist and criteria are met, withholding delays bronchodilation.",delayedCritical:!0},{id:"a02-n2-acc",text:"Oxygen ongoing; assist inhaler per protocol while preparing rapid transport",quality:"acceptable",next:"a02-n3",feedback:"Acceptable combined approach."}]},{id:"a02-n3",prompt:"After oxygen and inhaler assist, wheezing is quieter but the patient looks exhausted and SpO₂ is 89%. Concern?",vitals:{hr:130,rr:10,spo2:89,bp:"110/70",gcs:"14"},options:[{id:"a02-n3-best",text:"Recognize possible 'silent chest'/fatigue—prepare to assist ventilations and expedite ALS/ED care",quality:"best",next:"a02-n4",feedback:"Correct. Decreasing wheeze with fatigue can mean worsening airflow, not improvement."},{id:"a02-n3-ok",text:"Assume she is improving because wheezes are softer; delay transport",quality:"harmful",next:"a02-n4",feedback:"Quieter breath sounds with exhaustion is a red flag for failure.",delayedCritical:!0},{id:"a02-n3-wrong",text:"Force her to walk to 'open airways'",quality:"harmful",next:"a02-n4",feedback:"Exertion can precipitate respiratory arrest."},{id:"a02-n3-acc",text:"Reassess ABCs frequently and be ready to BVM if tidal volume falls",quality:"acceptable",next:"a02-n4",feedback:"Acceptable vigilance."}]},{id:"a02-n4",prompt:"She becomes barely responsive with inadequate chest rise. Next step?",options:[{id:"a02-n4-best",text:"Open airway, assist ventilations with BVM and oxygen, monitor for arrest",quality:"best",next:"end",feedback:"Correct. Inadequate ventilation requires immediate BVM support."},{id:"a02-n4-wrong",text:"Continue nasal cannula only and wait for the hospital",quality:"incorrect",next:"end",feedback:"Nasal cannula cannot fix apnea/hypoventilation.",delayedCritical:!0},{id:"a02-n4-bad",text:"Perform blind finger sweeps of the mouth",quality:"harmful",next:"end",feedback:"Blind sweeps can push objects deeper and are not indicated here."},{id:"a02-n4-acc",text:"BVM ventilations with high-flow oxygen and urgent update to ALS",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Upright positioning and oxygen; evaluate for prescribed inhaler assist","Assist with patient's prescribed MDI only per protocol","Watch for fatigue/silent chest as signs of failure","Assist ventilations if breathing becomes inadequate"],keyTakeaway:"Asthma care is oxygen, position, and protocol inhaler assist—falling effort or a quieting chest means imminent ventilatory failure."}),(0,t.sc)({id:"airway-03",title:"Opioid Overdose — Airway First",category:"airway",difficulty:"critical",source:t.NATIONAL,dispatch:"Unresponsive adult in bathroom, possible overdose. Slow breathing reported.",scene:"Apartment bathroom. Drug paraphernalia visible. Scene safe after PD clears. Partner present.",presentation:"Unresponsive to voice, responds only to deep pain with moan. Snoring respirations, cyanotic lips, pinpoint pupils. Pulse present and slow.",vitals:{hr:52,rr:6,spo2:78,bp:"98/60",skin:"cool, cyanotic",gcs:"6",glucose:"110"},startNodeId:"a03-n1",nodes:[{id:"a03-n1",prompt:"What is the immediate priority for this unresponsive, hypoventilating patient?",options:[{id:"a03-n1-best",text:"Open the airway (head-tilt/chin-lift if no trauma), suction if needed, and begin assisting ventilations with oxygen",quality:"best",next:"a03-n2",feedback:"Correct. Airway and breathing failures kill first—support ventilation before other interventions."},{id:"a03-n1-wrong",text:"Search the room for a medication history before touching the patient",quality:"incorrect",next:"a03-n2",feedback:"Do not delay airway support to investigate.",delayedCritical:!0},{id:"a03-n1-bad",text:"Leave the patient face-down to 'drain secretions'",quality:"harmful",next:"a03-n2",feedback:"Prone positioning without a managed airway risks further obstruction."},{id:"a03-n1-acc",text:"Manually open airway and prepare BVM while checking pulse",quality:"acceptable",next:"a03-n2",feedback:"Acceptable concurrent ABC approach."}]},{id:"a03-n2",prompt:"You are ventilating adequately; SpO₂ is rising. Partner asks about naloxone. Correct EMT framing?",vitals:{hr:56,rr:"assisted",spo2:92,bp:"100/64"},options:[{id:"a03-n2-best",text:"Continue effective ventilations; administer/assist naloxone per protocol if indicated, without delaying airway support",quality:"best",next:"a03-n3",feedback:"Correct. Ventilation is primary; naloxone is adjunct per protocol—no dose invention."},{id:"a03-n2-bad",text:"Stop ventilating so the drug can 'work better' alone",quality:"harmful",next:"a03-n3",feedback:"Never stop ventilations waiting for naloxone."},{id:"a03-n2-wrong",text:"Give an arbitrary large dose you invent on scene",quality:"harmful",next:"a03-n3",feedback:"Never invent medication doses. Follow protocol only."},{id:"a03-n2-acc",text:"Keep BVM support and request ALS while following local naloxone protocol",quality:"acceptable",next:"a03-n3",feedback:"Acceptable."}]},{id:"a03-n3",prompt:"After naloxone per protocol, the patient becomes agitated and tries to refuse care. Best next step?",sceneUpdate:"Patient sits up, SpO₂ 96% on oxygen, still drowsy.",vitals:{hr:88,rr:14,spo2:96,bp:"118/72",gcs:"14"},options:[{id:"a03-n3-best",text:"Reassess ABCs, explain risks of recurrence, encourage transport, and document; do not abandon an unsafe refusal process",quality:"best",next:"a03-n4",feedback:"Correct. Opioid effects can return; capacity and informed refusal matter—stay professional."},{id:"a03-n3-bad",text:"Physically restrain and force an airway adjunct because he overdosed",quality:"harmful",next:"a03-n4",feedback:"Forcing invasive care on an improving, protecting patient is harmful and legally risky."},{id:"a03-n3-wrong",text:"Leave immediately without reassessment once he can speak",quality:"incorrect",next:"a03-n4",feedback:"Reassess and address refusal properly; renarcotization is possible."},{id:"a03-n3-acc",text:"Monitor closely, keep oxygen as needed, strongly recommend ED evaluation",quality:"acceptable",next:"a03-n4",feedback:"Acceptable."}]},{id:"a03-n4",prompt:"During packaging he becomes unresponsive again with snoring. Priority?",options:[{id:"a03-n4-best",text:"Re-open airway, suction if needed, resume assisted ventilations, reconsider protocol naloxone/ALS",quality:"best",next:"end",feedback:"Correct. Recurrence of hypoventilation returns you to airway/breathing support."},{id:"a03-n4-wrong",text:"Assume he is faking and continue loading without airway care",quality:"harmful",next:"end",feedback:"Snoring unresponsiveness is a true airway emergency.",delayedCritical:!0},{id:"a03-n4-bad",text:"Pour water on his face to wake him",quality:"harmful",next:"end",feedback:"Not a substitute for airway management; aspiration risk."},{id:"a03-n4-acc",text:"Airway + BVM again; update receiving facility",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Open airway and assist ventilations with oxygen","Naloxone only as protocol adjunct—never stop ventilating","Reassess after improvement; address refusal carefully","If hypoventilation returns, restart airway/ventilation support"],keyTakeaway:"In opioid overdose, effective airway opening and BVM come first; naloxone supports but never replaces ventilation."}),(0,t.sc)({id:"airway-04",title:"Choking: Conscious to Unconscious",category:"airway",difficulty:"critical",source:t.NATIONAL,dispatch:"Restaurant, adult choking on food. Conscious on dispatch.",scene:"Crowded dining room. Waitstaff pointing to a middle-aged male standing at a table, clutching his throat.",presentation:"Universal choking sign, unable to speak or cough effectively, cyanosis around lips. Still standing with a pulse.",vitals:{hr:120,rr:"ineffective",spo2:"unable",bp:"not yet obtained",skin:"cyanotic",gcs:"15 (panic)"},startNodeId:"a04-n1",nodes:[{id:"a04-n1",prompt:"Severe FBAO in a conscious adult. Best action?",options:[{id:"a04-n1-best",text:"Perform abdominal thrusts (or chest thrusts if pregnant/obese) until object expels or patient becomes unresponsive",quality:"best",next:"a04-n2",feedback:"Correct. Severe choking needs immediate foreign-body airway clearing."},{id:"a04-n1-wrong",text:"Encourage him to take deep breaths and drink water",quality:"harmful",next:"a04-n2",feedback:"Ineffective cough plus silence means severe obstruction—water will not help.",delayedCritical:!0},{id:"a04-n1-bad",text:"Blind finger sweep while he is standing and conscious",quality:"harmful",next:"a04-n2",feedback:"Blind sweeps are not for conscious patients and can worsen obstruction."},{id:"a04-n1-acc",text:"Confirm severe obstruction, activate help, begin abdominal thrusts",quality:"acceptable",next:"a04-n2",feedback:"Acceptable."}]},{id:"a04-n2",prompt:"After several thrusts he collapses unresponsive. You lower him to the floor. Next?",sceneUpdate:"Patient unresponsive, not breathing normally.",options:[{id:"a04-n2-best",text:"Begin CPR starting with compressions; each time you open the airway look for an object and remove only if visible",quality:"best",next:"a04-n3",feedback:"Correct. Unresponsive FBAO care follows CPR with checks for a visible object."},{id:"a04-n2-wrong",text:"Continue only abdominal thrusts on the unresponsive patient on the floor",quality:"incorrect",next:"a04-n3",feedback:"Once unresponsive, switch to CPR-based algorithm.",delayedCritical:!0},{id:"a04-n2-bad",text:"Spend prolonged time with repeated blind finger sweeps before compressions",quality:"harmful",next:"a04-n3",feedback:"Blind sweeps delay CPR and may push the object deeper."},{id:"a04-n2-acc",text:"Activate ALS/AED, start CPR, inspect mouth when opening airway",quality:"acceptable",next:"a04-n3",feedback:"Acceptable."}]},{id:"a04-n3",prompt:"During airway opening you see a piece of food. What do you do?",options:[{id:"a04-n3-best",text:"Remove the visible object, then attempt ventilations and continue CPR as needed",quality:"best",next:"a04-n4",feedback:"Correct. Only remove objects you can see."},{id:"a04-n3-bad",text:"Push the object farther back to 'clear the path'",quality:"harmful",next:"a04-n4",feedback:"Never push a foreign body deeper."},{id:"a04-n3-wrong",text:"Ignore it and only compress forever without trying to clear",quality:"incorrect",next:"a04-n4",feedback:"A visible object should be removed when the airway is opened."},{id:"a04-n3-acc",text:"Remove visible food with a finger sweep, then ventilate",quality:"acceptable",next:"a04-n4",feedback:"Acceptable when the object is seen."}]},{id:"a04-n4",prompt:"Object removed; patient has a pulse and starts gasping. Priority?",vitals:{hr:110,rr:8,spo2:85,bp:"130/80",gcs:"10"},options:[{id:"a04-n4-best",text:"Support airway, assist ventilations as needed with oxygen, monitor for re-obstruction, rapid transport",quality:"best",next:"end",feedback:"Correct. Post-obstruction patients need airway support and close monitoring."},{id:"a04-n4-wrong",text:"Declare the emergency over and have him finish dinner",quality:"harmful",next:"end",feedback:"Airway trauma, aspiration, and hypoxia effects still require evaluation."},{id:"a04-n4-bad",text:"Force an OPA while he is gagging vigorously",quality:"harmful",next:"end",feedback:"OPA with intact gag causes vomiting."},{id:"a04-n4-acc",text:"Oxygen/ventilatory support and ED transport for evaluation",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Abdominal (or chest) thrusts for severe conscious choking","If unresponsive: CPR with visible-object checks","Remove only what you can see; attempt ventilations","Post-clearance: support breathing and transport"],keyTakeaway:"Severe conscious choking gets thrusts; once unresponsive, switch to CPR and remove only visible objects."}),(0,t.sc)({id:"airway-05",title:"CHF / Pulmonary Edema Respiratory Distress",category:"airway",difficulty:"application",source:t.NATIONAL,dispatch:"74 y/o female, sudden shortness of breath, history of heart failure. Sitting in recliner.",scene:"Private residence, bedroom. Husband present. Home oxygen concentrator in corner, currently off.",presentation:"Orthopnea, wet crackles bilaterally, frothy sputum, speaking in short phrases. Legs with chronic edema. Denies fever. Very anxious.",vitals:{hr:118,rr:30,spo2:86,bp:"178/98",skin:"pale, diaphoretic",gcs:"15"},startNodeId:"a05-n1",nodes:[{id:"a05-n1",prompt:"Best initial positioning and oxygen approach?",options:[{id:"a05-n1-best",text:"Keep sitting upright/legs dependent; apply high-flow oxygen per protocol and reassess",quality:"best",next:"a05-n2",feedback:"Correct. Upright position reduces pulmonary congestion work; treat hypoxia."},{id:"a05-n1-bad",text:"Lay flat to improve blood pressure reading comfort",quality:"harmful",next:"a05-n2",feedback:"Flat position worsens orthopnea and edema fluid shift into lungs.",delayedCritical:!0},{id:"a05-n1-wrong",text:"Withhold oxygen until a full 12-lead is done by you as EMT",quality:"incorrect",next:"a05-n2",feedback:"Oxygen for hypoxemia is not delayed for non-critical tasks.",delayedCritical:!0},{id:"a05-n1-acc",text:"Upright posture, oxygen, calm reassurance while preparing transport",quality:"acceptable",next:"a05-n2",feedback:"Acceptable."}]},{id:"a05-n2",prompt:"Husband offers her prescribed nitroglycerin tablets. She has crackles and BP 178/98. EMT consideration?",options:[{id:"a05-n2-best",text:"Follow local protocol for assisting prescribed nitro only if criteria met; prioritize oxygen, position, and ALS/rapid transport",quality:"best",next:"a05-n3",feedback:"Correct. No invented doses; many systems require ALS for CHF meds—know your protocol."},{id:"a05-n2-bad",text:"Give multiple nitro tablets based on a dose you invent",quality:"harmful",next:"a05-n3",feedback:"Never invent doses."},{id:"a05-n2-wrong",text:"Ignore hypoxia and argue about medication philosophy on scene",quality:"incorrect",next:"a05-n3",feedback:"Airway/oxygen remain the immediate priorities.",delayedCritical:!0},{id:"a05-n2-acc",text:"Continue oxygen/upright care and request ALS for advanced CHF management",quality:"acceptable",next:"a05-n3",feedback:"Acceptable when protocol limits EMT medication assist."}]},{id:"a05-n3",prompt:"Despite oxygen, she becomes more fatigued with shallow breaths. Next?",vitals:{hr:130,rr:8,spo2:84,bp:"160/90",gcs:"13"},options:[{id:"a05-n3-best",text:"Assist ventilations with BVM and oxygen; consider CPAP only if trained/protocol and she remains candidate",quality:"best",next:"a05-n4",feedback:"Correct. Inadequate rate/volume needs assisted ventilation; CPAP is protocol/training dependent."},{id:"a05-n3-wrong",text:"Keep NC only because 'CHF patients shouldn't be ventilated'",quality:"incorrect",next:"a05-n4",feedback:"Hypoventilation still requires support.",delayedCritical:!0},{id:"a05-n3-bad",text:"Force CPAP on a nearly unresponsive patient who cannot protect her airway",quality:"harmful",next:"a05-n4",feedback:"CPAP needs a spontaneously breathing, cooperative/protecting patient per typical protocols."},{id:"a05-n3-acc",text:"BVM assist and expedite transport/ALS",quality:"acceptable",next:"a05-n4",feedback:"Acceptable."}]},{id:"a05-n4",prompt:"Transport priority decision?",options:[{id:"a05-n4-best",text:"High priority: ongoing respiratory support, upright if possible, early hospital notification",quality:"best",next:"end",feedback:"Correct. Acute pulmonary edema is time-sensitive."},{id:"a05-n4-wrong",text:"Non-emergent transport after a complete home inventory of medications",quality:"incorrect",next:"end",feedback:"Do not delay for nonessential tasks.",delayedCritical:!0},{id:"a05-n4-bad",text:"Have her walk downstairs unassisted 'for exercise'",quality:"harmful",next:"end",feedback:"Exertion can cause arrest."},{id:"a05-n4-acc",text:"Priority move with continuous monitoring and oxygen/ventilation support",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Upright position and high-flow oxygen","Medication assist only per protocol—no invented doses","Assist ventilations if effort fails; CPAP only if allowed/appropriate","High-priority transport with early notification"],keyTakeaway:"Suspected cardiogenic pulmonary edema: keep upright, oxygenate, and escalate to assisted ventilation when fatigue appears."}),(0,t.sc)({id:"airway-06",title:"Aspiration Risk — Vomiting Unresponsive",category:"airway",difficulty:"application",source:t.NATIONAL,dispatch:"Elderly male found unresponsive at nursing facility after vomiting. Possible stroke history.",scene:"Skilled nursing facility room. Staff present. Suction available on wall. Patient supine in bed, gurgling.",presentation:"Unresponsive, gurgling upper airway sounds, vomitus in mouth and on pillow. Spontaneous but noisy respirations. Pulse present.",vitals:{hr:96,rr:20,spo2:88,bp:"150/90",skin:"pale",gcs:"7",glucose:"140"},startNodeId:"a06-n1",nodes:[{id:"a06-n1",prompt:"Immediate airway action?",options:[{id:"a06-n1-best",text:"Position to drain if needed, suction the oropharynx, then open airway and oxygenate/ventilate as indicated",quality:"best",next:"a06-n2",feedback:"Correct. Clear vomit first—suction before forcing positive pressure into a soiled airway."},{id:"a06-n1-bad",text:"Immediately BVM large volumes without clearing the mouth",quality:"harmful",next:"a06-n2",feedback:"Bagging into vomitus drives aspirate into the lungs.",delayedCritical:!0},{id:"a06-n1-wrong",text:"Ignore gurgling and start a detailed neurologic exam",quality:"incorrect",next:"a06-n2",feedback:"Gurgling is an airway threat first.",delayedCritical:!0},{id:"a06-n1-acc",text:"Log-roll/recovery position briefly to clear, then suction and reassess",quality:"acceptable",next:"a06-n2",feedback:"Acceptable when spinal injury is not the leading concern and it helps drainage."}]},{id:"a06-n2",prompt:"Airway is clearer after suction; patient still unresponsive with inadequate tidal volume. Next?",vitals:{hr:100,rr:8,spo2:86,bp:"148/88",gcs:"7"},options:[{id:"a06-n2-best",text:"Insert appropriate airway adjunct if tolerated and assist ventilations with BVM and oxygen",quality:"best",next:"a06-n3",feedback:"Correct. After clearing, support ventilation and protect the airway."},{id:"a06-n2-wrong",text:"Leave him without ventilatory support because suction 'fixed it'",quality:"incorrect",next:"a06-n3",feedback:"Hypoventilation remains after clearing.",delayedCritical:!0},{id:"a06-n2-bad",text:"Pour oral fluids to 'rinse' the airway",quality:"harmful",next:"a06-n3",feedback:"Adds aspiration volume."},{id:"a06-n2-acc",text:"NPA/OPA as appropriate plus BVM with high-flow oxygen",quality:"acceptable",next:"a06-n3",feedback:"Acceptable."}]},{id:"a06-n3",prompt:"During BVM he vomits again. Best response?",options:[{id:"a06-n3-best",text:"Turn patient as able, suction immediately, then resume careful ventilations",quality:"best",next:"a06-n4",feedback:"Correct. Interrupt to clear; then resume support."},{id:"a06-n3-bad",text:"Keep bagging through the vomit to maintain a schedule",quality:"harmful",next:"a06-n4",feedback:"Forces aspirate into lungs."},{id:"a06-n3-wrong",text:"Stop all care and wait silently for ALS without suctioning",quality:"incorrect",next:"a06-n4",feedback:"You can and must suction now.",delayedCritical:!0},{id:"a06-n3-acc",text:"Suction quickly and reassess airway patency before next ventilation",quality:"acceptable",next:"a06-n4",feedback:"Acceptable."}]},{id:"a06-n4",prompt:"Transport consideration for aspiration risk?",options:[{id:"a06-n4-best",text:"Maintain suction readiness, continuous airway monitoring, and priority transport with ALS backup if available",quality:"best",next:"end",feedback:"Correct. Aspiration patients deteriorate—stay ready to suction and ventilate."},{id:"a06-n4-wrong",text:"Non-urgent transport without suction available",quality:"incorrect",next:"end",feedback:"Suction must travel with an aspiration-risk airway."},{id:"a06-n4-bad",text:"Feed ice chips to keep the mouth moist",quality:"harmful",next:"end",feedback:"NPO—aspiration risk."},{id:"a06-n4-acc",text:"Keep airway kit and suction at the head throughout transport",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Suction/clear vomitus before positive-pressure ventilation","Airway adjunct + assist ventilations once clear","If re-vomiting: stop, clear, then resume","Transport with suction ready and continuous airway watch"],keyTakeaway:"Gurgling vomit means suction first—never bag debris into the lungs."}),(0,t.sc)({id:"airway-07",title:"Inadequate Ventilations — BVM Technique",category:"airway",difficulty:"foundational",source:t.NATIONAL,dispatch:"46 y/o male, altered mental status, slow breathing after possible seizure. Bystander CPR not started—pulse present.",scene:"Public sidewalk. Bystanders clear a space. No trauma reported. ALS 8 minutes out.",presentation:"Unresponsive, occasional agonal gasps, weak chest rise, cyanosis. Radial pulse present ~50. Jaw slightly clenched but you can open the mouth.",vitals:{hr:50,rr:4,spo2:74,bp:"88/50",skin:"cyanotic",gcs:"3",glucose:"98"},startNodeId:"a07-n1",nodes:[{id:"a07-n1",prompt:"Pulse present but breathing inadequate. Correct action?",options:[{id:"a07-n1-best",text:"Open airway, insert adjunct if appropriate, deliver BVM ventilations with oxygen at a proper rate—do not start compressions solely for bradypnea with a pulse",quality:"best",next:"a07-n2",feedback:"Correct. With a pulse, treat as respiratory failure with assisted ventilation."},{id:"a07-n1-wrong",text:"Withhold ventilation because a pulse means breathing is fine",quality:"incorrect",next:"a07-n2",feedback:"Agonal/slow breaths are not adequate.",delayedCritical:!0},{id:"a07-n1-bad",text:"Perform continuous chest compressions only and never ventilate",quality:"harmful",next:"a07-n2",feedback:"With a pulse, the priority is ventilation; needless compressions can cause injury."},{id:"a07-n1-acc",text:"BVM with oxygen while monitoring pulse closely",quality:"acceptable",next:"a07-n2",feedback:"Acceptable."}]},{id:"a07-n2",prompt:"Your first BVM attempts show poor chest rise and a large mask leak. Fix?",options:[{id:"a07-n2-best",text:"Reposition the airway, improve mask seal (EC clamp), consider two-person BVM, and confirm chest rise",quality:"best",next:"a07-n3",feedback:"Correct. Seal and airway position fix most failed BVM attempts."},{id:"a07-n2-bad",text:"Squeeze as hard and fast as possible regardless of chest rise",quality:"harmful",next:"a07-n3",feedback:"Hyperventilation and gastric inflation worsen outcomes."},{id:"a07-n2-wrong",text:"Abandon ventilations because the first try failed",quality:"incorrect",next:"a07-n3",feedback:"Troubleshoot—don't quit.",delayedCritical:!0},{id:"a07-n2-acc",text:"Switch to two-rescuer BVM technique for a better seal",quality:"acceptable",next:"a07-n3",feedback:"Acceptable and often preferred."}]},{id:"a07-n3",prompt:"Chest rise improves. What ventilation rate concept should guide you (adult)?",options:[{id:"a07-n3-best",text:"Deliver steady breaths that produce visible chest rise about once every 5–6 seconds; avoid over-ventilation",quality:"best",next:"a07-n4",feedback:"Correct. Adult rescue breathing targets roughly 10/min with visible rise—no stacking."},{id:"a07-n3-bad",text:"Ventilate as fast as possible to 'blow off CO₂'",quality:"harmful",next:"a07-n4",feedback:"Excessive rates hurt venous return and increase aspiration/gastric risk."},{id:"a07-n3-wrong",text:"Give one huge breath every 30 seconds only",quality:"incorrect",next:"a07-n4",feedback:"That rate is too slow for an apneic/hypoventilating adult."},{id:"a07-n3-acc",text:"Visible chest rise, controlled rate, continuous pulse checks",quality:"acceptable",next:"a07-n4",feedback:"Acceptable."}]},{id:"a07-n4",prompt:"After two minutes SpO₂ is 93% assisted; pulse still present. Next priority?",vitals:{hr:58,rr:"assisted",spo2:93,bp:"92/56",gcs:"3"},options:[{id:"a07-n4-best",text:"Continue effective ventilations, treat for shock as indicated, rapid transport/ALS intercept",quality:"best",next:"end",feedback:"Correct. Maintain what works and move toward definitive care."},{id:"a07-n4-wrong",text:"Stop BVM because SpO₂ improved and wait on scene",quality:"incorrect",next:"end",feedback:"He still needs ventilatory support.",delayedCritical:!0},{id:"a07-n4-bad",text:"Remove oxygen from the BVM to 'prevent oxygen toxicity' in the field",quality:"harmful",next:"end",feedback:"Acute hypoxic failure needs oxygenated ventilations."},{id:"a07-n4-acc",text:"Maintain BVM/oxygen and package for urgent transport",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["With pulse + inadequate breathing: assist ventilations (not compressions alone)","Fix seal/airway position; prefer two-person BVM if needed","Visible chest rise at an appropriate adult rate—avoid hyperventilation","Continue support and rapid transport/ALS"],keyTakeaway:"Inadequate breathing with a pulse is a BVM problem: seal, rate, visible chest rise, and ongoing oxygen."}),(0,t.sc)({id:"cardiac-01",title:"Chest Pain — Suspected ACS",category:"cardiac",difficulty:"foundational",source:t.NATIONAL,dispatch:"58 y/o male, crushing chest pressure for 20 minutes, sweating. At office desk.",scene:"Office building, conference room. Coworkers present. Elevator access available. No hazards.",presentation:"Pale, diaphoretic, clutching center of chest. Pain radiates to left arm. Denies trauma. History of hypertension. Alert and anxious.",vitals:{hr:96,rr:20,spo2:95,bp:"148/92",skin:"pale, diaphoretic",gcs:"15"},startNodeId:"c01-n1",nodes:[{id:"c01-n1",prompt:"After scene safety, what is your best initial focus?",options:[{id:"c01-n1-best",text:"ABCs, oxygen if needed per protocol, keep at rest, obtain SAMPLE/OPQRST while preparing rapid ALS/ED care",quality:"best",next:"c01-n2",feedback:"Correct. Suspected ACS: limit exertion, support ABCs, focused history, expedite definitive care."},{id:"c01-n1-bad",text:"Have him walk briskly to the ambulance to 'test the heart'",quality:"harmful",next:"c01-n2",feedback:"Exertion can extend infarct or trigger arrest."},{id:"c01-n1-wrong",text:"Ignore chest pain and only bandage a paper cut on his finger",quality:"incorrect",next:"c01-n2",feedback:"Chest pressure with diaphoresis is the life threat.",delayedCritical:!0},{id:"c01-n1-acc",text:"Place at rest, assess ABCs, request ALS",quality:"acceptable",next:"c01-n2",feedback:"Acceptable."}]},{id:"c01-n2",prompt:"He has prescribed nitroglycerin. BP is 148/92, SpO₂ 95%. EMT medication approach?",vitals:{hr:98,rr:20,spo2:95,bp:"148/92"},options:[{id:"c01-n2-best",text:"If protocol allows, assist with his prescribed nitroglycerin only after checking contraindications (e.g., recent ED meds, hypotension); no invented doses",quality:"best",next:"c01-n3",feedback:"Correct. Assist only per protocol with safety checks—never invent a dose."},{id:"c01-n2-bad",text:"Give several tablets based on a dose you invent because pain is severe",quality:"harmful",next:"c01-n3",feedback:"Never invent medication doses."},{id:"c01-n2-wrong",text:"Force him to take a coworker's nitro 'just like his'",quality:"harmful",next:"c01-n3",feedback:"Only the patient's prescribed medication, and only per protocol."},{id:"c01-n2-acc",text:"Oxygen as indicated, aspirin/nitro only if local protocol authorizes EMT assist",quality:"acceptable",next:"c01-n3",feedback:"Acceptable—protocols vary."}]},{id:"c01-n3",prompt:"During assessment he becomes profoundly pale, BP 82/50, still complaining of chest pain. Priority shift?",vitals:{hr:110,rr:24,spo2:93,bp:"82/50",skin:"cool, clammy"},options:[{id:"c01-n3-best",text:"Treat as cardiogenic shock/ACS emergency: keep supine or position of comfort as tolerated, oxygen as needed, rapid transport, ALS—do not give nitro if hypotensive per typical rules",quality:"best",next:"c01-n4",feedback:"Correct. Hypotension changes the plan—support perfusion and move fast."},{id:"c01-n3-bad",text:"Sit him bolt upright and assist more nitro despite hypotension",quality:"harmful",next:"c01-n4",feedback:"Nitro with hypotension can worsen shock."},{id:"c01-n3-wrong",text:"Stay on scene for a complete social history",quality:"incorrect",next:"c01-n4",feedback:"Shocking ACS needs transport now.",delayedCritical:!0},{id:"c01-n3-acc",text:"Withhold nitro due to low BP; high-priority transport",quality:"acceptable",next:"c01-n4",feedback:"Acceptable."}]},{id:"c01-n4",prompt:"Transport decision and notification?",options:[{id:"c01-n4-best",text:"Priority transport to an appropriate ED, early radio report of suspected ACS/shock",quality:"best",next:"end",feedback:"Correct. Time-sensitive cardiac care needs early notification."},{id:"c01-n4-wrong",text:"Take the long scenic route so he can 'relax'",quality:"incorrect",next:"end",feedback:"Delays reperfusion."},{id:"c01-n4-bad",text:"Discharge him on scene because pain briefly lessened",quality:"harmful",next:"end",feedback:"Suspected ACS requires evaluation even if pain fluctuates."},{id:"c01-n4-acc",text:"Lights/siren per protocol, continuous monitoring, ALS intercept if beneficial",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Rest + ABCs + focused ACS assessment","Assist prescribed nitro/aspirin only per protocol with contraindications checked","If hypotensive: stop nitro, support, rapid transport","Priority ED transport with early notification"],keyTakeaway:"Suspected ACS: limit work of the heart, follow protocol for assists, and treat hypotension as a reason to withhold nitro and move faster."}),(0,t.sc)({id:"cardiac-02",title:"Cardiac Arrest — CPR and AED",category:"cardiac",difficulty:"critical",source:t.NATIONAL,dispatch:"Witnessed collapse at gym. Unresponsive, not breathing normally.",scene:"Gym floor cleared. AED on wall. Bystander starting compressions on your arrival.",presentation:"Unresponsive, agonal gasps, no pulse. Adult male ~50s.",vitals:{hr:"none",rr:"agonal",spo2:"n/a",bp:"unobtainable",skin:"cyanotic",gcs:"3"},startNodeId:"c02-n1",nodes:[{id:"c02-n1",prompt:"Confirm arrest. Immediate priority?",options:[{id:"c02-n1-best",text:"Ensure high-quality CPR, apply AED as soon as available, minimize interruptions",quality:"best",next:"c02-n2",feedback:"Correct. Compressions + early defibrillation save lives."},{id:"c02-n1-wrong",text:"Pause everything for a 5-minute detailed history from bystanders",quality:"incorrect",next:"c02-n2",feedback:"Do not delay CPR/AED.",delayedCritical:!0},{id:"c02-n1-bad",text:"Move the patient to the ambulance before any CPR",quality:"harmful",next:"c02-n2",feedback:"Start resuscitation where you find him if safe."},{id:"c02-n1-acc",text:"Take over/coach CPR and send someone for the AED",quality:"acceptable",next:"c02-n2",feedback:"Acceptable."}]},{id:"c02-n2",prompt:"AED analyzes and advises a shock. Correct action?",options:[{id:"c02-n2-best",text:"Clear the patient, deliver shock, then immediately resume CPR starting with compressions",quality:"best",next:"c02-n3",feedback:"Correct. Shock then CPR—do not delay for pulse checks."},{id:"c02-n2-wrong",text:"Check a pulse for a full minute before shocking",quality:"incorrect",next:"c02-n3",feedback:"Follow AED prompts promptly.",delayedCritical:!0},{id:"c02-n2-bad",text:"Shock while a rescuer is still touching the patient",quality:"harmful",next:"c02-n3",feedback:"Clear before defibrillation."},{id:"c02-n2-acc",text:"Clear, shock, resume compressions for about 2 minutes until next analyze",quality:"acceptable",next:"c02-n3",feedback:"Acceptable."}]},{id:"c02-n3",prompt:"During CPR the AED says 'no shock advised.' What now?",options:[{id:"c02-n3-best",text:"Immediately resume high-quality CPR; treat reversible issues as able; continue cycles",quality:"best",next:"c02-n4",feedback:"Correct. No-shock means continue CPR and ALS care—not a reason to stop."},{id:"c02-n3-bad",text:"Stop all resuscitation because no shock was advised",quality:"harmful",next:"c02-n4",feedback:"Asystole/PEA still need CPR."},{id:"c02-n3-wrong",text:"Deliver a shock anyway against AED guidance",quality:"harmful",next:"c02-n4",feedback:"Do not override 'no shock' with unsynchronized guessing."},{id:"c02-n3-acc",text:"Resume CPR and prepare for ALS airway/vascular care",quality:"acceptable",next:"c02-n4",feedback:"Acceptable."}]},{id:"c02-n4",prompt:"After a shock and CPR, signs of life return (pulse, breathing). Next?",sceneUpdate:"Carotid pulse present; spontaneous respirations slow.",options:[{id:"c02-n4-best",text:"Support ABCs, oxygen/ventilations as needed, monitor closely for re-arrest, rapid transport",quality:"best",next:"end",feedback:"Correct. ROSC care is airway, oxygenation, perfusion support, and readiness to restart CPR."},{id:"c02-n4-wrong",text:"Remove oxygen and walk him to the locker room",quality:"harmful",next:"end",feedback:"Post-arrest patients are unstable."},{id:"c02-n4-bad",text:"Sit him up immediately for a sports drink",quality:"harmful",next:"end",feedback:"Risk of aspiration and hemodynamic collapse."},{id:"c02-n4-acc",text:"Post-ROSC monitoring with AED left attached during transport prep",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["High-quality CPR + early AED","Clear, shock if advised, immediate CPR","If no shock: continue CPR cycles","On ROSC: support ABCs and watch for re-arrest"],keyTakeaway:"Arrest care is uninterrupted CPR and AED use—shock when advised, CPR when not, and never stop for a 'no shock' message alone."}),(0,t.sc)({id:"cardiac-03",title:"Symptomatic Bradycardia",category:"cardiac",difficulty:"application",source:t.NATIONAL,dispatch:"81 y/o female, weakness and near-fainting. Caregiver says pulse is 'very slow.'",scene:"Assisted living apartment. Patient in chair. Caregiver present. No trauma.",presentation:"Pale, cool skin, dizzy when sitting forward. Alert but weak. Denies chest pain currently. Possible beta-blocker on med list.",vitals:{hr:38,rr:16,spo2:94,bp:"78/50",skin:"pale, cool",gcs:"15"},startNodeId:"c03-n1",nodes:[{id:"c03-n1",prompt:"HR 38 with hypotension and poor perfusion. Best EMT framing?",options:[{id:"c03-n1-best",text:"Recognize symptomatic bradycardia: support ABCs, oxygen as needed, keep supine if tolerated, rapid ALS/transport—EMTs do not pace or give rate meds unless protocolized",quality:"best",next:"c03-n2",feedback:"Correct. Identify instability and expedite advanced care."},{id:"c03-n1-wrong",text:"Call it 'normal aging' and clear the call without transport",quality:"incorrect",next:"c03-n2",feedback:"Symptomatic bradycardia with shock signs is an emergency.",delayedCritical:!0},{id:"c03-n1-bad",text:"Have her stand and march in place to raise the rate",quality:"harmful",next:"c03-n2",feedback:"Standing may cause syncope."},{id:"c03-n1-acc",text:"Supine, oxygen if indicated, request ALS",quality:"acceptable",next:"c03-n2",feedback:"Acceptable."}]},{id:"c03-n2",prompt:"While waiting for ALS she becomes confused and BP falls to 70/40. Priority?",vitals:{hr:36,rr:12,spo2:91,bp:"70/40",gcs:"13"},options:[{id:"c03-n2-best",text:"Maintain airway, assist ventilations if needed, treat for shock, expedite movement/ALS",quality:"best",next:"c03-n3",feedback:"Correct. Worsening perfusion means escalate support and time to ALS/ED."},{id:"c03-n2-wrong",text:"Start a long secondary head-to-toe before any movement",quality:"incorrect",next:"c03-n3",feedback:"Unstable patients need rapid packaging.",delayedCritical:!0},{id:"c03-n2-bad",text:"Give an invented dose of atropine from a friend's kit",quality:"harmful",next:"c03-n3",feedback:"Never invent doses or use unregulated meds."},{id:"c03-n2-acc",text:"Airway readiness and high-priority transport toward ALS intercept",quality:"acceptable",next:"c03-n3",feedback:"Acceptable."}]},{id:"c03-n3",prompt:"She becomes unresponsive with a weak slow pulse and inadequate breathing. Next?",options:[{id:"c03-n3-best",text:"Open airway and assist ventilations; if pulse becomes absent, begin CPR/AED",quality:"best",next:"c03-n4",feedback:"Correct. Support breathing while pulse present; be ready for arrest."},{id:"c03-n3-wrong",text:"Assume she is sleeping and stop assessments",quality:"harmful",next:"c03-n4",feedback:"Unresponsive + bradycardia needs active management.",delayedCritical:!0},{id:"c03-n3-bad",text:"Deliver an AED shock while a definite pulse is still present without analysis guidance",quality:"harmful",next:"c03-n4",feedback:"Do not shock a perfusing bradycardia."},{id:"c03-n3-acc",text:"BVM support and continuous pulse checks",quality:"acceptable",next:"c03-n4",feedback:"Acceptable."}]},{id:"c03-n4",prompt:"Key handoff point to ALS/ED?",options:[{id:"c03-n4-best",text:"Report rate, signs of poor perfusion, interventions, and trends (mental status/BP)",quality:"best",next:"end",feedback:"Correct. Symptomatic vs asymptomatic hinges on perfusion findings."},{id:"c03-n4-wrong",text:"Only say 'old person tired' without vitals",quality:"incorrect",next:"end",feedback:"Rate and perfusion data are essential."},{id:"c03-n4-bad",text:"Hide that she became unresponsive to avoid paperwork",quality:"harmful",next:"end",feedback:"Honesty in handoff is required."},{id:"c03-n4-acc",text:"Concise SAMPLE plus bradycardia with hypotension timeline",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Identify symptomatic bradycardia and support ABCs","If deteriorating: airway/shock care and rapid ALS","Assist ventilations if needed; CPR if pulseless","Handoff rate + perfusion trends"],keyTakeaway:"Bradycardia matters when perfusion fails—support ABCs and get ALS/ED care rather than inventing rate medications."}),(0,t.sc)({id:"cardiac-04",title:"CHF vs ACS — EMT Differentiation",category:"cardiac",difficulty:"application",source:t.NATIONAL,dispatch:"67 y/o male, shortness of breath and chest discomfort. History of MI and CHF.",scene:"Living room recliner. Wife present. Home meds include a diuretic and antiplatelet.",presentation:"Sitting bolt upright, bilateral crackles, mild frothy sputum, also reports pressure-like chest pain. Ankle edema present. Diaphoretic.",vitals:{hr:112,rr:28,spo2:88,bp:"170/100",skin:"pale, sweaty",gcs:"15"},startNodeId:"c04-n1",nodes:[{id:"c04-n1",prompt:"Both ACS and CHF features are present. What should drive EMT priorities?",options:[{id:"c04-n1-best",text:"Treat the life threats you see: upright posture, oxygen for hypoxia, limit exertion, rapid ALS/ED—do not delay for perfect labeling",quality:"best",next:"c04-n2",feedback:"Correct. Overlapping presentations are common; ABCs and transport matter most at EMT level."},{id:"c04-n1-wrong",text:"Refuse care until you decide a single diagnosis with certainty",quality:"incorrect",next:"c04-n2",feedback:"EMTs manage presentations, not definitive labels.",delayedCritical:!0},{id:"c04-n1-bad",text:"Lay him flat to 'equalize' heart and lung problems",quality:"harmful",next:"c04-n2",feedback:"Flat position worsens pulmonary edema."},{id:"c04-n1-acc",text:"Oxygen, upright, monitor, request ALS",quality:"acceptable",next:"c04-n2",feedback:"Acceptable."}]},{id:"c04-n2",prompt:"Which finding most supports a dominant pulmonary edema/CHF picture right now?",options:[{id:"c04-n2-best",text:"Orthopnea with wet crackles and frothy sputum plus hypoxia while upright",quality:"best",next:"c04-n3",feedback:"Correct. Those point strongly to fluid in the lungs."},{id:"c04-n2-wrong",text:"A healed scar on his knee",quality:"incorrect",next:"c04-n3",feedback:"Irrelevant to the acute respiratory picture."},{id:"c04-n2-bad",text:"Assuming crackles always mean pneumonia so you withhold oxygen",quality:"harmful",next:"c04-n3",feedback:"Hypoxia still needs oxygen."},{id:"c04-n2-acc",text:"Hypertension with acute dyspnea and crackles in a known CHF patient",quality:"acceptable",next:"c04-n3",feedback:"Acceptable supporting picture."}]},{id:"c04-n3",prompt:"Chest pressure continues. Nitro assist consideration?",options:[{id:"c04-n3-best",text:"Follow protocol: assist prescribed nitro only if allowed and BP/contraindications OK; remember hypoxia and positioning remain first-line EMT care",quality:"best",next:"c04-n4",feedback:"Correct. Dual presentation still obeys protocol and ABC priorities."},{id:"c04-n3-bad",text:"Invent a nitro dosing schedule because he 'looks like a textbook MI'",quality:"harmful",next:"c04-n4",feedback:"No invented doses."},{id:"c04-n3-wrong",text:"Ignore SpO₂ 88% to debate ACS vs CHF for ten minutes",quality:"incorrect",next:"c04-n4",feedback:"Oxygenate now.",delayedCritical:!0},{id:"c04-n3-acc",text:"Oxygen/upright care first; medication assist only per protocol",quality:"acceptable",next:"c04-n4",feedback:"Acceptable."}]},{id:"c04-n4",prompt:"Best transport framing?",options:[{id:"c04-n4-best",text:"Priority transport as undifferentiated cardiac/respiratory emergency with ongoing oxygen and monitoring",quality:"best",next:"end",feedback:"Correct. ED/ALS will refine the diagnosis."},{id:"c04-n4-wrong",text:"Cancel ALS because you 'mostly think it is CHF'",quality:"incorrect",next:"end",feedback:"He remains unstable."},{id:"c04-n4-bad",text:"Encourage him to shower before leaving",quality:"harmful",next:"end",feedback:"Delays care and risks collapse."},{id:"c04-n4-acc",text:"Early notification describing both chest pain and pulmonary edema signs",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["ABCs/upright/oxygen without forcing a single label","Use crackles/orthopnea/froth as CHF-leaning clues","Med assists only per protocol after ABCs","Priority transport as cardiac-respiratory emergency"],keyTakeaway:"ACS and CHF often overlap—treat hypoxia and perfusion threats first; perfect labeling is not required to act."}),(0,t.sc)({id:"cardiac-05",title:"Syncope — Scene to Transport",category:"cardiac",difficulty:"foundational",source:t.NATIONAL,dispatch:"42 y/o female fainted at church, now awake. Bystanders say brief seizure-like jerking.",scene:"Church aisle. Patient sitting on floor against a pew. Crowd controlled by ushers.",presentation:"Now alert, embarrassed, pale. Remembers standing then 'blacking out.' No incontinence. Denies ongoing chest pain. Slightly tachycardic.",vitals:{hr:104,rr:18,spo2:98,bp:"100/68",skin:"pale",gcs:"15",glucose:"92"},startNodeId:"c05-n1",nodes:[{id:"c05-n1",prompt:"First priorities after scene safety?",options:[{id:"c05-n1-best",text:"ABCs, spinal considerations only if trauma mechanism, glucose check, history of prodrome, and cardiac risk screening",quality:"best",next:"c05-n2",feedback:"Correct. Syncope workup starts with life threats and causes you can find in the field."},{id:"c05-n1-wrong",text:"Immediately full spinal immobilization solely because she fainted",quality:"incorrect",next:"c05-n2",feedback:"Syncope alone is not automatic spinal immobilization without trauma indicators."},{id:"c05-n1-bad",text:"Have her stand quickly to prove she is fine",quality:"harmful",next:"c05-n2",feedback:"Risk of recurrent syncope."},{id:"c05-n1-acc",text:"Keep supine/sitting supported while assessing ABCs and glucose",quality:"acceptable",next:"c05-n2",feedback:"Acceptable."}]},{id:"c05-n2",prompt:"Bystanders describe brief jerking after she hit the floor. Best interpretation at EMT level?",options:[{id:"c05-n2-best",text:"Treat as syncope with possible convulsive activity from hypoxia/hypotension—still needs medical evaluation; do not dismiss as 'just a seizure' without assessment",quality:"best",next:"c05-n3",feedback:"Correct. Convulsive syncope happens; evaluate fully and transport."},{id:"c05-n2-wrong",text:"Clear the scene without vitals because she is talking",quality:"incorrect",next:"c05-n3",feedback:"Syncope warrants evaluation."},{id:"c05-n2-bad",text:"Force oral fluids while she is still pale and nauseated",quality:"harmful",next:"c05-n3",feedback:"Aspiration risk if she faints again."},{id:"c05-n2-acc",text:"Document witness account and continue cardiac/neuro assessment",quality:"acceptable",next:"c05-n3",feedback:"Acceptable."}]},{id:"c05-n3",prompt:"She wants to refuse transport. Capacity and counseling?",options:[{id:"c05-n3-best",text:"Assess decision-making capacity, explain risks of cardiac syncope, encourage transport, involve medical control/protocol if refusing",quality:"best",next:"c05-n4",feedback:"Correct. Informed refusal requires capacity plus clear risk explanation."},{id:"c05-n3-bad",text:"Forge her signature on a refusal and leave",quality:"harmful",next:"c05-n4",feedback:"Fraudulent and dangerous."},{id:"c05-n3-wrong",text:"Physically force her onto the stretcher without legal/ethical basis",quality:"harmful",next:"c05-n4",feedback:"Alert refusing patients with capacity have rights—use proper process."},{id:"c05-n3-acc",text:"Strongly recommend ED evaluation for first-time syncope with unknown cause",quality:"acceptable",next:"c05-n4",feedback:"Acceptable."}]},{id:"c05-n4",prompt:"She agrees to go. En route BP is 88/56 and she feels like fainting again. Action?",vitals:{hr:120,rr:22,spo2:96,bp:"88/56"},options:[{id:"c05-n4-best",text:"Supine, elevate legs if appropriate, oxygen as needed, treat for shock, update hospital, watch airway",quality:"best",next:"end",feedback:"Correct. Recurrent near-syncope with hypotension is unstable."},{id:"c05-n4-wrong",text:"Sit her fully upright for the view",quality:"harmful",next:"end",feedback:"Worsens cerebral perfusion."},{id:"c05-n4-bad",text:"Ignore vitals because the church service is ending",quality:"incorrect",next:"end",feedback:"Reassess continuously.",delayedCritical:!0},{id:"c05-n4-acc",text:"Shock position as tolerated and rapid notification",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["ABCs, glucose, syncope history—not automatic full spinal","Don't dismiss convulsive syncope","Capacity-based refusal counseling","If hypotensive again: shock care and notify"],keyTakeaway:"Syncope is a symptom—rule out life threats, advise transport, and treat recurrent hypotension as an emergency."}),(0,t.sc)({id:"cardiac-06",title:"ROSC Care Basics",category:"cardiac",difficulty:"critical",source:t.NATIONAL,dispatch:"You regain a pulse after AED shock and CPR on a 61 y/o male in a parking lot.",scene:"Store parking lot. Safe. ALS 5 minutes out. AED pads still on chest.",presentation:"Pulse present ~70, unresponsive, shallow irregular breathing. Skin mottled. No obvious trauma.",vitals:{hr:70,rr:6,spo2:85,bp:"90/60",skin:"mottled",gcs:"3",etco2:"if available"},startNodeId:"c06-n1",nodes:[{id:"c06-n1",prompt:"Immediate post-ROSC priority?",options:[{id:"c06-n1-best",text:"Support airway and assist ventilations with oxygen; do not remove AED pads; prepare for possible re-arrest",quality:"best",next:"c06-n2",feedback:"Correct. Airway/breathing and readiness to restart CPR define early ROSC care."},{id:"c06-n1-wrong",text:"Celebrate and stop all monitoring",quality:"incorrect",next:"c06-n2",feedback:"Re-arrest is common.",delayedCritical:!0},{id:"c06-n1-bad",text:"Sit him up and offer oral water",quality:"harmful",next:"c06-n2",feedback:"Unresponsive—aspiration risk."},{id:"c06-n1-acc",text:"BVM/oxygen and continuous pulse checks with pads left in place",quality:"acceptable",next:"c06-n2",feedback:"Acceptable."}]},{id:"c06-n2",prompt:"Ventilations are ongoing. BP 90/60. Best EMT supportive care?",options:[{id:"c06-n2-best",text:"Maintain oxygenation/ventilation, keep supine, gentle handling, rapid transport/ALS—avoid hyperventilation",quality:"best",next:"c06-n3",feedback:"Correct. Stable support beats aggressive over-ventilation."},{id:"c06-n2-bad",text:"Hyperventilate as fast as possible",quality:"harmful",next:"c06-n3",feedback:"Hyperventilation harms post-arrest hemodynamics."},{id:"c06-n2-wrong",text:"Delay transport to deep-clean the ambulance first",quality:"incorrect",next:"c06-n3",feedback:"Move toward definitive care.",delayedCritical:!0},{id:"c06-n2-acc",text:"Controlled ventilations and urgent ALS intercept",quality:"acceptable",next:"c06-n3",feedback:"Acceptable."}]},{id:"c06-n3",prompt:"Pulse suddenly disappears again. Action?",sceneUpdate:"Carotid pulse absent; no breathing.",options:[{id:"c06-n3-best",text:"Resume high-quality CPR and use the AED as indicated",quality:"best",next:"c06-n4",feedback:"Correct. Return to arrest algorithm immediately."},{id:"c06-n3-wrong",text:"Wait three minutes to 'see if the pulse comes back'",quality:"incorrect",next:"c06-n4",feedback:"Start CPR now.",delayedCritical:!0},{id:"c06-n3-bad",text:"Pour water on the chest instead of compressing",quality:"harmful",next:"c06-n4",feedback:"Not a resuscitation method."},{id:"c06-n3-acc",text:"CPR + AED analyze/shock sequence again",quality:"acceptable",next:"c06-n4",feedback:"Acceptable."}]},{id:"c06-n4",prompt:"After another shock, ROSC returns. Transport note?",options:[{id:"c06-n4-best",text:"Notify receiving facility of arrest-to-ROSC timeline, shocks, and current ABCs; continue close monitoring",quality:"best",next:"end",feedback:"Correct. Clear timelines help ED post-arrest care."},{id:"c06-n4-wrong",text:"Omit that he re-arrested to keep the report short",quality:"harmful",next:"end",feedback:"Critical information must be reported."},{id:"c06-n4-bad",text:"Remove pads so the ED can 'start fresh' without history",quality:"incorrect",next:"end",feedback:"Leave pads on unless directed otherwise; communicate care given."},{id:"c06-n4-acc",text:"Concise ROSC handoff with ongoing ventilatory support",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Airway/ventilation support; keep AED ready","Avoid hyperventilation; rapid ALS/ED","If re-arrest: immediate CPR/AED","Report arrest timeline accurately"],keyTakeaway:"ROSC is unstable—oxygenate carefully, watch for re-arrest, and hand off a clear resuscitation timeline."}),(0,t.sc)({id:"cardiac-07",title:"AED Shockable vs Continue CPR",category:"cardiac",difficulty:"foundational",source:t.NATIONAL,dispatch:"Nursing home, cardiac arrest. Staff performing CPR. AED connected by your partner.",scene:"Resident room. Clear space. Staff rotating compressors. ALS en route.",presentation:"Elderly male, pulseless, apneic. CPR in progress with visible chest recoil coached.",vitals:{hr:"none",rr:"none",spo2:"n/a",bp:"unobtainable",gcs:"3"},startNodeId:"c07-n1",nodes:[{id:"c07-n1",prompt:"AED charges for a shock. Team coordination?",options:[{id:"c07-n1-best",text:"Pause compressions briefly only to clear and shock, then resume compressions immediately",quality:"best",next:"c07-n2",feedback:"Correct. Minimize the pause around defibrillation."},{id:"c07-n1-wrong",text:"Take a prolonged break to discuss lunch after the shock tone",quality:"incorrect",next:"c07-n2",feedback:"Long pauses kill.",delayedCritical:!0},{id:"c07-n1-bad",text:"Shock without clearing because CPR is 'more important'",quality:"harmful",next:"c07-n2",feedback:"Rescuers must be clear of the patient for the shock."},{id:"c07-n1-acc",text:"Clear, shock, compressions within seconds",quality:"acceptable",next:"c07-n2",feedback:"Acceptable."}]},{id:"c07-n2",prompt:"Next analyze: 'No shock advised.' Correct understanding?",options:[{id:"c07-n2-best",text:"Resume CPR immediately—nonshockable rhythms still require high-quality compressions and ventilations",quality:"best",next:"c07-n3",feedback:"Correct. No shock ≠ stop."},{id:"c07-n2-bad",text:"End the code solely because the AED will not shock",quality:"harmful",next:"c07-n3",feedback:"Continue CPR until ROSC, valid termination order, or transfer of care."},{id:"c07-n2-wrong",text:"Deliver three stacked shocks against the prompt",quality:"harmful",next:"c07-n3",feedback:"Follow AED guidance."},{id:"c07-n2-acc",text:"CPR for ~2 minutes then reanalyze",quality:"acceptable",next:"c07-n3",feedback:"Acceptable."}]},{id:"c07-n3",prompt:"Compressions look shallow and too slow. Coaching?",options:[{id:"c07-n3-best",text:"Coach rate ~100–120, depth ~2 inches adult, full recoil, minimize interruptions, rotate compressors",quality:"best",next:"c07-n4",feedback:"Correct. Quality metrics matter as much as the algorithm."},{id:"c07-n3-wrong",text:"Say nothing because criticism is rude",quality:"incorrect",next:"c07-n4",feedback:"Patient-centered coaching is required."},{id:"c07-n3-bad",text:"Order compressions at 40/min to 'rest the heart'",quality:"harmful",next:"c07-n4",feedback:"Too slow is ineffective."},{id:"c07-n3-acc",text:"Rotate every 2 minutes and correct depth/recoil in real time",quality:"acceptable",next:"c07-n4",feedback:"Acceptable."}]},{id:"c07-n4",prompt:"AED again advises shock. You notice a medication patch under a pad site. Action?",options:[{id:"c07-n4-best",text:"If safe and does not cause a long delay, remove the patch and wipe the area, then apply pad and shock as advised",quality:"best",next:"end",feedback:"Correct. Patches can interfere with pads/energy—address quickly without abandoning the algorithm."},{id:"c07-n4-wrong",text:"Never shock again because a patch exists, even after removal is possible",quality:"incorrect",next:"end",feedback:"Remove/wipe and proceed.",delayedCritical:!0},{id:"c07-n4-bad",text:"Shock through a thick pool of water on the chest without drying",quality:"harmful",next:"end",feedback:"Dry the chest; avoid shocking in standing water hazards."},{id:"c07-n4-acc",text:"Quickly move pad to an appropriate dry area if patch cannot be removed instantly",quality:"acceptable",next:"end",feedback:"Acceptable alternative."}]}],correctSequence:["Clear-shock-CPR with minimal pause","No shock → continue CPR","Coach high-quality compressions","Address patches/wet chest quickly, then defibrillate if advised"],keyTakeaway:"Shock when the AED advises; when it does not, high-quality CPR continues without delay."}),(0,t.sc)({id:"medical-01",title:"Hypoglycemia — Altered Diabetic",category:"medical",difficulty:"foundational",source:t.NATIONAL,dispatch:"29 y/o diabetic, acting confused at work. Coworkers say he skipped lunch after insulin.",scene:"Office break room. Patient seated, sweaty, confused. No trauma. Manager present.",presentation:"Diaphoretic, tachycardic, confused to place/time but can swallow with coaching. Speaks slurred words. Medic alert bracelet: insulin-dependent diabetes.",vitals:{hr:118,rr:20,spo2:98,bp:"122/78",skin:"cool, diaphoretic",gcs:"13",glucose:"42"},startNodeId:"m01-n1",nodes:[{id:"m01-n1",prompt:"After ABCs, what confirms your suspicion and guides treatment?",options:[{id:"m01-n1-best",text:"Check blood glucose promptly in any altered diabetic/unknown AMS",quality:"best",next:"m01-n2",feedback:"Correct. Glucose is a rapid, actionable field test."},{id:"m01-n1-wrong",text:"Skip glucose and assume stroke only",quality:"incorrect",next:"m01-n2",feedback:"Hypoglycemia mimics stroke—check sugar.",delayedCritical:!0},{id:"m01-n1-bad",text:"Give an invented IV dextrose concentration as an EMT without protocol/authorization",quality:"harmful",next:"m01-n2",feedback:"Stay within EMT scope and never invent doses."},{id:"m01-n1-acc",text:"SAMPLE plus immediate glucose reading",quality:"acceptable",next:"m01-n2",feedback:"Acceptable."}]},{id:"m01-n2",prompt:"Glucose is 42; patient can protect airway and follow commands to swallow. Best treatment path?",options:[{id:"m01-n2-best",text:"Give oral glucose per protocol if able to swallow/protect airway; reassess mental status and glucose",quality:"best",next:"m01-n3",feedback:"Correct. Oral glucose is appropriate when the airway is protected."},{id:"m01-n2-bad",text:"Force oral gel into an unresponsive patient's mouth",quality:"harmful",next:"m01-n3",feedback:"Aspiration risk—unresponsive patients need ALS route options, not oral sugar."},{id:"m01-n2-wrong",text:"Withhold sugar because 'he needs to learn a lesson'",quality:"incorrect",next:"m01-n3",feedback:"Treat hypoglycemia now.",delayedCritical:!0},{id:"m01-n2-acc",text:"Oral glucose per protocol and request ALS if no improvement",quality:"acceptable",next:"m01-n3",feedback:"Acceptable."}]},{id:"m01-n3",prompt:"After oral glucose he improves to GCS 15. He wants to refuse transport. Consideration?",vitals:{hr:90,rr:16,spo2:98,bp:"124/80",gcs:"15",glucose:"96"},options:[{id:"m01-n3-best",text:"Reassess, explain recurrence risk, follow protocol/medical control for diabetic refusal criteria, document thoroughly",quality:"best",next:"m01-n4",feedback:"Correct. Improvement does not automatically equal safe refusal—follow local rules."},{id:"m01-n3-bad",text:"Leave without documenting because he looks fine",quality:"harmful",next:"m01-n4",feedback:"Documentation and counseling are required."},{id:"m01-n3-wrong",text:"Force another full tube of glucose against his will after full recovery without indication",quality:"incorrect",next:"m01-n4",feedback:"Treat based on need and protocol; respect capacity once recovered."},{id:"m01-n3-acc",text:"Encourage ED eval especially if on insulin with unclear cause",quality:"acceptable",next:"m01-n4",feedback:"Acceptable."}]},{id:"m01-n4",prompt:"If instead he had been unresponsive with glucose 42, EMT priority would be?",options:[{id:"m01-n4-best",text:"Airway protection and ALS for parenteral sugar/glucagon per protocol—do not give oral glucose",quality:"best",next:"end",feedback:"Correct. Unresponsive hypoglycemics need airway first and advanced glucose routes."},{id:"m01-n4-bad",text:"Pour syrup into the unresponsive airway",quality:"harmful",next:"end",feedback:"Aspiration hazard."},{id:"m01-n4-wrong",text:"Wait without airway support",quality:"incorrect",next:"end",feedback:"Protect ABCs.",delayedCritical:!0},{id:"m01-n4-acc",text:"Manage airway, request ALS, transport rapidly",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Check glucose in AMS","Oral glucose only if able to swallow/protect airway","Counsel/document after improvement per protocol","Unresponsive: airway + ALS parenteral options—not oral sugar"],keyTakeaway:"Hypoglycemia: confirm with glucose, use oral sugar only when the airway is safe, and escalate when the patient cannot swallow."}),(0,t.sc)({id:"medical-02",title:"Stroke — FAST Recognition",category:"medical",difficulty:"foundational",source:t.NATIONAL,dispatch:"72 y/o female, sudden right-sided weakness and slurred speech. Last known well 45 minutes ago.",scene:"Kitchen at home. Husband present. Patient seated in chair. No fall trauma noted.",presentation:"Facial droop left, arm drift right, speech slurred. Alert, anxious. Denies headache currently. Blood glucose pending.",vitals:{hr:88,rr:16,spo2:97,bp:"178/96",skin:"warm, dry",gcs:"15",glucose:"118"},startNodeId:"m02-n1",nodes:[{id:"m02-n1",prompt:"Best immediate assessment tool?",options:[{id:"m02-n1-best",text:"Perform a stroke scale (FAST/CPSS), note last known well, check glucose, support ABCs",quality:"best",next:"m02-n2",feedback:"Correct. Time last known well and glucose are critical."},{id:"m02-n1-wrong",text:"Wait an hour on scene to see if symptoms resolve",quality:"incorrect",next:"m02-n2",feedback:"Stroke is time-sensitive.",delayedCritical:!0},{id:"m02-n1-bad",text:"Give aspirin on your own invented indication for every facial droop without protocol",quality:"harmful",next:"m02-n2",feedback:"Do not invent stroke medication plans—follow protocol; many strokes are hemorrhagic."},{id:"m02-n1-acc",text:"FAST exam plus glucose and rapid transport planning",quality:"acceptable",next:"m02-n2",feedback:"Acceptable."}]},{id:"m02-n2",prompt:"Glucose is normal. Transport destination concept?",options:[{id:"m02-n2-best",text:"Rapid transport to an appropriate stroke-capable facility per local plan; early notification with last known well",quality:"best",next:"m02-n3",feedback:"Correct. Notify with timeline so the stroke team can activate."},{id:"m02-n2-wrong",text:"Take the farthest hospital because traffic looks interesting",quality:"incorrect",next:"m02-n3",feedback:"Follow stroke destination protocols."},{id:"m02-n2-bad",text:"Encourage her to sleep until tomorrow's clinic",quality:"harmful",next:"m02-n3",feedback:"Delays reperfusion windows."},{id:"m02-n2-acc",text:"Priority move with stroke alert radio report",quality:"acceptable",next:"m02-n3",feedback:"Acceptable."}]},{id:"m02-n3",prompt:"She begins to vomit and becomes drowsier. Priority?",vitals:{hr:92,rr:14,spo2:94,bp:"190/100",gcs:"12"},options:[{id:"m02-n3-best",text:"Protect airway (position/suction), assist ventilations if needed, continue rapid transport",quality:"best",next:"m02-n4",feedback:"Correct. Airway threats trump further neurologic testing."},{id:"m02-n3-wrong",text:"Keep her fully supine without suction readiness while you re-do FAST three times",quality:"incorrect",next:"m02-n4",feedback:"Airway first.",delayedCritical:!0},{id:"m02-n3-bad",text:"Force oral contrast drink for 'better scans later'",quality:"harmful",next:"m02-n4",feedback:"NPO—aspiration risk."},{id:"m02-n3-acc",text:"Suction ready at the head, lateral if needed, high priority",quality:"acceptable",next:"m02-n4",feedback:"Acceptable."}]},{id:"m02-n4",prompt:"Key radio report elements?",options:[{id:"m02-n4-best",text:"Age, last known well time, stroke scale findings, glucose, deficits, ETA",quality:"best",next:"end",feedback:"Correct. Time and deficits drive ED activation."},{id:"m02-n4-wrong",text:"Only say 'sick elderly' without times",quality:"incorrect",next:"end",feedback:"Last known well is essential."},{id:"m02-n4-bad",text:"Invent a medication dose you already gave",quality:"harmful",next:"end",feedback:"Never fabricate care."},{id:"m02-n4-acc",text:"Stroke alert with LKW and FAST positives",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["FAST + glucose + last known well","Stroke-capable destination with early notify","Airway protection if vomiting/drowsiness","Report LKW, findings, glucose, ETA"],keyTakeaway:"Stroke care is recognition, glucose check, and rapid transport with a precise last-known-well time."}),(0,t.sc)({id:"medical-03",title:"Anaphylaxis",category:"medical",difficulty:"critical",source:t.NATIONAL,dispatch:"22 y/o, allergic reaction after bee sting at park. Difficulty breathing and swelling.",scene:"Picnic area. Safe. Friend holding an epinephrine auto-injector prescribed to the patient.",presentation:"Urticaria, lip/tongue swelling, wheezing, anxious. Speaks in short phrases. Known bee allergy.",vitals:{hr:130,rr:28,spo2:91,bp:"88/58",skin:"flushed with hives",gcs:"15"},startNodeId:"m03-n1",nodes:[{id:"m03-n1",prompt:"This presentation indicates?",options:[{id:"m03-n1-best",text:"Anaphylaxis: multi-system involvement with respiratory and/or perfusion compromise—treat immediately",quality:"best",next:"m03-n2",feedback:"Correct. Hypotension + airway/breathing signs after allergen = anaphylaxis."},{id:"m03-n1-wrong",text:"Simple localized sting—observe for hours on a bench",quality:"incorrect",next:"m03-n2",feedback:"Systemic signs require emergency treatment.",delayedCritical:!0},{id:"m03-n1-bad",text:"Have her run laps to 'work out the venom'",quality:"harmful",next:"m03-n2",feedback:"Worsens shock and swelling."},{id:"m03-n1-acc",text:"Recognize anaphylaxis and prepare epinephrine assist per protocol",quality:"acceptable",next:"m03-n2",feedback:"Acceptable."}]},{id:"m03-n2",prompt:"Friend offers her prescribed epinephrine auto-injector. Correct EMT action?",options:[{id:"m03-n2-best",text:"Confirm it is prescribed to her and assist administration per protocol; support airway/oxygen; no invented doses",quality:"best",next:"m03-n3",feedback:"Correct. Auto-injector assist is protocol-driven—never invent a dose."},{id:"m03-n2-bad",text:"Draw up an invented epinephrine concentration from a vial without authority",quality:"harmful",next:"m03-n3",feedback:"Outside typical EMT practice and dose invention is forbidden here."},{id:"m03-n2-wrong",text:"Withhold epinephrine despite anaphylaxis to 'wait and see'",quality:"incorrect",next:"m03-n3",feedback:"Delay risks airway obstruction and arrest.",delayedCritical:!0},{id:"m03-n2-acc",text:"Assist auto-injector per protocol while applying oxygen",quality:"acceptable",next:"m03-n3",feedback:"Acceptable."}]},{id:"m03-n3",prompt:"After epinephrine assist, wheezing persists and BP is still low. Next?",vitals:{hr:140,rr:30,spo2:90,bp:"84/50"},options:[{id:"m03-n3-best",text:"Maintain oxygen/positioning, rapid transport, ALS intercept; further dosing only per protocol",quality:"best",next:"m03-n4",feedback:"Correct. Ongoing support and advanced care—do not freelance dosing."},{id:"m03-n3-bad",text:"Give repeated unknown quantities of epinephrine by feel",quality:"harmful",next:"m03-n4",feedback:"No invented dosing."},{id:"m03-n3-wrong",text:"Remove oxygen because she received a medication",quality:"incorrect",next:"m03-n4",feedback:"Hypoxia still needs oxygen."},{id:"m03-n3-acc",text:"Airway readiness and priority transport",quality:"acceptable",next:"m03-n4",feedback:"Acceptable."}]},{id:"m03-n4",prompt:"Tongue swelling worsens; stridor appears. Priority?",sceneUpdate:"Inspiratory stridor now audible.",options:[{id:"m03-n4-best",text:"Airway crisis: high-flow oxygen, prepare to assist ventilations if needed, do not delay transport/ALS",quality:"best",next:"end",feedback:"Correct. Impending obstruction needs airway support and definitive care."},{id:"m03-n4-wrong",text:"Oral exam with repeated tongue depressor probing for fun",quality:"harmful",next:"end",feedback:"Can worsen obstruction."},{id:"m03-n4-bad",text:"Lay flat without airway plan while swelling progresses",quality:"harmful",next:"end",feedback:"Position of comfort/airway watch; prepare to act."},{id:"m03-n4-acc",text:"Minimize scene time; continuous airway reassessment",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Recognize anaphylaxis","Assist prescribed epinephrine auto-injector per protocol","Continue support; no freelance dosing","Treat evolving airway threat urgently"],keyTakeaway:"Anaphylaxis needs early epinephrine assist per protocol plus oxygen—airway swelling can progress rapidly."}),(0,t.sc)({id:"medical-04",title:"Seizure — Postictal Care",category:"medical",difficulty:"application",source:t.NATIONAL,dispatch:"Active seizure reported in grocery aisle. Now possibly postictal.",scene:"Grocery store. Crowd held back. Patient on floor, no major trauma apparent. Family says epilepsy history.",presentation:"On arrival: generalized tonic-clonic ending. Then snoring, unresponsive, incontinent. Bloody saliva from bitten tongue.",vitals:{hr:120,rr:24,spo2:90,bp:"150/90",skin:"cyanotic then improving",gcs:"6",glucose:"pending"},startNodeId:"m04-n1",nodes:[{id:"m04-n1",prompt:"During the final seconds of seizing, your priority is?",options:[{id:"m04-n1-best",text:"Protect from injury, do not restrain forcefully, do not put objects in the mouth, prepare suction/oxygen",quality:"best",next:"m04-n2",feedback:"Correct. Protect and prepare—never pry the mouth open with hard objects."},{id:"m04-n1-bad",text:"Force a spoon between the teeth",quality:"harmful",next:"m04-n2",feedback:"Causes dental trauma and aspiration risk."},{id:"m04-n1-wrong",text:"Pile people on the patient to stop movement",quality:"harmful",next:"m04-n2",feedback:"Injury risk."},{id:"m04-n1-acc",text:"Clear hazards and time the seizure",quality:"acceptable",next:"m04-n2",feedback:"Acceptable."}]},{id:"m04-n2",prompt:"Postictal with snoring and SpO₂ 90%. Best airway step?",options:[{id:"m04-n2-best",text:"Recovery position if no trauma contraindication, suction as needed, oxygen, consider NPA if indicated",quality:"best",next:"m04-n3",feedback:"Correct. Postictal airways often need positioning and oxygen."},{id:"m04-n2-wrong",text:"Leave supine without airway support",quality:"incorrect",next:"m04-n3",feedback:"Snoring needs intervention.",delayedCritical:!0},{id:"m04-n2-bad",text:"Oral water to 'wake them up'",quality:"harmful",next:"m04-n3",feedback:"Aspiration."},{id:"m04-n2-acc",text:"Open airway, oxygen, suction readiness",quality:"acceptable",next:"m04-n3",feedback:"Acceptable."}]},{id:"m04-n3",prompt:"Glucose is 70. Family asks if she can refuse once she wakes a little. Approach?",vitals:{hr:100,rr:16,spo2:96,bp:"140/88",gcs:"12",glucose:"70"},options:[{id:"m04-n3-best",text:"Continue reassessment; capacity may be impaired postictally—encourage transport; follow refusal protocols carefully",quality:"best",next:"m04-n4",feedback:"Correct. Postictal patients often lack full capacity initially."},{id:"m04-n3-bad",text:"Accept a mumbled refusal without assessing capacity",quality:"harmful",next:"m04-n4",feedback:"Must assess capacity."},{id:"m04-n3-wrong",text:"Invent a sedative dose to keep her quiet",quality:"harmful",next:"m04-n4",feedback:"No invented meds."},{id:"m04-n3-acc",text:"Reassess mental status frequently and transport if first/prolonged/atypical seizure",quality:"acceptable",next:"m04-n4",feedback:"Acceptable."}]},{id:"m04-n4",prompt:"She has a second seizure lasting >5 minutes without regaining consciousness. Priority?",options:[{id:"m04-n4-best",text:"Treat as status epilepticus emergency: protect airway, oxygen/BVM as needed, rapid ALS/ED",quality:"best",next:"end",feedback:"Correct. Prolonged/recurrent seizures without recovery need ALS."},{id:"m04-n4-wrong",text:"Wait another 20 minutes on scene without support",quality:"incorrect",next:"end",feedback:"Status is time-critical.",delayedCritical:!0},{id:"m04-n4-bad",text:"Hold breath with the patient 'in solidarity'",quality:"harmful",next:"end",feedback:"Not care."},{id:"m04-n4-acc",text:"Airway support and ALS for anticonvulsant therapy per their scope",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Protect during seizure—nothing in the mouth","Postictal: position, suction, oxygen","Capacity may be impaired—encourage transport","Status/recurrent: airway + ALS urgently"],keyTakeaway:"Seizure care is protect, then open the postictal airway—prolonged seizures need ALS without delay."}),(0,t.sc)({id:"medical-05",title:"Opioid Overdose — Medical Focus",category:"medical",difficulty:"application",source:t.NATIONAL,dispatch:"Suspected opioid overdose, unresponsive in car. Breathing slow.",scene:"Parked car, engine off. PD on scene, scene safe. Empty pill bottles and powder residue noted.",presentation:"Pinpoint pupils, cyanosis, RR 5, pulse present. Unresponsive to pain initially.",vitals:{hr:48,rr:5,spo2:76,bp:"100/62",skin:"cyanotic",gcs:"3",glucose:"108"},startNodeId:"m05-n1",nodes:[{id:"m05-n1",prompt:"Priority order?",options:[{id:"m05-n1-best",text:"Airway opening and BVM ventilations with oxygen first; naloxone per protocol as adjunct",quality:"best",next:"m05-n2",feedback:"Correct. Same principle as airway scenarios—breathe for the patient."},{id:"m05-n1-wrong",text:"Only take photos of the pills before any care",quality:"incorrect",next:"m05-n2",feedback:"Treat life threats first.",delayedCritical:!0},{id:"m05-n1-bad",text:"Withhold ventilations until naloxone arrives from across town",quality:"harmful",next:"m05-n2",feedback:"Ventilate now."},{id:"m05-n1-acc",text:"BVM now; naloxone per protocol when available",quality:"acceptable",next:"m05-n2",feedback:"Acceptable."}]},{id:"m05-n2",prompt:"Naloxone is given per protocol. Patient wakes combative. Safety?",sceneUpdate:"Patient thrashing, SpO₂ rising with oxygen.",options:[{id:"m05-n2-best",text:"Ensure crew safety, reassess ABCs, de-escalate verbally, expect possible renarcotization",quality:"best",next:"m05-n3",feedback:"Correct. Agitation can follow reversal—stay safe and keep assessing."},{id:"m05-n2-bad",text:"Immediately tackle and choke the patient",quality:"harmful",next:"m05-n3",feedback:"Unnecessary force."},{id:"m05-n2-wrong",text:"Walk away leaving an unprotected airway patient alone in the car",quality:"incorrect",next:"m05-n3",feedback:"Continue care/monitoring."},{id:"m05-n2-acc",text:"Calm approach, space, ongoing vitals",quality:"acceptable",next:"m05-n3",feedback:"Acceptable."}]},{id:"m05-n3",prompt:"He refuses hospital. Capacity assessment essentials?",vitals:{hr:90,rr:14,spo2:97,bp:"118/76",gcs:"15"},options:[{id:"m05-n3-best",text:"Assess orientation/understanding of risks including recurrent apnea; follow refusal protocol; do not abandon unsafe process",quality:"best",next:"m05-n4",feedback:"Correct. Informed refusal after OD is high-risk—do it carefully."},{id:"m05-n3-bad",text:"Forge documents stating he was never unresponsive",quality:"harmful",next:"m05-n4",feedback:"Falsification is unethical/illegal."},{id:"m05-n3-wrong",text:"Ignore hypoxia recurrence risk in counseling",quality:"incorrect",next:"m05-n4",feedback:"Must explain renarcotization."},{id:"m05-n3-acc",text:"Encourage transport; document mental status and warnings",quality:"acceptable",next:"m05-n4",feedback:"Acceptable."}]},{id:"m05-n4",prompt:"While signing refusal paperwork he becomes unresponsive again. Action?",options:[{id:"m05-n4-best",text:"Return to airway/BVM support and protocol naloxone/ALS; refusal is moot if capacity lost",quality:"best",next:"end",feedback:"Correct. Lost capacity + hypoventilation = treat."},{id:"m05-n4-wrong",text:"Continue the refusal form while he is apneic",quality:"harmful",next:"end",feedback:"Treat first.",delayedCritical:!0},{id:"m05-n4-bad",text:"Assume faking without checking breathing",quality:"harmful",next:"end",feedback:"Verify ABCs."},{id:"m05-n4-acc",text:"Airway, ventilate, reassess",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Ventilate first; naloxone as adjunct","Manage post-reversal agitation safely","High-risk refusal counseling with capacity checks","If unresponsive again: restart airway care"],keyTakeaway:"Opioid OD care is ventilation-first; naloxone helps but patients can crash again—capacity and ABCs rule refusals."}),(0,t.sc)({id:"medical-06",title:"DKA Recognition",category:"medical",difficulty:"application",source:t.NATIONAL,dispatch:"17 y/o, weakness, vomiting, rapid breathing. Mother says new excessive thirst for a week.",scene:"Bedroom at home. Patient on bed. Sweet/fruity odor noted. No trauma.",presentation:"Ill-appearing, dry mucous membranes, Kussmaul respirations, abdominal pain, altered but arousable. Polyuria/polydipsia history.",vitals:{hr:128,rr:32,spo2:98,bp:"100/70",skin:"dry, warm",temp:"99.0°F",gcs:"14",glucose:"HIGH / >500"},startNodeId:"m06-n1",nodes:[{id:"m06-n1",prompt:"Pattern recognition points to?",options:[{id:"m06-n1-best",text:"Suspected DKA/hyperglycemic emergency: dehydration + Kussmaul breathing + very high glucose",quality:"best",next:"m06-n2",feedback:"Correct. EMT recognition drives urgent transport—not field insulin dosing."},{id:"m06-n1-wrong",text:"Simple anxiety hyperventilation only—no further care",quality:"incorrect",next:"m06-n2",feedback:"High glucose and dehydration say otherwise."},{id:"m06-n1-bad",text:"Give insulin from the mother's vial using an invented dose",quality:"harmful",next:"m06-n2",feedback:"EMTs do not invent insulin doses."},{id:"m06-n1-acc",text:"Flag hyperglycemic crisis and prepare ALS/ED transport",quality:"acceptable",next:"m06-n2",feedback:"Acceptable."}]},{id:"m06-n2",prompt:"Best EMT supportive care?",options:[{id:"m06-n2-best",text:"ABCs, oxygen if needed, keep NPO if vomiting/altered, ALS for fluids per protocol, rapid transport",quality:"best",next:"m06-n3",feedback:"Correct. Support and move—definitive care is hospital/ALS."},{id:"m06-n2-bad",text:"Force large amounts of sugary soda because glucose is already high 'to balance ketones'",quality:"harmful",next:"m06-n3",feedback:"Do not add oral sugar in DKA suspicion."},{id:"m06-n2-wrong",text:"Withhold transport to try home remedies for hours",quality:"incorrect",next:"m06-n3",feedback:"This is an emergency.",delayedCritical:!0},{id:"m06-n2-acc",text:"Monitor ABCs and expedite care",quality:"acceptable",next:"m06-n3",feedback:"Acceptable."}]},{id:"m06-n3",prompt:"He becomes more lethargic with continued deep rapid breaths. Concern?",vitals:{hr:136,rr:36,spo2:97,bp:"92/60",gcs:"12"},options:[{id:"m06-n3-best",text:"Worsening metabolic emergency—protect airway, assist ventilations if inadequate, do not delay",quality:"best",next:"m06-n4",feedback:"Correct. Fatigue after Kussmaul can signal decompensation."},{id:"m06-n3-wrong",text:"Coach him to hold his breath to normalize CO₂",quality:"harmful",next:"m06-n4",feedback:"Kussmaul is compensatory—do not suppress it casually."},{id:"m06-n3-bad",text:"Give an invented bicarbonate dose",quality:"harmful",next:"m06-n4",feedback:"No invented meds."},{id:"m06-n3-acc",text:"Airway watch and priority transport",quality:"acceptable",next:"m06-n4",feedback:"Acceptable."}]},{id:"m06-n4",prompt:"Handoff emphasis?",options:[{id:"m06-n4-best",text:"Report suspected DKA signs, glucose reading, respiratory pattern, mental status trend, and fluids if given by ALS",quality:"best",next:"end",feedback:"Correct. Clear suspicion speeds ED labs/treatment."},{id:"m06-n4-wrong",text:"Say only 'teen with stomachache'",quality:"incorrect",next:"end",feedback:"Misses critical context."},{id:"m06-n4-bad",text:"Claim you gave insulin when you did not",quality:"harmful",next:"end",feedback:"Never falsify."},{id:"m06-n4-acc",text:"Hyperglycemia with Kussmaul and dehydration summary",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Recognize DKA pattern (high glucose, Kussmaul, dehydration)","Supportive care—no invented insulin","Watch for airway/ventilatory failure as fatigue grows","Clear suspected-DKA handoff"],keyTakeaway:"DKA is a recognition-and-transport emergency for EMTs—support ABCs and never invent insulin doses."}),(0,t.sc)({id:"medical-07",title:"Behavioral Emergency — Safety First",category:"medical",difficulty:"application",source:t.NATIONAL,dispatch:"Agitated adult yelling in apartment hallway. Possible psychiatric history. PD requested.",scene:"Apartment hallway. PD on scene stating scene is secure but patient pacing. Exits clear behind you.",presentation:"Agitated, speaking rapidly about being followed, not currently violent. Refuses to sit. Denies SI clearly but is paranoid. Skin warm; pupils normal.",vitals:{hr:110,rr:22,spo2:98,bp:"142/88",skin:"warm, dry",gcs:"15",glucose:"102"},startNodeId:"m07-n1",nodes:[{id:"m07-n1",prompt:"First priority?",options:[{id:"m07-n1-best",text:"Maintain scene safety and escape routes; approach calmly with PD; look for medical causes of AMS",quality:"best",next:"m07-n2",feedback:"Correct. Behavioral calls still need safety and medical differentials."},{id:"m07-n1-bad",text:"Corner the patient alone without PD to 'show dominance'",quality:"harmful",next:"m07-n2",feedback:"Unsafe."},{id:"m07-n1-wrong",text:"Ignore safety and rush hands-on restraint immediately",quality:"harmful",next:"m07-n2",feedback:"Escalate only when needed with adequate resources."},{id:"m07-n1-acc",text:"Calm verbal engagement from a safe distance",quality:"acceptable",next:"m07-n2",feedback:"Acceptable."}]},{id:"m07-n2",prompt:"Which medical checks matter before labeling 'psych only'?",options:[{id:"m07-n2-best",text:"Glucose, hypoxia, overdose/trauma signs, stroke/seizure clues, fever when feasible",quality:"best",next:"m07-n3",feedback:"Correct. Many 'psych' presentations are medical."},{id:"m07-n2-wrong",text:"No vitals ever on behavioral patients",quality:"incorrect",next:"m07-n3",feedback:"Assess as safety allows."},{id:"m07-n2-bad",text:"Inject an invented sedative dose without protocol",quality:"harmful",next:"m07-n3",feedback:"No invented meds."},{id:"m07-n2-acc",text:"Attempt SpO₂, glucose, and focused history if safe",quality:"acceptable",next:"m07-n3",feedback:"Acceptable."}]},{id:"m07-n3",prompt:"He agrees to sit; still agitated but not assaultive. Transport approach?",options:[{id:"m07-n3-best",text:"Voluntary transport if possible; explain process; use least restrictive measures; restrain only per protocol with enough personnel if danger appears",quality:"best",next:"m07-n4",feedback:"Correct. Least restrictive + safety."},{id:"m07-n3-bad",text:"Hog-tie prone with weight on the back for convenience",quality:"harmful",next:"m07-n4",feedback:"Positional asphyxia risk."},{id:"m07-n3-wrong",text:"Refuse any assessment because he is 'psych'",quality:"incorrect",next:"m07-n4",feedback:"Still a patient."},{id:"m07-n3-acc",text:"Calm coaching onto stretcher with PD present",quality:"acceptable",next:"m07-n4",feedback:"Acceptable."}]},{id:"m07-n4",prompt:"En route he becomes violent, threatening crew. Action?",options:[{id:"m07-n4-best",text:"Prioritize crew safety—stop ambulance if needed, request PD, apply approved restraint methods per protocol, monitor ABCs closely",quality:"best",next:"end",feedback:"Correct. Safety first, then protocol restraints with airway monitoring."},{id:"m07-n4-bad",text:"Punish with airway obstruction techniques",quality:"harmful",next:"end",feedback:"Never."},{id:"m07-n4-wrong",text:"Ignore threats and continue without changing plan",quality:"incorrect",next:"end",feedback:"Reassess safety."},{id:"m07-n4-acc",text:"PD assist and continuous monitoring after restraint",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Scene safety + calm approach","Seek medical causes (glucose/hypoxia/tox)","Least restrictive transport plan","If violence: safety, protocol restraints, ABC watch"],keyTakeaway:"Behavioral emergencies demand safety and a medical workup—restraints are last resort and require airway vigilance."}),(0,t.sc)({id:"trauma-01",title:"External Hemorrhage Control",category:"trauma",difficulty:"foundational",source:t.NATIONAL,dispatch:"Industrial accident, severe bleeding from arm laceration. Conscious on arrival.",scene:"Warehouse floor. Machine stopped. PPE on. Bright red bleeding from upper arm wound. Coworker applying random paper towels.",presentation:"Alert, anxious, blood-soaked sleeve. Spurting bleeding from medial upper arm. Distal pulse present but weak.",vitals:{hr:120,rr:22,spo2:97,bp:"100/70",skin:"pale, diaphoretic",gcs:"15"},startNodeId:"t01-n1",nodes:[{id:"t01-n1",prompt:"After BSI/scene safety, immediate priority?",options:[{id:"t01-n1-best",text:"Expose the wound and apply direct pressure with a gloved hand/dressing—control life-threatening hemorrhage first",quality:"best",next:"t01-n2",feedback:"Correct. March toward bleeding control before delayed vitals."},{id:"t01-n1-wrong",text:"Spend several minutes documenting exact mechanism before touching the wound",quality:"incorrect",next:"t01-n2",feedback:"Bleeding first.",delayedCritical:!0},{id:"t01-n1-bad",text:"Apply a tourniquet loosely as decoration without assessing pressure needs",quality:"incorrect",next:"t01-n2",feedback:"Start with effective direct pressure; escalate properly if needed."},{id:"t01-n1-acc",text:"Direct pressure with sterile dressing while assessing ABCs",quality:"acceptable",next:"t01-n2",feedback:"Acceptable."}]},{id:"t01-n2",prompt:"Direct pressure is soaking through rapidly; bleeding continues heavily. Next escalation?",options:[{id:"t01-n2-best",text:"Apply a tourniquet proximal to the wound on the extremity per training; note time; continue assessment",quality:"best",next:"t01-n3",feedback:"Correct. Life-threatening extremity hemorrhage that fails pressure needs a tourniquet."},{id:"t01-n2-wrong",text:"Remove all dressings to 'let it air out'",quality:"harmful",next:"t01-n3",feedback:"Worsens hemorrhage."},{id:"t01-n2-bad",text:"Pack the wound with food napkins soaked in bleach",quality:"harmful",next:"t01-n3",feedback:"Use proper dressings/hemostatic agents per protocol—not caustics."},{id:"t01-n2-acc",text:"Tourniquet high and tight enough to stop bleeding; mark time",quality:"acceptable",next:"t01-n3",feedback:"Acceptable."}]},{id:"t01-n3",prompt:"Bleeding stops after tourniquet. Patient becomes dizzy, BP 88/60. Care?",vitals:{hr:132,rr:24,spo2:95,bp:"88/60",skin:"cool, pale"},options:[{id:"t01-n3-best",text:"Treat for shock: keep warm, supine as tolerated, high-flow oxygen as needed, rapid transport",quality:"best",next:"t01-n4",feedback:"Correct. Hemorrhagic shock care after bleeding control."},{id:"t01-n3-wrong",text:"Have him stand to check orthostatics repeatedly",quality:"harmful",next:"t01-n4",feedback:"Worsens shock."},{id:"t01-n3-bad",text:"Loosen the tourniquet because BP dropped",quality:"harmful",next:"t01-n4",feedback:"Do not loosen a working tourniquet in the field for hypotension."},{id:"t01-n3-acc",text:"Shock management and priority transport",quality:"acceptable",next:"t01-n4",feedback:"Acceptable."}]},{id:"t01-n4",prompt:"Handoff must include?",options:[{id:"t01-n4-best",text:"Tourniquet location and time applied, estimated blood loss, response, and current vitals",quality:"best",next:"end",feedback:"Correct. Time-on-tourniquet is critical information."},{id:"t01-n4-wrong",text:"Omit tourniquet time as unimportant",quality:"incorrect",next:"end",feedback:"Always report time."},{id:"t01-n4-bad",text:"Hide that bleeding was arterial to avoid concern",quality:"harmful",next:"end",feedback:"Be accurate."},{id:"t01-n4-acc",text:"Report interventions and shock signs clearly",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Direct pressure first","Escalate to tourniquet if pressure fails","Treat hemorrhagic shock; do not loosen a needed TQ","Report TQ time and response"],keyTakeaway:"Life-threatening extremity bleeding: pressure, then tourniquet if needed—never delay for nonessential tasks."}),(0,t.sc)({id:"trauma-02",title:"Open Chest Wound",category:"trauma",difficulty:"critical",source:t.NATIONAL,dispatch:"Stabbing to chest, patient conscious, difficulty breathing. PD advises scene secure.",scene:"Alley cleared by PD. Adult male sitting against wall. Penetrating wound mid-chest right, bubbling with breaths.",presentation:"Alert, severe dyspnea, sucking chest wound sounds, diminished sounds on injured side. No major external bleeding now.",vitals:{hr:118,rr:28,spo2:88,bp:"110/78",skin:"pale",gcs:"15"},startNodeId:"t02-n1",nodes:[{id:"t02-n1",prompt:"Immediate wound management?",options:[{id:"t02-n1-best",text:"Apply an occlusive dressing (vented per protocol/training) and monitor for tension physiology",quality:"best",next:"t02-n2",feedback:"Correct. Seal open chest wounds and watch for deterioration."},{id:"t02-n1-wrong",text:"Leave the wound open to 'equalize pressures' indefinitely without a plan",quality:"incorrect",next:"t02-n2",feedback:"Open pneumothorax needs occlusion.",delayedCritical:!0},{id:"t02-n1-bad",text:"Pack the chest cavity deeply with dry gauze blindly into the thorax",quality:"harmful",next:"t02-n2",feedback:"Not appropriate open-chest packing technique for EMT sucking wound care."},{id:"t02-n1-acc",text:"Gloved hand seal temporarily then occlusive dressing",quality:"acceptable",next:"t02-n2",feedback:"Acceptable."}]},{id:"t02-n2",prompt:"After sealing, SpO₂ still 88% and work of breathing high. Support?",options:[{id:"t02-n2-best",text:"High-flow oxygen, position of comfort if no spinal priority, rapid transport/ALS",quality:"best",next:"t02-n3",feedback:"Correct. Oxygenate and move toward definitive care."},{id:"t02-n2-wrong",text:"Withhold oxygen to avoid fire risk from a distant cigarette butt",quality:"incorrect",next:"t02-n3",feedback:"Treat hypoxia; manage ignition sources reasonably.",delayedCritical:!0},{id:"t02-n2-bad",text:"Force him to lie on the uninjured side while ignoring increasing distress without reassessment",quality:"incorrect",next:"t02-n3",feedback:"Reassess continuously; follow positioning that helps breathing if spinal allows."},{id:"t02-n2-acc",text:"Oxygen and prepare for ventilatory support if needed",quality:"acceptable",next:"t02-n3",feedback:"Acceptable."}]},{id:"t02-n3",prompt:"He suddenly worsens: JVD, tracheal deviation signs, severe dyspnea, BP falling. Concern?",vitals:{hr:140,rr:34,spo2:82,bp:"86/60",gcs:"14"},options:[{id:"t02-n3-best",text:"Possible tension pneumothorax developing—support ABCs, lift a corner of occlusive dressing to burp if protocol trained, rapid ALS for needle decompression",quality:"best",next:"t02-n4",feedback:"Correct. Recognize tension physiology; EMTs support and expedite ALS/ED."},{id:"t02-n3-wrong",text:"Assume anxiety and remove oxygen",quality:"harmful",next:"t02-n4",feedback:"This is a thoracic emergency."},{id:"t02-n3-bad",text:"Perform an improvised field thoracotomy",quality:"harmful",next:"t02-n4",feedback:"Far outside EMT scope."},{id:"t02-n3-acc",text:"Burp the seal if trained/protocol and request immediate ALS",quality:"acceptable",next:"t02-n4",feedback:"Acceptable."}]},{id:"t02-n4",prompt:"Transport priority?",options:[{id:"t02-n4-best",text:"Load-and-go thoracic trauma with ongoing airway/oxygen monitoring and early trauma notification",quality:"best",next:"end",feedback:"Correct. Penetrating chest trauma is surgical time-sensitive."},{id:"t02-n4-wrong",text:"Extended scene for full secondary survey of toes first",quality:"incorrect",next:"end",feedback:"Do not delay.",delayedCritical:!0},{id:"t02-n4-bad",text:"Allow him to smoke to 'calm nerves'",quality:"harmful",next:"end",feedback:"Oxygen/fire and delay."},{id:"t02-n4-acc",text:"Priority trauma transport with continuous reassessment of breath sounds and distress",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Occlusive dressing for sucking chest wound","Oxygen and rapid ALS/transport","Watch for tension—burp seal/ALS decompression pathway","Load-and-go with trauma notify"],keyTakeaway:"Open chest wounds get sealed and watched—worsening shock and dyspnea suggest tension physiology needing ALS/ED urgently."}),(0,t.sc)({id:"trauma-03",title:"Flail Chest Recognition",category:"trauma",difficulty:"application",source:t.NATIONAL,dispatch:"MVC, driver vs steering wheel, chest pain and trouble breathing.",scene:"Vehicle stabilized by rescue. Patient still in driver seat initially, then extricated to board. Daytime, dry road.",presentation:"Paradoxical motion of a segment of left chest wall, severe pain, shallow breaths, crepitus. Alert.",vitals:{hr:110,rr:28,spo2:90,bp:"128/84",skin:"pale",gcs:"15"},startNodeId:"t03-n1",nodes:[{id:"t03-n1",prompt:"What finding defines flail chest concern?",options:[{id:"t03-n1-best",text:"A segment of chest wall moving paradoxically opposite the rest of the chest during breathing",quality:"best",next:"t03-n2",feedback:"Correct. Paradoxical motion after blunt trauma signals flail physiology."},{id:"t03-n1-wrong",text:"A tiny scratch on the forearm",quality:"incorrect",next:"t03-n2",feedback:"Not the defining finding."},{id:"t03-n1-bad",text:"Ignoring chest wall motion because SpO₂ is 'only a little low'",quality:"incorrect",next:"t03-n2",feedback:"Recognize the injury pattern.",delayedCritical:!0},{id:"t03-n1-acc",text:"Paradoxical segment plus respiratory distress after blunt trauma",quality:"acceptable",next:"t03-n2",feedback:"Acceptable."}]},{id:"t03-n2",prompt:"Best EMT respiratory support approach?",options:[{id:"t03-n2-best",text:"High-flow oxygen, stabilize with hand or bulky dressing as trained, assist ventilations if inadequate, rapid transport",quality:"best",next:"t03-n3",feedback:"Correct. Oxygenation/ventilation support is key—underlying lung injury is the threat."},{id:"t03-n2-bad",text:"Tape the chest circumferentially as tightly as possible forever",quality:"harmful",next:"t03-n3",feedback:"Over-restrictive taping can worsen ventilation."},{id:"t03-n2-wrong",text:"Withhold oxygen to 'encourage deep breathing contests'",quality:"incorrect",next:"t03-n3",feedback:"Treat hypoxia.",delayedCritical:!0},{id:"t03-n2-acc",text:"Oxygen and be ready to BVM if tidal volume falls",quality:"acceptable",next:"t03-n3",feedback:"Acceptable."}]},{id:"t03-n3",prompt:"Patient becomes exhausted; SpO₂ 85% despite oxygen. Next?",vitals:{hr:124,rr:8,spo2:85,bp:"118/80",gcs:"13"},options:[{id:"t03-n3-best",text:"Assist ventilations carefully with BVM and oxygen; monitor for deterioration",quality:"best",next:"t03-n4",feedback:"Correct. Fatigue with flail/pulmonary contusion often needs assisted ventilation."},{id:"t03-n3-wrong",text:"Encourage sprinting to the ambulance",quality:"harmful",next:"t03-n4",feedback:"Exertion worsens failure."},{id:"t03-n3-bad",text:"Remove all oxygen to 'reset'",quality:"harmful",next:"t03-n4",feedback:"Dangerous."},{id:"t03-n3-acc",text:"BVM support and expedite trauma center transport",quality:"acceptable",next:"t03-n4",feedback:"Acceptable."}]},{id:"t03-n4",prompt:"Associated injury vigilance?",options:[{id:"t03-n4-best",text:"Suspect pulmonary contusion and other blunt trauma; reassess ABCs frequently during transport",quality:"best",next:"end",feedback:"Correct. Flail often pairs with contusion and multi-system injury."},{id:"t03-n4-wrong",text:"Assume isolated cosmetic rib issue only",quality:"incorrect",next:"end",feedback:"Underestimates severity."},{id:"t03-n4-bad",text:"Give an invented opioid dose for pain without protocol",quality:"harmful",next:"end",feedback:"No invented doses."},{id:"t03-n4-acc",text:"Continuous monitoring for hypoxia and shock",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Recognize paradoxical chest wall motion","Oxygen ± gentle stabilization; avoid harmful restriction","Assist ventilations if failing","Watch for contusion/multi-trauma during transport"],keyTakeaway:"Flail chest is paradoxical motion plus respiratory failure risk—oxygenate, assist early, and transport rapidly."}),(0,t.sc)({id:"trauma-04",title:"Pelvic Trauma",category:"trauma",difficulty:"critical",source:t.NATIONAL,dispatch:"Pedestrian struck, pelvic pain, unable to move legs well. High-speed vehicle.",scene:"Roadway secured. Patient supine. Longboard available. Significant mechanism.",presentation:"Pale, pelvic pain to gentle assessment, unstable pelvis suspicion, hypotension developing. Alert initially.",vitals:{hr:130,rr:24,spo2:94,bp:"86/58",skin:"pale, cool",gcs:"15"},startNodeId:"t04-n1",nodes:[{id:"t04-n1",prompt:"Pelvic assessment caution?",options:[{id:"t04-n1-best",text:"Avoid repeated rocking of an unstable pelvis; assess once gently and treat for hemorrhage/shock",quality:"best",next:"t04-n2",feedback:"Correct. Do not repeatedly stress a broken pelvis."},{id:"t04-n1-bad",text:"Vigorously spring the pelvis multiple times for teaching",quality:"harmful",next:"t04-n2",feedback:"Can worsen bleeding."},{id:"t04-n1-wrong",text:"Ignore hypotension because pain is 'just musculoskeletal'",quality:"incorrect",next:"t04-n2",feedback:"Pelvic bleeding can be massive.",delayedCritical:!0},{id:"t04-n1-acc",text:"Gentle assessment once, then pelvic binder per protocol if indicated",quality:"acceptable",next:"t04-n2",feedback:"Acceptable."}]},{id:"t04-n2",prompt:"Best hemorrhage/shock interventions at EMT level?",options:[{id:"t04-n2-best",text:"Pelvic binder/sheet wrap per training, control other external bleeding, keep warm, rapid transport to trauma center",quality:"best",next:"t04-n3",feedback:"Correct. Stabilize pelvis and treat shock—surgery/IR is definitive."},{id:"t04-n2-wrong",text:"Log-roll repeatedly to 'check the back' before any binder",quality:"incorrect",next:"t04-n3",feedback:"Minimize movement; prioritize hemorrhage control.",delayedCritical:!0},{id:"t04-n2-bad",text:"Sit the hypotensive patient upright for comfort photos",quality:"harmful",next:"t04-n3",feedback:"Worsens shock."},{id:"t04-n2-acc",text:"Binder per protocol + shock care + trauma notify",quality:"acceptable",next:"t04-n3",feedback:"Acceptable."}]},{id:"t04-n3",prompt:"BP falls to 70/40; patient becomes confused. Priority?",vitals:{hr:146,rr:28,spo2:92,bp:"70/40",gcs:"12"},options:[{id:"t04-n3-best",text:"Load-and-go hemorrhagic shock care: airway, oxygen, warmth, minimize scene time, ALS intercept",quality:"best",next:"t04-n4",feedback:"Correct. Unstable pelvic trauma needs surgical hemorrhage control."},{id:"t04-n3-wrong",text:"Start a prolonged detailed secondary on scene",quality:"incorrect",next:"t04-n4",feedback:"Delay kills.",delayedCritical:!0},{id:"t04-n3-bad",text:"Give oral fluids liberally",quality:"harmful",next:"t04-n4",feedback:"NPO; aspiration and delay."},{id:"t04-n3-acc",text:"Priority move with ongoing monitoring",quality:"acceptable",next:"t04-n4",feedback:"Acceptable."}]},{id:"t04-n4",prompt:"Why is pelvic injury especially dangerous?",options:[{id:"t04-n4-best",text:"It can conceal large internal hemorrhage into the retroperitoneum/pelvic space",quality:"best",next:"end",feedback:"Correct. External blood loss may look modest while internal bleeding is massive."},{id:"t04-n4-wrong",text:"Because it always causes isolated toe fractures only",quality:"incorrect",next:"end",feedback:"Misses the hemorrhage risk."},{id:"t04-n4-bad",text:"Because oxygen is contraindicated in all pelvic injuries",quality:"harmful",next:"end",feedback:"False—support perfusion/oxygenation."},{id:"t04-n4-acc",text:"Occult bleeding plus shock physiology",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Gentle one-time pelvic assessment","Binder/sheet per protocol + shock care","Rapid trauma transport if unstable","Respect occult internal hemorrhage risk"],keyTakeaway:"Unstable pelvis means hidden bleeding—bind per protocol, treat shock, and minimize scene time."}),(0,t.sc)({id:"trauma-05",title:"Head Injury with Airway Threat",category:"trauma",difficulty:"critical",source:t.NATIONAL,dispatch:"Fall from ladder ~12 feet, unresponsive, bleeding from scalp. Son on scene.",scene:"Backyard. Ladder on ground. Patient supine. No ongoing fall hazard. ALS 7 minutes.",presentation:"Unresponsive, snoring respirations, large scalp laceration with controllable bleeding, suspected head injury. Possible cervical trauma.",vitals:{hr:64,rr:8,spo2:86,bp:"170/90",skin:"bloody scalp",gcs:"6"},startNodeId:"t05-n1",nodes:[{id:"t05-n1",prompt:"Competing priorities—how do you sequence?",options:[{id:"t05-n1-best",text:"Manual c-spine as indicated, open airway with jaw-thrust, suction, assist ventilations with oxygen; control scalp bleeding without delaying airway",quality:"best",next:"t05-n2",feedback:"Correct. Airway/breathing still lead, with spinal motion restriction precautions."},{id:"t05-n1-wrong",text:"Ignore airway to apply five scalp bandages first",quality:"incorrect",next:"t05-n2",feedback:"Airway first.",delayedCritical:!0},{id:"t05-n1-bad",text:"Hyperextend the neck aggressively despite trauma",quality:"harmful",next:"t05-n2",feedback:"Use jaw-thrust when spinal injury possible."},{id:"t05-n1-acc",text:"Jaw-thrust, suction, BVM, then scalp pressure",quality:"acceptable",next:"t05-n2",feedback:"Acceptable."}]},{id:"t05-n2",prompt:"Ventilations: which concept fits head injury?",options:[{id:"t05-n2-best",text:"Maintain adequate oxygenation and avoid prolonged hypoxia/hyperventilation extremes unless directed for specific herniation protocols",quality:"best",next:"t05-n3",feedback:"Correct. Prevent hypoxia; do not wildly hyperventilate by default."},{id:"t05-n2-bad",text:"Hyperventilate as fast as possible for the entire call without indication",quality:"harmful",next:"t05-n3",feedback:"Routine aggressive hyperventilation can harm."},{id:"t05-n2-wrong",text:"Leave SpO₂ at 86% because head injuries 'need hypoxia'",quality:"incorrect",next:"t05-n3",feedback:"Hypoxia worsens brain injury.",delayedCritical:!0},{id:"t05-n2-acc",text:"Effective BVM with oxygen and visible chest rise at an appropriate rate",quality:"acceptable",next:"t05-n3",feedback:"Acceptable."}]},{id:"t05-n3",prompt:"Scalp bleeding continues under a loose dressing. Action?",options:[{id:"t05-n3-best",text:"Apply firm direct pressure with dressing; avoid pressing bone fragments into open depressed skull if palpable—control bleeding carefully",quality:"best",next:"t05-n4",feedback:"Correct. Control hemorrhage without worsening open skull injuries."},{id:"t05-n3-bad",text:"Remove clotting dressings repeatedly to photograph",quality:"harmful",next:"t05-n4",feedback:"Disrupts clotting."},{id:"t05-n3-wrong",text:"Ignore bleeding entirely forever",quality:"incorrect",next:"t05-n4",feedback:"Scalp can bleed significantly."},{id:"t05-n3-acc",text:"Pressure dressing once airway is being managed",quality:"acceptable",next:"t05-n4",feedback:"Acceptable."}]},{id:"t05-n4",prompt:"Transport packaging?",options:[{id:"t05-n4-best",text:"Spinal motion restriction as indicated, continuous airway support, elevate head of board slightly if protocol and no contraindication, rapid trauma transport",quality:"best",next:"end",feedback:"Correct. Protect spine and airway while moving to definitive care."},{id:"t05-n4-wrong",text:"Sit fully upright without airway adjuncts while snoring",quality:"harmful",next:"end",feedback:"Airway not secured."},{id:"t05-n4-bad",text:"Delay for a complete insurance discussion on scene",quality:"incorrect",next:"end",feedback:"TBI needs speed.",delayedCritical:!0},{id:"t05-n4-acc",text:"SMR + ongoing BVM/oxygen + trauma notify",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Jaw-thrust airway + BVM with c-spine precautions","Oxygenate; avoid needless hyperventilation","Control scalp bleeding carefully","SMR packaging and rapid transport"],keyTakeaway:"Head trauma still follows ABCs—open the airway with spinal precautions and prevent hypoxia."}),(0,t.sc)({id:"trauma-06",title:"Spinal Motion Restriction Decision",category:"trauma",difficulty:"application",source:t.NATIONAL,dispatch:"Low-speed rear-end MVC. Ambulatory on scene, neck pain. Extricated self.",scene:"Parking lot fender-bender. Vehicles minor damage. Patient standing, holding neck. No altered mental status.",presentation:"GCS 15, midline neck tenderness, no focal neuro deficits, ambulatory. Denies intoxication. Stable vitals.",vitals:{hr:88,rr:16,spo2:99,bp:"128/78",skin:"warm, dry",gcs:"15"},startNodeId:"t06-n1",nodes:[{id:"t06-n1",prompt:"Best initial approach to spinal care?",options:[{id:"t06-n1-best",text:"Manual stabilization as needed and apply cervical collar based on assessment findings/protocol—not every minor MVC gets longboard strapping by default",quality:"best",next:"t06-n2",feedback:"Correct. Modern SMR is assessment-driven per protocol."},{id:"t06-n1-wrong",text:"Tackle the standing patient onto a board without assessment",quality:"harmful",next:"t06-n2",feedback:"Unnecessary force."},{id:"t06-n1-bad",text:"Tell every patient with any crash to run home without evaluation",quality:"incorrect",next:"t06-n2",feedback:"Still assess."},{id:"t06-n1-acc",text:"Assess for reliable exam and midline tenderness; collar if indicated",quality:"acceptable",next:"t06-n2",feedback:"Acceptable."}]},{id:"t06-n2",prompt:"He has midline cervical tenderness. Next?",options:[{id:"t06-n2-best",text:"C-collar and spinal motion restriction per protocol; limit unnecessary movement; transport for evaluation",quality:"best",next:"t06-n3",feedback:"Correct. Positive findings warrant SMR."},{id:"t06-n2-wrong",text:"Have him do cartwheels to clear the spine",quality:"harmful",next:"t06-n3",feedback:"Dangerous."},{id:"t06-n2-bad",text:"Remove collar repeatedly for selfies",quality:"harmful",next:"t06-n3",feedback:"Inconsistent protection."},{id:"t06-n2-acc",text:"Collar, careful stretcher movement, document neuro status",quality:"acceptable",next:"t06-n3",feedback:"Acceptable."}]},{id:"t06-n3",prompt:"During packaging he mentions new arm numbness. Action?",options:[{id:"t06-n3-best",text:"Reassess neurologic status, maintain SMR carefully, note time of change, priority transport",quality:"best",next:"t06-n4",feedback:"Correct. New deficits raise urgency."},{id:"t06-n3-wrong",text:"Ignore new deficits because initial exam was normal",quality:"incorrect",next:"t06-n4",feedback:"Reassess—findings evolve."},{id:"t06-n3-bad",text:"Force neck range-of-motion testing aggressively",quality:"harmful",next:"t06-n4",feedback:"Do not provoke injury."},{id:"t06-n3-acc",text:"Document neuro change and expedite care",quality:"acceptable",next:"t06-n4",feedback:"Acceptable."}]},{id:"t06-n4",prompt:"Key teaching point for SMR?",options:[{id:"t06-n4-best",text:"Spinal precautions are based on mechanism plus reliable exam findings—protect when indicated without causing harm from over-restriction",quality:"best",next:"end",feedback:"Correct. Balance protection and unnecessary rigid packaging harms."},{id:"t06-n4-wrong",text:"Longboards are mandatory for all back pain forever",quality:"incorrect",next:"end",feedback:"Protocols have evolved."},{id:"t06-n4-bad",text:"Never collar anyone with midline tenderness",quality:"harmful",next:"end",feedback:"Positive findings need protection."},{id:"t06-n4-acc",text:"Follow local selective SMR protocol thoughtfully",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Assessment-driven SMR, not blind tackling","Collar/SMR when midline tenderness present","Reassess if neuro symptoms change","Balance indicated protection vs harmful over-restriction"],keyTakeaway:"Spinal motion restriction is selective and protocol-based—protect positive findings without causing needless harm."}),(0,t.sc)({id:"trauma-07",title:"Multi-System Trauma Priorities",category:"trauma",difficulty:"critical",source:t.NATIONAL,dispatch:"Motorcycle vs car. Multisystem injuries. Unresponsive. High-speed roadway.",scene:"Highway blocked by PD/fire. Helmet removed by fire carefully before your hands-on. Hazards controlled.",presentation:"Unresponsive, inadequate breathing, femoral bleeding, deformed femur, suspected chest injury, hypotensive.",vitals:{hr:140,rr:6,spo2:84,bp:"78/50",skin:"pale, cool",gcs:"4"},startNodeId:"t07-n1",nodes:[{id:"t07-n1",prompt:"With multiple life threats, what order wins?",options:[{id:"t07-n1-best",text:"Massive hemorrhage control and airway/breathing support nearly simultaneously—tourniquet for femoral bleed while opening airway/BVM",quality:"best",next:"t07-n2",feedback:"Correct. MARCH/XABC mindset: stop killing bleeding and oxygenate."},{id:"t07-n1-wrong",text:"Splint the femur first for 15 minutes before airway or bleeding care",quality:"incorrect",next:"t07-n2",feedback:"Wrong priority.",delayedCritical:!0},{id:"t07-n1-bad",text:"Ignore the arterial bleed to finish a neat secondary survey",quality:"harmful",next:"t07-n2",feedback:"Exsanguination first."},{id:"t07-n1-acc",text:"Tourniquet + BVM/oxygen together with partner teamwork",quality:"acceptable",next:"t07-n2",feedback:"Acceptable."}]},{id:"t07-n2",prompt:"Bleeding controlled; still apneic with pulse. Focus?",options:[{id:"t07-n2-best",text:"Continue effective BVM ventilations with oxygen and rapid packaging for trauma center",quality:"best",next:"t07-n3",feedback:"Correct. After hemorrhage control, ventilate and move."},{id:"t07-n2-wrong",text:"Stop ventilations to apply decorative tape to a scraped elbow",quality:"incorrect",next:"t07-n3",feedback:"Life threats first.",delayedCritical:!0},{id:"t07-n2-bad",text:"Pronounce based on hypotension alone while pulse/breathing supportable",quality:"harmful",next:"t07-n3",feedback:"Continue resuscitation."},{id:"t07-n2-acc",text:"Airway support and load-and-go",quality:"acceptable",next:"t07-n3",feedback:"Acceptable."}]},{id:"t07-n3",prompt:"Scene time philosophy?",options:[{id:"t07-n3-best",text:"Critical trauma: only life-saving interventions on scene, then rapid transport (platinum minutes mindset)",quality:"best",next:"t07-n4",feedback:"Correct. Surgery fixes bleeding you cannot see."},{id:"t07-n3-wrong",text:"Stay until every abrasion is cataloged",quality:"incorrect",next:"t07-n4",feedback:"Delay."},{id:"t07-n3-bad",text:"Drive without any airway support because 'the hospital is close'",quality:"harmful",next:"t07-n4",feedback:"Support en route."},{id:"t07-n3-acc",text:"Minimize scene time after XABCs addressed",quality:"acceptable",next:"t07-n4",feedback:"Acceptable."}]},{id:"t07-n4",prompt:"En route femur still deformed; bleeding controlled. Splinting?",options:[{id:"t07-n4-best",text:"Splint en route if it does not delay critical care; reassess pulse/motor/sensory after",quality:"best",next:"end",feedback:"Correct. Limb care after life threats, ideally during transport."},{id:"t07-n4-wrong",text:"Return to the highway to fetch a nonessential gadget before transport",quality:"incorrect",next:"end",feedback:"Do not reverse priority."},{id:"t07-n4-bad",text:"Remove the tourniquet to make splinting prettier",quality:"harmful",next:"end",feedback:"Keep needed hemorrhage control."},{id:"t07-n4-acc",text:"Traction/splint per protocol once ABCs/bleeding stable enough",quality:"acceptable",next:"end",feedback:"Acceptable."}]}],correctSequence:["Hemorrhage + airway/breathing together","Continue ventilation and rapid packaging","Short scene time after life-saving care","Splint en route without undoing critical interventions"],keyTakeaway:"Multi-system trauma: stop massive bleeding, support the airway, and leave the scene—definitive care is the hospital."}),(0,t.sc)({id:"ob-peds-01",title:"Imminent Delivery",category:"ob_peds",difficulty:"application",source:t.NATIONAL,dispatch:"28 y/o female, full-term pregnancy, contractions every 2 minutes. Partner says she feels the urge to push.",scene:"Apartment bedroom, evening. Partner present. Floor clear, no hazards. OB kit available on the ambulance.",presentation:"Alert, sweaty, between contractions. Crowning visible on inspection. Membranes ruptured. Denies prenatal complications.",vitals:{hr:110,rr:22,bp:"128/82",spo2:98,skin:"flushed, diaphoretic",gcs:"15"},startNodeId:"op01-n1",nodes:[{id:"op01-n1",prompt:"Crowning is present and the patient has a strong urge to push. Best immediate action?",options:[{id:"op01-n1-best",text:"Prepare for delivery on scene: BSI, OB kit, support the perineum, coach controlled delivery of the head",quality:"best",next:"op01-n2",feedback:"Correct. With crowning and urge to push, delivery is imminent — prepare and assist rather than attempting a prolonged extrication."},{id:"op01-n1-ok",text:"Load immediately for hospital delivery without preparing an OB kit",quality:"incorrect",next:"op01-n2",feedback:"Transport may still be needed, but crowning means you must be ready to deliver en route or on scene. Prepare the kit now.",delayedCritical:!0},{id:"op01-n1-bad",text:"Have the mother hold her legs together tightly to delay birth until the hospital",quality:"harmful",next:"op01-n2",feedback:"Never attempt to delay delivery. Support a controlled birth and protect mother and newborn.",delayedCritical:!0},{id:"op01-n1-wrong",text:"Focus only on obtaining a full prenatal history before examining the perineum",quality:"incorrect",next:"op01-n2",feedback:"History matters, but imminent delivery signs require immediate preparation for birth.",delayedCritical:!0}]},{id:"op01-n2",prompt:"The head delivers. You notice the cord is loosely around the neck. Best next step?",sceneUpdate:"Head is out; body not yet delivered. Cord visible around neck, not tightly constricting.",options:[{id:"op01-n2-best",text:"Gently slip the cord over the head if loose; if tightly clamped and irreducible, clamp and cut per training, then continue delivery",quality:"best",next:"op01-n3",feedback:"Correct. A nuchal cord is managed by slipping it free when possible; tight irreducible cords are clamped and cut so the body can deliver."},{id:"op01-n2-ok",text:"Pull firmly on the head to deliver the shoulders quickly past the cord",quality:"harmful",next:"op01-n3",feedback:"Traction on the head risks injury. Guide delivery; do not pull.",delayedCritical:!0},{id:"op01-n2-bad",text:"Ignore the cord and wait without intervening until the placenta delivers",quality:"incorrect",next:"op01-n3",feedback:"A cord around the neck must be addressed so the body can deliver safely.",delayedCritical:!0},{id:"op01-n2-wrong",text:"Push the head back in and transport without delivering",quality:"harmful",next:"op01-n3",feedback:"Never attempt to replace a delivered head. Continue assisted delivery.",delayedCritical:!0}]},{id:"op01-n3",prompt:"Shoulders and body deliver. Newborn is crying vigorously. Mother is stable. Priority now?",options:[{id:"op01-n3-best",text:"Dry and warm the newborn, place skin-to-skin or wrap, note time of birth, clamp/cut cord when appropriate, reassess mother for bleeding",quality:"best",next:"op01-n4",feedback:"Correct. Vigorous newborns need drying, warmth, and ongoing maternal assessment for postpartum hemorrhage."},{id:"op01-n3-ok",text:"Immediately begin aggressive stimulation and prolonged suction of a crying newborn",quality:"incorrect",next:"op01-n4",feedback:"A vigorous crying newborn does not need aggressive airway intervention — dry, warm, and observe."},{id:"op01-n3-bad",text:"Leave the newborn unattended while you complete paperwork",quality:"harmful",next:"op01-n4",feedback:"Newborns cool quickly and need continuous attention alongside maternal care.",delayedCritical:!0},{id:"op01-n3-wrong",text:"Pull on the cord to speed placental delivery",quality:"harmful",next:"op01-n4",feedback:"Do not traction the cord. Allow placental delivery; watch for excessive maternal bleeding.",delayedCritical:!0}]},{id:"op01-n4",prompt:"Best transport and monitoring plan for mother and newborn?",options:[{id:"op01-n4-best",text:"Transport both; keep newborn warm, monitor maternal bleeding/fundus awareness per training, reassess both frequently",quality:"best",next:"end",feedback:"Correct. Postpartum mother and neonate both need ongoing assessment and warm, careful transport."},{id:"op01-n4-ok",text:"Transport mother only; leave newborn with family until another unit arrives",quality:"harmful",next:"end",feedback:"Do not separate care without a plan — both patients need EMS attention.",delayedCritical:!0},{id:"op01-n4-bad",text:"Delay transport indefinitely to wait for the placenta if bleeding is already heavy",quality:"incorrect",next:"end",feedback:"Significant maternal bleeding is a load-and-go priority while supporting care.",delayedCritical:!0},{id:"op01-n4-wrong",text:"Stop reassessment once both appear briefly well",quality:"incorrect",next:"end",feedback:"Condition can change quickly postpartum — continue reassessment."}]}],correctSequence:["Prepare for imminent delivery with BSI and OB kit","Manage nuchal cord appropriately; avoid traction on the head","Dry/warm vigorous newborn; reassess mother for bleeding","Transport both with ongoing warmth and reassessment"],keyTakeaway:"Crowning means deliver now: support controlled birth, protect the newborn from heat loss, and watch the mother for hemorrhage."}),(0,t.sc)({id:"ob-peds-02",title:"Neonate Needs Stimulation",category:"ob_peds",difficulty:"critical",source:t.NATIONAL,dispatch:"Home birth just occurred. Caller says the baby is blue and not crying loudly.",scene:"Living room floor, warm apartment. Mother still on the floor, placenta not delivered. Newborn in partner's arms, limp-appearing.",presentation:"Term newborn, weak intermittent cry, central cyanosis, poor tone. Mother alert with moderate vaginal bleeding.",vitals:{hr:"newborn ~90 (weak)",rr:"irregular, weak",spo2:"not yet applied",skin:"central cyanosis"},startNodeId:"op02-n1",nodes:[{id:"op02-n1",prompt:"First priority for this newly born infant?",options:[{id:"op02-n1-best",text:"Warm, dry thoroughly, clear airway as needed, stimulate by drying/rubbing the back or feet, position airway open",quality:"best",next:"op02-n2",feedback:"Correct. Initial neonatal steps are warmth, drying, airway positioning, and tactile stimulation."},{id:"op02-n1-ok",text:"Immediately start chest compressions without drying or stimulating",quality:"incorrect",next:"op02-n2",feedback:"Most newborns improve with drying and stimulation. Assess heart rate after initial steps before compressions.",delayedCritical:!0},{id:"op02-n1-bad",text:"Blow cold air on the infant's face and splash with water",quality:"harmful",next:"op02-n2",feedback:"Cold stress worsens newborns. Warm and dry — never cool them.",delayedCritical:!0},{id:"op02-n1-wrong",text:"Ignore the newborn until the placenta delivers",quality:"harmful",next:"op02-n2",feedback:"A depressed newborn is the immediate life threat. Assign maternal care while you resuscitate the infant.",delayedCritical:!0}]},{id:"op02-n2",prompt:"After drying and stimulation, the infant remains limp with HR about 50 and inadequate breathing. Best next action?",options:[{id:"op02-n2-best",text:"Begin positive-pressure ventilations with an appropriately sized BVM and room air/oxygen per neonatal protocol; reassess HR",quality:"best",next:"op02-n3",feedback:"Correct. Persistent apnea/bradycardia after stimulation needs effective ventilations — the key neonatal intervention."},{id:"op02-n2-ok",text:"Only give blow-by oxygen without supporting ventilations",quality:"incorrect",next:"op02-n3",feedback:"Inadequate breathing with bradycardia requires assisted ventilation, not blow-by alone.",delayedCritical:!0},{id:"op02-n2-bad",text:"Start compressions first without ventilating",quality:"incorrect",next:"op02-n3",feedback:"Ventilation comes before compressions in neonatal resuscitation priorities for most cases.",delayedCritical:!0},{id:"op02-n2-wrong",text:"Stimulate harder for several more minutes without ventilating",quality:"harmful",next:"op02-n3",feedback:"Do not delay ventilations when HR is critically low and breathing is inadequate.",delayedCritical:!0}]},{id:"op02-n3",prompt:"Effective ventilations are ongoing. After about 30 seconds, HR is still under 60. Next step?",options:[{id:"op02-n3-best",text:"Ensure ventilations are effective, then begin chest compressions coordinated with ventilations per neonatal guidelines; request ALS",quality:"best",next:"op02-n4",feedback:"Correct. Persistent HR <60 after adequate ventilation warrants compressions and advanced help."},{id:"op02-n3-ok",text:"Stop all care and wait for ALS without continuing ventilations",quality:"harmful",next:"op02-n4",feedback:"Continue BLS neonatal support until ALS arrives or the infant improves.",delayedCritical:!0},{id:"op02-n3-bad",text:"Give adult-sized ventilation volumes as hard as possible",quality:"harmful",next:"op02-n4",feedback:"Use gentle, appropriate neonatal volumes — overventilation causes harm.",delayedCritical:!0},{id:"op02-n3-wrong",text:"Place the infant prone and stop reassessment of HR",quality:"incorrect",next:"op02-n4",feedback:"Keep the airway open supine/neutral and reassess HR frequently."}]},{id:"op02-n4",prompt:"While resuscitating the newborn, how do you manage the mother?",options:[{id:"op02-n4-best",text:"Assign a provider to monitor maternal bleeding and mental status; keep both warm; transport with ongoing neonatal support",quality:"best",next:"end",feedback:"Correct. Two patients — newborn resuscitation plus maternal hemorrhage watch and transport."},{id:"op02-n4-ok",text:"Leave mother completely unmonitored for the rest of the call",quality:"harmful",next:"end",feedback:"Postpartum hemorrhage can kill the mother while you focus on the infant — divide attention.",delayedCritical:!0},{id:"op02-n4-bad",text:"Have mother walk to the ambulance carrying the infant during CPR",quality:"harmful",next:"end",feedback:"Do not interrupt effective resuscitation or create fall/cold-stress hazards.",delayedCritical:!0},{id:"op02-n4-wrong",text:"Refuse transport because the birth already happened at home",quality:"incorrect",next:"end",feedback:"A depressed neonate and postpartum mother need emergency transport."}]}],correctSequence:["Warm, dry, stimulate, position airway","Provide PPV for persistent apnea/bradycardia","Add compressions if HR remains <60 after adequate ventilation","Care for mother and newborn; transport with ongoing support"],keyTakeaway:"Neonatal priorities: warmth and drying first, then effective ventilation — compressions only after ventilation fails to raise HR."}),(0,t.sc)({id:"ob-peds-03",title:"Pediatric Respiratory Distress",category:"ob_peds",difficulty:"application",source:t.NATIONAL,dispatch:"4 y/o with difficulty breathing. Parent says the child has a known history of asthma-like wheezing.",scene:"Home living room. Parent present. No smoke or toxins. Child sitting on parent's lap.",presentation:"Alert, anxious, speaking in short phrases, audible wheeze, mild retractions. Able to follow commands.",vitals:{hr:130,rr:36,spo2:91,bp:"age-appropriate",skin:"pale, warm",gcs:"15"},startNodeId:"op03-n1",nodes:[{id:"op03-n1",prompt:"Best initial approach to this child?",options:[{id:"op03-n1-best",text:"Allow position of comfort with caregiver, assess ABCs calmly, apply oxygen as needed without forcing agitation",quality:"best",next:"op03-n2",feedback:"Correct. Keep the child calm with a caregiver; agitation worsens work of breathing."},{id:"op03-n1-ok",text:"Separate the child from the parent and lay them flat for a full exam",quality:"harmful",next:"op03-n2",feedback:"Separation and supine positioning often worsen pediatric respiratory distress.",delayedCritical:!0},{id:"op03-n1-bad",text:"Ignore SpO₂ because children always look pale",quality:"incorrect",next:"op03-n2",feedback:"Hypoxemia matters — treat and reassess oxygenation and work of breathing.",delayedCritical:!0},{id:"op03-n1-wrong",text:"Start adult-dose interventions without pediatric assessment",quality:"incorrect",next:"op03-n2",feedback:"Use pediatric assessment and EMT-scope care only; no dosing improvisation."}]},{id:"op03-n2",prompt:"SpO₂ is 91% on room air with increased work of breathing. Best next action?",options:[{id:"op03-n2-best",text:"Provide oxygen in a tolerated manner, assist with prescribed inhaler if protocol allows, prepare for transport, request ALS if available",quality:"best",next:"op03-n3",feedback:"Correct. Support oxygenation, use allowed assistive meds per protocol, and arrange higher-level care/transport."},{id:"op03-n2-ok",text:"Withhold oxygen to 'drive' breathing effort",quality:"harmful",next:"op03-n3",feedback:"Do not withhold oxygen from a hypoxemic child in distress.",delayedCritical:!0},{id:"op03-n2-bad",text:"Force a tight NRB that causes panic and breath-holding",quality:"incorrect",next:"op03-n3",feedback:"If a mask causes severe agitation, use a better-tolerated method while still supporting oxygenation."},{id:"op03-n2-wrong",text:"Advise waiting at home until the wheeze resolves on its own",quality:"harmful",next:"op03-n3",feedback:"Hypoxemic pediatric distress needs transport and ongoing assessment.",delayedCritical:!0}]},{id:"op03-n3",prompt:"En route the child becomes drowsy with slowing respirations and dropping SpO₂. What changed priority?",options:[{id:"op03-n3-best",text:"Recognize impending failure — open airway, assist ventilations with BVM as needed, rapid transport, update receiving facility",quality:"best",next:"op03-n4",feedback:"Correct. Fatigue and declining mentation signal failure — support ventilation immediately."},{id:"op03-n3-ok",text:"Assume the child is 'finally relaxing' and reduce oxygen",quality:"harmful",next:"op03-n4",feedback:"Quiet/drowsy after distress often means fatigue and failure, not improvement.",delayedCritical:!0},{id:"op03-n3-bad",text:"Stop reassessment to finish a long SAMPLE interview",quality:"incorrect",next:"op03-n4",feedback:"Life-threat changes override detailed history.",delayedCritical:!0},{id:"op03-n3-wrong",text:"Sit the child up more and wait without supporting breaths",quality:"incorrect",next:"op03-n4",feedback:"Inadequate respirations require assisted ventilation.",delayedCritical:!0}]},{id:"op03-n4",prompt:"Key reassessment focus for this pediatric respiratory patient?",options:[{id:"op03-n4-best",text:"Work of breathing, mental status, SpO₂, skin color, and response to oxygen/ventilation support",quality:"best",next:"end",feedback:"Correct. Pediatric respiratory status is tracked by effort, alertness, color, and oxygenation — not a single number."},{id:"op03-n4-ok",text:"Only blood pressure every 30 minutes",quality:"incorrect",next:"end",feedback:"BP is less useful early than respiratory effort and mentation in kids."},{id:"op03-n4-bad",text:"No further checks once oxygen is applied",quality:"incorrect",next:"end",feedback:"Always reassess after interventions — failure can develop quickly.",delayedCritical:!0},{id:"op03-n4-wrong",text:"Focus only on parental anxiety",quality:"incorrect",next:"end",feedback:"Support parents, but clinical reassessment of the child comes first."}]}],correctSequence:["Keep child calm with caregiver; assess ABCs","Oxygen as tolerated; assist allowed inhaler; transport/ALS","If fatigue/failure develops, assist ventilations","Reassess effort, mentation, SpO₂, and color"],keyTakeaway:"In pediatric respiratory distress, calm positioning and oxygen come first — a quiet tired child may be failing, not improving."}),(0,t.sc)({id:"ob-peds-04",title:"Croup vs Epiglottitis Caution",category:"ob_peds",difficulty:"critical",source:t.NATIONAL,dispatch:"3 y/o with noisy breathing and fever. Parent says the child is drooling and won't lie down.",scene:"Bedroom. Soft lighting. Parent holding child upright. No foreign body history.",presentation:"Anxious, sitting forward, drooling, muffled voice, high fever. Minimal cough. Looks toxic.",vitals:{hr:140,rr:32,spo2:94,temp:"high fever",skin:"flushed, hot",gcs:"15 (anxious)"},startNodeId:"op04-n1",nodes:[{id:"op04-n1",prompt:"This presentation raises concern for a serious upper-airway infection. Best immediate approach?",options:[{id:"op04-n1-best",text:"Keep child calm and upright with caregiver; do not agitate; avoid inspecting the throat; high-flow O₂ as tolerated; rapid gentle transport",quality:"best",next:"op04-n2",feedback:"Correct. Suspected epiglottitis: minimize agitation and never force an oral exam that may precipitate complete obstruction."},{id:"op04-n1-ok",text:"Lay the child flat and use a tongue blade to visualize the throat",quality:"harmful",next:"op04-n2",feedback:"Throat inspection and supine positioning can trigger fatal airway loss in epiglottitis.",delayedCritical:!0},{id:"op04-n1-bad",text:"Insert an OPA to 'secure' the airway while the child is still alert",quality:"harmful",next:"op04-n2",feedback:"Never force an airway adjunct into an alert child with suspected upper-airway obstruction.",delayedCritical:!0},{id:"op04-n1-wrong",text:"Treat as mild croup only and recommend home observation without transport",quality:"incorrect",next:"op04-n2",feedback:"Toxic appearance, drooling, and preference for sitting forward warrant emergency transport.",delayedCritical:!0}]},{id:"op04-n2",prompt:"How does classic croup typically differ from this concerning picture?",options:[{id:"op04-n2-best",text:"Croup more often has barky cough and stridor that may improve with calm/cool air; epiglottitis presents more toxic with drooling and muffled voice",quality:"best",next:"op04-n3",feedback:"Correct. Pattern recognition guides caution — when in doubt, treat as a fragile airway and do not agitate."},{id:"op04-n2-ok",text:"They are identical, so always examine the throat aggressively",quality:"harmful",next:"op04-n3",feedback:"Aggressive exam is never the EMT default for suspected epiglottitis.",delayedCritical:!0},{id:"op04-n2-bad",text:"Epiglottitis always has a barky cough and never fever",quality:"incorrect",next:"op04-n3",feedback:"Epiglottitis is often febrile and toxic; barky cough is more classic for croup."},{id:"op04-n2-wrong",text:"Croup never needs oxygen or transport",quality:"incorrect",next:"op04-n3",feedback:"Severe croup can still need oxygen, ALS, and transport."}]},{id:"op04-n3",prompt:"Child suddenly becomes quiet with marked stridor and poor air movement. Next action?",options:[{id:"op04-n3-best",text:"Support airway carefully, assist ventilations if needed without forcing devices that worsen obstruction, rapid transport, ALS intercept",quality:"best",next:"op04-n4",feedback:"Correct. Impending obstruction needs gentle ventilatory support and immediate definitive care — not delay for nonessential tasks."},{id:"op04-n3-ok",text:"Perform blind finger sweeps of the mouth",quality:"harmful",next:"op04-n4",feedback:"Blind sweeps can worsen obstruction and are not indicated here.",delayedCritical:!0},{id:"op04-n3-bad",text:"Have the child gargle water to 'clear' the throat",quality:"harmful",next:"op04-n4",feedback:"Oral intake and irritation can worsen a critical airway.",delayedCritical:!0},{id:"op04-n3-wrong",text:"Spend several minutes obtaining a full vaccination history before moving",quality:"incorrect",next:"op04-n4",feedback:"History can wait — airway failure is the priority.",delayedCritical:!0}]},{id:"op04-n4",prompt:"Best communication to the receiving facility?",options:[{id:"op04-n4-best",text:"Alert them early to a pediatric possible upper-airway emergency with suspected epiglottitis features and current airway status",quality:"best",next:"end",feedback:"Correct. Early notification lets the hospital prepare airway experts and equipment."},{id:"op04-n4-ok",text:"Give no radio report to avoid 'HIPAA issues'",quality:"incorrect",next:"end",feedback:"Clinical handoff for emergency care is appropriate and necessary."},{id:"op04-n4-bad",text:"Tell them it is definitely mild cold symptoms only",quality:"incorrect",next:"end",feedback:"Under-calling a critical airway delays preparation."},{id:"op04-n4-wrong",text:"Read the entire chart including unrelated family history on an open channel with no clinical focus",quality:"incorrect",next:"end",feedback:"Keep radio reports concise and clinically relevant."}]}],correctSequence:["Keep calm/upright; no throat exam; oxygen as tolerated","Differentiate toxic drooling presentation from typical croup","If worsening, gentle ventilatory support and rapid transport","Early hospital notification for pediatric airway emergency"],keyTakeaway:"Drooling, toxic appearance, and tripoding mean fragile airway — do not inspect the throat or agitate the child."}),(0,t.sc)({id:"ob-peds-05",title:"Pediatric Trauma Priorities",category:"ob_peds",difficulty:"application",source:t.NATIONAL,dispatch:"7 y/o struck by a slow-moving car in a parking lot. Conscious per bystanders.",scene:"Parking lot secured by PD. Vehicle stopped. Child on pavement with parent kneeling nearby.",presentation:"Crying, ABCs present, abrasion to forehead, guarding abdomen, deformity to left femur. Distal pulses present in injured leg.",vitals:{hr:128,rr:28,spo2:97,bp:"100/70",skin:"pale, cool",gcs:"14 (confused/crying)"},startNodeId:"op05-n1",nodes:[{id:"op05-n1",prompt:"After scene safety, what guides your primary survey?",options:[{id:"op05-n1-best",text:"XABC approach: control major hemorrhage, airway with C-spine consideration, breathing, circulation/perfusion, disability, expose as needed",quality:"best",next:"op05-n2",feedback:"Correct. Pediatric trauma still follows life-threat order with spinal motion awareness."},{id:"op05-n1-ok",text:"Splint the femur before checking airway and breathing",quality:"incorrect",next:"op05-n2",feedback:"Life threats and ABCs come before isolated extremity care.",delayedCritical:!0},{id:"op05-n1-bad",text:"Assume children cannot be in shock if BP is 'normal'",quality:"incorrect",next:"op05-n2",feedback:"Kids compensate — tachycardia and pale/cool skin can signal shock before hypotension.",delayedCritical:!0},{id:"op05-n1-wrong",text:"Skip spinal precautions because the child is crying",quality:"incorrect",next:"op05-n2",feedback:"Significant MOI warrants spinal motion restriction decisions regardless of crying."}]},{id:"op05-n2",prompt:"Abdomen is tender and the child is tachycardic and pale. Femur is deformed. Priority packaging?",options:[{id:"op05-n2-best",text:"Treat as multi-system trauma: high-priority transport, spinal motion restriction as indicated, stabilize femur en route if time allows, keep warm",quality:"best",next:"op05-n3",feedback:"Correct. Suspected internal bleeding plus long-bone injury = load-and-go priorities with warmth and ongoing ABCs."},{id:"op05-n2-ok",text:"Stay on scene for a detailed head-to-toe before any movement",quality:"incorrect",next:"op05-n3",feedback:"Unstable multi-system pediatric trauma needs rapid transport after life threats are addressed.",delayedCritical:!0},{id:"op05-n2-bad",text:"Give oral fluids because the child says they are thirsty",quality:"harmful",next:"op05-n3",feedback:"NPO in trauma with possible surgical needs; oral fluids risk aspiration and delay.",delayedCritical:!0},{id:"op05-n2-wrong",text:"Focus only on the femur and ignore abdominal findings",quality:"incorrect",next:"op05-n3",feedback:"Abdominal injury can be the life threat — do not fixate on the obvious deformity.",delayedCritical:!0}]},{id:"op05-n3",prompt:"Parent is distraught and interfering with care. Best approach?",options:[{id:"op05-n3-best",text:"Assign someone to calmly update the parent, keep them informed, and allow presence if it calms the child without blocking care",quality:"best",next:"op05-n4",feedback:"Correct. Caregiver presence often helps pediatric patients when it does not compromise care."},{id:"op05-n3-ok",text:"Yell at the parent to leave immediately without explanation",quality:"incorrect",next:"op05-n4",feedback:"Clear, calm boundaries work better than confrontation."},{id:"op05-n3-bad",text:"Stop patient care until the parent finishes a long argument",quality:"harmful",next:"op05-n4",feedback:"Do not pause critical trauma care for nonessential conflict.",delayedCritical:!0},{id:"op05-n3-wrong",text:"Ask the child alone for consent to refuse transport",quality:"incorrect",next:"op05-n4",feedback:"Minors generally cannot refuse needed emergency care; involve a parent/guardian and follow protocol."}]},{id:"op05-n4",prompt:"En route, what reassessment finding would most increase urgency?",options:[{id:"op05-n4-best",text:"Rising HR, worsening pallor, altered mentation, or increasing abdominal distention/pain",quality:"best",next:"end",feedback:"Correct. Signs of decompensating shock or head injury demand immediate recognition and hospital update."},{id:"op05-n4-ok",text:"A single stable SpO₂ reading with no other checks",quality:"incorrect",next:"end",feedback:"Trends across multiple signs matter more than one number."},{id:"op05-n4-bad",text:"Improved crying alone without vital sign trends",quality:"incorrect",next:"end",feedback:"Crying can coexist with serious injury — track perfusion and mentation."},{id:"op05-n4-wrong",text:"No need to reassess until arrival",quality:"incorrect",next:"end",feedback:"Trauma patients require frequent reassessment.",delayedCritical:!0}]}],correctSequence:["Primary survey with hemorrhage/ABC priorities and spinal awareness","Treat as multi-system trauma; rapid transport; stabilize limb as able","Manage caregiver presence to support the child","Reassess for shock and mentation changes"],keyTakeaway:"Pediatric trauma: kids hide shock — prioritize ABCs, warmth, and rapid transport over prolonged on-scene extremity care."}),(0,t.sc)({id:"ob-peds-06",title:"Complicated Delivery — Breech",category:"ob_peds",difficulty:"critical",source:t.NATIONAL,dispatch:"32 y/o female in labor. Caller thinks 'the feet are coming first.'",scene:"Bathroom floor. Partner assisting. Crowding but manageable. ALS 15 minutes out.",presentation:"Feet/buttocks presenting. Mother pushing. Head not yet delivered. Cord not visible. Mother exhausted but alert.",vitals:{hr:120,rr:24,bp:"132/84",spo2:97,skin:"diaphoretic",gcs:"15"},startNodeId:"op06-n1",nodes:[{id:"op06-n1",prompt:"You recognize a breech presentation. Best EMT action?",options:[{id:"op06-n1-best",text:"Support the presenting parts; do not pull; create an airway for the baby if the head is delayed; rapid transport / ALS; prepare for newborn care",quality:"best",next:"op06-n2",feedback:"Correct. Breech is a complicated delivery — support, avoid traction, and move toward definitive care while managing the airway if needed."},{id:"op06-n1-ok",text:"Pull hard on the legs to speed delivery of the head",quality:"harmful",next:"op06-n2",feedback:"Never pull on a breech infant — traction causes injury.",delayedCritical:!0},{id:"op06-n1-bad",text:"Push the presenting parts back in and tell the mother to wait hours",quality:"harmful",next:"op06-n2",feedback:"Do not attempt to replace presenting parts or delay needed care.",delayedCritical:!0},{id:"op06-n1-wrong",text:"Treat exactly like a normal uncomplicated cephalic delivery with no extra caution",quality:"incorrect",next:"op06-n2",feedback:"Breech requires recognition as complicated and different handling."}]},{id:"op06-n2",prompt:"The body delivers but the head is entrapped. You were trained to form an airway. What is the concept?",options:[{id:"op06-n2-best",text:"Use a gloved hand to create a space for the newborn's airway (V-shaped fingers elevating the vaginal wall off the face) while avoiding pulling on the body",quality:"best",next:"op06-n3",feedback:"Correct. If the head is delayed, maintain an airway space for the infant and continue support without traction."},{id:"op06-n2-ok",text:"Insert an adult OPA into the mother to help the baby breathe",quality:"harmful",next:"op06-n3",feedback:"That does not create a neonatal airway and can injure the mother.",delayedCritical:!0},{id:"op06-n2-bad",text:"Twist and yank the torso forcefully",quality:"harmful",next:"op06-n3",feedback:"Forceful manipulation risks catastrophic injury.",delayedCritical:!0},{id:"op06-n2-wrong",text:"Cover the infant's face tightly with a towel until the head delivers",quality:"harmful",next:"op06-n3",feedback:"Do not obstruct the infant's airway — maintain a patent path for air.",delayedCritical:!0}]},{id:"op06-n3",prompt:"Delivery completes. Newborn is floppy and not crying. Immediate focus?",options:[{id:"op06-n3-best",text:"Neonatal resuscitation sequence: warm/dry/stimulate, open airway, ventilate if needed; continue maternal support",quality:"best",next:"op06-n4",feedback:"Correct. Complicated deliveries often yield depressed newborns — be ready to resuscitate."},{id:"op06-n3-ok",text:"Assume the newborn is fine because the mother is talking",quality:"incorrect",next:"op06-n4",feedback:"Assess the newborn independently every time.",delayedCritical:!0},{id:"op06-n3-bad",text:"Shake the infant vigorously by the shoulders",quality:"harmful",next:"op06-n4",feedback:"Do not shake — use appropriate tactile stimulation and airway support.",delayedCritical:!0},{id:"op06-n3-wrong",text:"Place the infant face-down in fluid without clearing the airway",quality:"harmful",next:"op06-n4",feedback:"Position for airway patency and clear secretions as needed.",delayedCritical:!0}]},{id:"op06-n4",prompt:"Transport priority after breech delivery?",options:[{id:"op06-n4-best",text:"High priority for mother and newborn; keep warm; monitor bleeding; early hospital notification about breech/complicated delivery",quality:"best",next:"end",feedback:"Correct. Complicated delivery warrants priority transport and a clear handoff."},{id:"op06-n4-ok",text:"Non-urgent transport with no hospital notification",quality:"incorrect",next:"end",feedback:"Breech and possible neonatal depression are urgent.",delayedCritical:!0},{id:"op06-n4-bad",text:"Release both patients home without evaluation",quality:"harmful",next:"end",feedback:"Both need emergency evaluation after complicated delivery.",delayedCritical:!0},{id:"op06-n4-wrong",text:"Transport mother only; leave newborn on scene",quality:"harmful",next:"end",feedback:"Never abandon the newborn.",delayedCritical:!0}]}],correctSequence:["Recognize breech; support without pulling; rapid transport/ALS","Maintain neonatal airway space if head entrapped","Resuscitate depressed newborn; support mother","Priority transport with early hospital notification"],keyTakeaway:"Breech: support, never pull, maintain an airway for the baby if the head is delayed, and expect a depressed newborn."}),(0,t.sc)({id:"assessment-01",title:"Scene Size-Up Essentials",category:"assessment",difficulty:"foundational",source:t.NATIONAL,dispatch:"Unknown medical emergency in an alley behind a bar. Caller hung up.",scene:"Night. Dim alley. Two bystanders arguing near a person on the ground. Broken glass. Possible smell of alcohol.",presentation:"From a distance: adult male supine, not obviously moving. Crowd tense. No PD on scene yet.",startNodeId:"as01-n1",nodes:[{id:"as01-n1",prompt:"You arrive first. What is your first priority?",options:[{id:"as01-n1-best",text:"Scene size-up: safety/BSI, mechanism/nature, number of patients, need for additional resources/PD, consider C-spine",quality:"best",next:"as01-n2",feedback:"Correct. Never commit to patient contact before sizing up hazards, resources, and NOI/MOI."},{id:"as01-n1-ok",text:"Rush directly to the patient without scanning for hazards or backup needs",quality:"harmful",next:"as01-n2",feedback:"An unsafe scene can create more patients. Size-up first.",delayedCritical:!0},{id:"as01-n1-bad",text:"Start a detailed neurologic exam from 50 feet away without requesting help",quality:"incorrect",next:"as01-n2",feedback:"You cannot complete a proper exam from afar — secure the scene and resources first."},{id:"as01-n1-wrong",text:"Ignore bystanders and assume the scene is safe because dispatch said 'medical'",quality:"incorrect",next:"as01-n2",feedback:"Dispatch labels can be wrong — verify safety yourself.",delayedCritical:!0}]},{id:"as01-n2",prompt:"Bystanders become aggressive as you approach. Best action?",options:[{id:"as01-n2-best",text:"Withdraw to a safe location, request law enforcement, stage until the scene is secure",quality:"best",next:"as01-n3",feedback:"Correct. If the scene turns unsafe, leave and wait for PD — your safety enables care."},{id:"as01-n2-ok",text:"Physically confront the bystanders to 'take control'",quality:"harmful",next:"as01-n3",feedback:"Do not escalate violence. Stage and wait for law enforcement.",delayedCritical:!0},{id:"as01-n2-bad",text:"Kneel with your back to the crowd while focusing only on the patient",quality:"harmful",next:"as01-n3",feedback:"Maintain situational awareness; request help if threatened.",delayedCritical:!0},{id:"as01-n2-wrong",text:"Cancel the call and leave without notifying anyone",quality:"incorrect",next:"as01-n3",feedback:"Stage safely and coordinate with dispatch/PD — do not abandon coordination."}]},{id:"as01-n3",prompt:"PD clears the scene. Patient is unresponsive. Next size-up/decision point?",options:[{id:"as01-n3-best",text:"Confirm BSI, consider MOI (fall/assault), request ALS if needed, begin primary assessment with C-spine as indicated",quality:"best",next:"as01-n4",feedback:"Correct. Once safe, complete size-up elements and move into the primary survey."},{id:"as01-n3-ok",text:"Skip primary assessment and start a 20-minute SAMPLE with bystanders only",quality:"incorrect",next:"as01-n4",feedback:"Unresponsive patients need ABCs first.",delayedCritical:!0},{id:"as01-n3-bad",text:"Assume single patient without looking for others",quality:"incorrect",next:"as01-n4",feedback:"Always estimate number of patients during size-up."},{id:"as01-n3-wrong",text:"Remove gloves because the alley 'looks clean'",quality:"harmful",next:"as01-n4",feedback:"Maintain BSI for body fluid exposure risk.",delayedCritical:!0}]},{id:"as01-n4",prompt:"Which statement best reflects scene size-up?",options:[{id:"as01-n4-best",text:"It is continuous — hazards and resource needs can change throughout the call",quality:"best",next:"end",feedback:"Correct. Size-up is not a one-time checkbox."},{id:"as01-n4-ok",text:"It ends the moment you touch the patient",quality:"incorrect",next:"end",feedback:"Continue scanning for hazards and changing conditions."},{id:"as01-n4-bad",text:"Only drivers perform size-up; clinicians never do",quality:"incorrect",next:"end",feedback:"Every provider shares responsibility for scene safety."},{id:"as01-n4-wrong",text:"Size-up is optional on 'routine' calls",quality:"incorrect",next:"end",feedback:"Every call needs a size-up."}]}],correctSequence:["Perform full scene size-up before patient contact","Stage if scene becomes unsafe; request PD","When clear, BSI + MOI + resources + primary survey","Treat size-up as continuous"],keyTakeaway:"Scene size-up first and always — unsafe scenes create more patients."}),(0,t.sc)({id:"assessment-02",title:"Primary Survey — ABCs",category:"assessment",difficulty:"foundational",source:t.NATIONAL,dispatch:"55 y/o female found unresponsive at home. Family says she collapsed after standing up.",scene:"Living room. Family present. No obvious hazards. Patient on carpet.",presentation:"Unresponsive to voice. Snoring respirations. Skin pale and sweaty. Radial pulse rapid and weak.",vitals:{hr:120,rr:"snoring, 8",spo2:84,bp:"88/54",skin:"pale, diaphoretic",gcs:"3–7 (unresponsive)"},startNodeId:"as02-n1",nodes:[{id:"as02-n1",prompt:"After BSI/scene safety, what is your first primary-assessment action?",options:[{id:"as02-n1-best",text:"Open/maintain airway (consider trauma), assess breathing adequacy, support ventilation/oxygenation, then evaluate circulation",quality:"best",next:"as02-n2",feedback:"Correct. Airway and breathing threats come immediately in the primary survey."},{id:"as02-n1-ok",text:"Obtain a full OPQRST before touching the airway",quality:"incorrect",next:"as02-n2",feedback:"Unresponsive patients cannot give OPQRST — fix ABCs first.",delayedCritical:!0},{id:"as02-n1-bad",text:"Check blood glucose before opening a snoring airway",quality:"incorrect",next:"as02-n2",feedback:"Airway patency precedes secondary tests.",delayedCritical:!0},{id:"as02-n1-wrong",text:"Assume snoring is normal sleep and walk away",quality:"harmful",next:"as02-n2",feedback:"Snoring in an unresponsive patient signals obstruction.",delayedCritical:!0}]},{id:"as02-n2",prompt:"Airway opens with positioning; respirations remain slow and shallow. SpO₂ 84%. Next?",options:[{id:"as02-n2-best",text:"Assist ventilations with BVM and supplemental oxygen; reassess chest rise and pulse",quality:"best",next:"as02-n3",feedback:"Correct. Inadequate breathing requires assisted ventilation, not passive observation."},{id:"as02-n2-ok",text:"Apply a nasal cannula at minimal flow and wait 20 minutes",quality:"incorrect",next:"as02-n3",feedback:"Hypoventilation needs assisted breaths.",delayedCritical:!0},{id:"as02-n2-bad",text:"Insert an OPA in a patient with an intact gag without assessing",quality:"incorrect",next:"as02-n3",feedback:"OPA only if no gag; choose adjunct appropriately."},{id:"as02-n2-wrong",text:"Focus only on getting a 12-lead before supporting breathing",quality:"incorrect",next:"as02-n3",feedback:"Breathing support outranks diagnostic extras at EMT level here.",delayedCritical:!0}]},{id:"as02-n3",prompt:"Circulation: pale, sweaty, BP 88/54, weak rapid radial. What does this indicate for priority?",options:[{id:"as02-n3-best",text:"Shock / unstable — treat life threats, keep warm, rapid transport, ALS intercept, frequent reassessment",quality:"best",next:"as02-n4",feedback:"Correct. Hypotension with poor perfusion is a high-priority patient."},{id:"as02-n3-ok",text:"Stable — no rush, complete a leisurely secondary exam on scene",quality:"incorrect",next:"as02-n4",feedback:"This patient is unstable.",delayedCritical:!0},{id:"as02-n3-bad",text:"Give oral fluids to raise blood pressure",quality:"harmful",next:"as02-n4",feedback:"Unresponsive/hypotensive patients should not receive oral fluids.",delayedCritical:!0},{id:"as02-n3-wrong",text:"Ignore skin signs because BP is the only perfusion measure",quality:"incorrect",next:"as02-n4",feedback:"Skin, mentation, and pulse quality matter with BP."}]},{id:"as02-n4",prompt:"After ABCs are supported, how do you decide disability/exposure next?",options:[{id:"as02-n4-best",text:"Quick neurologic check (AVPU/GCS/pupils), expose to find hidden life threats, then package for transport",quality:"best",next:"end",feedback:"Correct. Primary survey includes a rapid disability check and exposure for hidden problems."},{id:"as02-n4-ok",text:"Skip disability because you already know they are sick",quality:"incorrect",next:"end",feedback:"A brief neuro check still guides care and handoff."},{id:"as02-n4-bad",text:"Fully undress outdoors in freezing weather without covering",quality:"harmful",next:"end",feedback:"Expose to examine, then cover to prevent hypothermia."},{id:"as02-n4-wrong",text:"End the primary survey before addressing inadequate breathing",quality:"incorrect",next:"end",feedback:"You cannot complete primary survey while leaving ABCs uncorrected.",delayedCritical:!0}]}],correctSequence:["Open airway and assess breathing first","Assist inadequate ventilations with O₂/BVM","Recognize shock and set high transport priority","Rapid disability/exposure then package"],keyTakeaway:"Primary survey fixes airway, breathing, and circulation threats before detailed history."}),(0,t.sc)({id:"assessment-03",title:"SAMPLE Timing",category:"assessment",difficulty:"foundational",source:t.NATIONAL,dispatch:"40 y/o male, mild abdominal pain, sitting upright, talking clearly.",scene:"Office break room. Stable environment. One coworker present.",presentation:"Alert, conversant, mild lower abdominal discomfort for 2 hours. No respiratory distress. Skin warm/dry.",vitals:{hr:88,rr:16,spo2:98,bp:"128/78",skin:"warm, dry",gcs:"15"},startNodeId:"as03-n1",nodes:[{id:"as03-n1",prompt:"Patient is stable after a quick primary survey. When should SAMPLE be obtained?",options:[{id:"as03-n1-best",text:"After life threats are ruled out/managed — during the history/secondary assessment on a stable patient",quality:"best",next:"as03-n2",feedback:"Correct. SAMPLE supports the secondary survey once ABCs are intact."},{id:"as03-n1-ok",text:"Before checking whether the patient can speak or breathe",quality:"incorrect",next:"as03-n2",feedback:"Never delay primary survey for a full SAMPLE on a potentially unstable patient.",delayedCritical:!0},{id:"as03-n1-bad",text:"Only after hospital arrival — EMTs never take history",quality:"incorrect",next:"as03-n2",feedback:"EMTs gather SAMPLE/OPQRST when appropriate."},{id:"as03-n1-wrong",text:"Instead of vital signs forever",quality:"incorrect",next:"as03-n2",feedback:"History complements vitals; it does not replace them."}]},{id:"as03-n2",prompt:"Which SAMPLE element is especially important before assisting with a patient's prescribed medication (per protocol)?",options:[{id:"as03-n2-best",text:"Medications and allergies (plus pertinent history) — know what they take and what they cannot take",quality:"best",next:"as03-n3",feedback:"Correct. M and A in SAMPLE are critical before medication assistance."},{id:"as03-n2-ok",text:"Only their favorite food (Events unrelated)",quality:"incorrect",next:"as03-n3",feedback:"Focus on clinically relevant SAMPLE elements."},{id:"as03-n2-bad",text:"Skip allergies because protocols never mention them",quality:"harmful",next:"as03-n3",feedback:"Allergy history prevents harmful exposures.",delayedCritical:!0},{id:"as03-n2-wrong",text:"Last meal only — ignore medications",quality:"incorrect",next:"as03-n3",feedback:"Last oral intake matters for some patients, but meds/allergies are essential for medication decisions."}]},{id:"as03-n3",prompt:"Mid-SAMPLE the patient becomes pale, diaphoretic, and hypotensive. What do you do with history-taking?",options:[{id:"as03-n3-best",text:"Pause detailed history, return to primary survey/interventions, and resume SAMPLE later as able",quality:"best",next:"as03-n4",feedback:"Correct. Changing condition resets priorities to ABCs and transport."},{id:"as03-n3-ok",text:"Finish every SAMPLE letter before treating shock",quality:"harmful",next:"as03-n4",feedback:"Do not finish a checklist while the patient decompensates.",delayedCritical:!0},{id:"as03-n3-bad",text:"Discard all history already obtained",quality:"incorrect",next:"as03-n4",feedback:"Keep useful information; just reprioritize care."},{id:"as03-n3-wrong",text:"Argue with the patient about inconsistent answers",quality:"incorrect",next:"as03-n4",feedback:"Treat the deterioration; clarify history later."}]},{id:"as03-n4",prompt:"Best description of SAMPLE?",options:[{id:"as03-n4-best",text:"Signs/Symptoms, Allergies, Medications, Past history, Last oral intake, Events — a structured history tool",quality:"best",next:"end",feedback:"Correct. SAMPLE organizes essential history without replacing the primary survey."},{id:"as03-n4-ok",text:"A trauma-only exam of the spine",quality:"incorrect",next:"end",feedback:"SAMPLE is a history mnemonic for medical and trauma patients."},{id:"as03-n4-bad",text:"A replacement for vital signs",quality:"incorrect",next:"end",feedback:"You still need vitals and physical assessment."},{id:"as03-n4-wrong",text:"Only for pediatric patients",quality:"incorrect",next:"end",feedback:"SAMPLE applies across age groups."}]}],correctSequence:["Obtain SAMPLE after ABCs on a stable patient","Prioritize meds/allergies before assisting meds","Interrupt history if the patient destabilizes","Know what SAMPLE stands for"],keyTakeaway:"SAMPLE belongs after life threats — and must yield if the patient becomes unstable."}),(0,t.sc)({id:"assessment-04",title:"OPQRST for Chest Pain",category:"assessment",difficulty:"application",source:t.NATIONAL,dispatch:"60 y/o male with chest discomfort. Conscious and breathing.",scene:"Home recliner. Wife present. No hazards.",presentation:"Alert, mild distress, clutching center of chest. Skin slightly pale. Denies trauma.",vitals:{hr:96,rr:18,spo2:95,bp:"148/90",skin:"pale, cool",gcs:"15"},startNodeId:"as04-n1",nodes:[{id:"as04-n1",prompt:"Primary survey is intact. You begin OPQRST. What does the 'O' ask?",options:[{id:"as04-n1-best",text:"Onset — what were you doing when it started, and did it begin suddenly or gradually?",quality:"best",next:"as04-n2",feedback:"Correct. Onset clarifies timing and context of the symptom."},{id:"as04-n1-ok",text:"Oxygen saturation only",quality:"incorrect",next:"as04-n2",feedback:"O in OPQRST is Onset, not oxygen."},{id:"as04-n1-bad",text:"Ignore onset because chest pain is always the same",quality:"incorrect",next:"as04-n2",feedback:"Onset details help risk stratification and handoff."},{id:"as04-n1-wrong",text:"Ask only about allergies at this step",quality:"incorrect",next:"as04-n2",feedback:"Allergies are SAMPLE; onset is OPQRST."}]},{id:"as04-n2",prompt:"Patient says pressure-like pain 7/10 radiating to the left arm. Which OPQRST elements did you just capture?",options:[{id:"as04-n2-best",text:"Quality (pressure), Severity (7/10), and Region/Radiation (chest to arm)",quality:"best",next:"as04-n3",feedback:"Correct. Those descriptors map to Q, S, and R."},{id:"as04-n2-ok",text:"Only Events leading up — nothing else",quality:"incorrect",next:"as04-n3",feedback:"Events is SAMPLE; you obtained quality, severity, and radiation."},{id:"as04-n2-bad",text:"Provocation only",quality:"incorrect",next:"as04-n3",feedback:"Provocation asks what makes it better/worse — not described here."},{id:"as04-n2-wrong",text:"None of OPQRST applies to chest pain",quality:"incorrect",next:"as04-n3",feedback:"OPQRST is classic for pain/discomfort complaints."}]},{id:"as04-n3",prompt:"While finishing OPQRST, SpO₂ drops to 88% and the patient becomes diaphoretic and nauseated. Next?",options:[{id:"as04-n3-best",text:"Treat the deterioration: oxygen per protocol, position of comfort, rapid transport/ALS — finish remaining history en route",quality:"best",next:"as04-n4",feedback:"Correct. Worsening cardiopulmonary status outranks completing a mnemonic on scene."},{id:"as04-n3-ok",text:"Refuse to treat until every OPQRST letter is perfect",quality:"harmful",next:"as04-n4",feedback:"Do not delay care for a complete interview.",delayedCritical:!0},{id:"as04-n3-bad",text:"Have the patient walk to the ambulance to 'test' the pain",quality:"harmful",next:"as04-n4",feedback:"Minimize exertion in suspected cardiac ischemia.",delayedCritical:!0},{id:"as04-n3-wrong",text:"Stop monitoring SpO₂ because OPQRST is more important",quality:"incorrect",next:"as04-n4",feedback:"Vitals and oxygenation guide priority continuously.",delayedCritical:!0}]},{id:"as04-n4",prompt:"What belongs in a concise handoff from your OPQRST?",options:[{id:"as04-n4-best",text:"Onset time, quality, radiation, severity, and what makes it better/worse — plus key vitals and treatments",quality:"best",next:"end",feedback:"Correct. A focused OPQRST summary improves cardiac handoffs."},{id:"as04-n4-ok",text:"Only the patient's insurance status",quality:"incorrect",next:"end",feedback:"Clinical symptom details matter for emergency care."},{id:"as04-n4-bad",text:"Unrelated childhood stories with no symptom details",quality:"incorrect",next:"end",feedback:"Keep the report clinically relevant."},{id:"as04-n4-wrong",text:"Nothing — hospitals dislike OPQRST",quality:"incorrect",next:"end",feedback:"Structured symptom history is valued."}]}],correctSequence:["Use Onset correctly in OPQRST","Map quality/severity/radiation to the mnemonic","Interrupt history for clinical deterioration","Handoff key OPQRST findings with vitals/treatments"],keyTakeaway:"OPQRST structures pain history — but ABCs and oxygenation still come first if the patient worsens."}),(0,t.sc)({id:"assessment-05",title:"Reassessment After Intervention",category:"assessment",difficulty:"application",source:t.NATIONAL,dispatch:"22 y/o with allergic reaction after a bee sting. History of anaphylaxis; has an epinephrine auto-injector.",scene:"Park picnic area. Safe. Friend present with the patient's prescribed auto-injector.",presentation:"Anxious, hives, mild lip swelling, wheezing, speaking in full sentences initially.",vitals:{hr:118,rr:24,spo2:93,bp:"100/70",skin:"flushed with urticaria",gcs:"15"},startNodeId:"as05-n1",nodes:[{id:"as05-n1",prompt:"Per protocol you assist with the prescribed epinephrine auto-injector and provide oxygen. What must you do next?",options:[{id:"as05-n1-best",text:"Reassess ABCs, mental status, work of breathing, skin findings, and vitals; note time of medication; prepare for transport/ALS",quality:"best",next:"as05-n2",feedback:"Correct. Every intervention requires reassessment of response and possible deterioration."},{id:"as05-n1-ok",text:"Assume permanent improvement and stop monitoring",quality:"harmful",next:"as05-n2",feedback:"Anaphylaxis can rebound — continue reassessment.",delayedCritical:!0},{id:"as05-n1-bad",text:"Immediately give a second unrelated household medication without protocol",quality:"harmful",next:"as05-n2",feedback:"Stay within EMT scope and protocols.",delayedCritical:!0},{id:"as05-n1-wrong",text:"Leave the patient alone in the park for 30 minutes",quality:"harmful",next:"as05-n2",feedback:"Do not abandon a patient after epinephrine.",delayedCritical:!0}]},{id:"as05-n2",prompt:"Two minutes later, wheezing lessens and SpO₂ rises to 97%, but BP is now 84/50 and the patient is dizzy. Interpretation?",options:[{id:"as05-n2-best",text:"Partial respiratory improvement with ongoing shock — continue support, rapid transport, ALS, frequent reassessment",quality:"best",next:"as05-n3",feedback:"Correct. Improvement in one system does not mean the patient is stable overall."},{id:"as05-n2-ok",text:"Fully cured — cancel ALS and recommend walking home",quality:"harmful",next:"as05-n3",feedback:"Hypotension after anaphylaxis remains an emergency.",delayedCritical:!0},{id:"as05-n2-bad",text:"Ignore BP because breathing sounds better",quality:"incorrect",next:"as05-n3",feedback:"Reassessment must include circulation.",delayedCritical:!0},{id:"as05-n2-wrong",text:"Only reassess once per hour for anaphylaxis",quality:"incorrect",next:"as05-n3",feedback:"Unstable patients need frequent reassessment (often every 5 minutes)."}]},{id:"as05-n3",prompt:"How often should you reassess an unstable patient en route?",options:[{id:"as05-n3-best",text:"About every 5 minutes (or more often if changing), including vitals and ABCs",quality:"best",next:"as05-n4",feedback:"Correct. Unstable patients get frequent reassessment; stable patients about every 15 minutes."},{id:"as05-n3-ok",text:"Only at the hospital door",quality:"incorrect",next:"as05-n4",feedback:"Reassess throughout transport.",delayedCritical:!0},{id:"as05-n3-bad",text:"Never — initial vitals are enough forever",quality:"incorrect",next:"as05-n4",feedback:"Trends matter more than a single set."},{id:"as05-n3-wrong",text:"Every 2 hours regardless of condition",quality:"incorrect",next:"as05-n4",feedback:"That interval is far too long for EMS care."}]},{id:"as05-n4",prompt:"What should your reassessment documentation include?",options:[{id:"as05-n4-best",text:"Time of intervention, response (better/worse/unchanged), repeat vitals, and any new treatments",quality:"best",next:"end",feedback:"Correct. Clear before/after comparison supports continuity of care."},{id:"as05-n4-ok",text:"Only that 'patient fine' with no details",quality:"incorrect",next:"end",feedback:"Be specific about findings and times."},{id:"as05-n4-bad",text:"Fabricated normal vitals to save time",quality:"harmful",next:"end",feedback:"Falsifying documentation is unethical and illegal.",delayedCritical:!0},{id:"as05-n4-wrong",text:"Nothing about medications given",quality:"incorrect",next:"end",feedback:"Medication time and response are essential."}]}],correctSequence:["Reassess after epinephrine/oxygen","Recognize partial improvement with ongoing shock","Reassess unstable patients about every 5 minutes","Document times, response, and repeat vitals"],keyTakeaway:"Interventions demand reassessment — one improving sign does not equal a stable patient."}),(0,t.sc)({id:"assessment-06",title:"Transport Priority Decision",category:"assessment",difficulty:"application",source:t.NATIONAL,dispatch:"Two patients from a minor parking-lot collision. You are assigned Patient A.",scene:"Parking lot, low speed. PD on scene. Your patient is in a vehicle with airbag deployment.",presentation:"Patient A: 70 y/o, seat-belted, confused from baseline per spouse, BP 78/50, HR 112, chest wall tenderness.",vitals:{hr:112,rr:22,spo2:94,bp:"78/50",skin:"pale, cool",gcs:"13 (confused)"},startNodeId:"as06-n1",nodes:[{id:"as06-n1",prompt:"Based on presentation, what transport priority is appropriate?",options:[{id:"as06-n1-best",text:"High priority — signs of shock and altered mentation after blunt trauma warrant rapid transport",quality:"best",next:"as06-n2",feedback:"Correct. Unstable vitals and mental status change drive priority transport."},{id:"as06-n1-ok",text:"Low priority because the crash looked minor",quality:"incorrect",next:"as06-n2",feedback:"Mechanism can be misleading — patient condition drives priority.",delayedCritical:!0},{id:"as06-n1-bad",text:"No transport — advise driving home",quality:"harmful",next:"as06-n2",feedback:"Hypotensive trauma patients need emergency care.",delayedCritical:!0},{id:"as06-n1-wrong",text:"Priority is based only on who called 911 first",quality:"incorrect",next:"as06-n2",feedback:"Clinical status and triage principles guide priority."}]},{id:"as06-n2",prompt:"On-scene time is climbing while a detailed secondary exam continues. Best adjustment?",options:[{id:"as06-n2-best",text:"Limit on-scene interventions to life threats; perform detailed exam en route; notify hospital early",quality:"best",next:"as06-n3",feedback:"Correct. For unstable trauma, shorten scene time after critical interventions."},{id:"as06-n2-ok",text:"Remain on scene until a perfect head-to-toe is finished in every detail",quality:"incorrect",next:"as06-n3",feedback:"Perfection on scene delays definitive care.",delayedCritical:!0},{id:"as06-n2-bad",text:"Wait for the patient's preferred hospital across town with a long delay despite instability",quality:"incorrect",next:"as06-n3",feedback:"Unstable patients go to the closest appropriate facility per protocol.",delayedCritical:!0},{id:"as06-n2-wrong",text:"Cancel ALS because you 'might' finish sooner alone",quality:"incorrect",next:"as06-n3",feedback:"Unstable trauma often benefits from ALS intercept when available."}]},{id:"as06-n3",prompt:"Spouse asks to ride along and talks continuously. How do you protect priority care?",options:[{id:"as06-n3-best",text:"Allow if policy/safety permit, set clear expectations, keep focus on ABCs and rapid transport",quality:"best",next:"as06-n4",feedback:"Correct. Family can help with history if they do not impede care."},{id:"as06-n3-ok",text:"Stop resuscitation tasks to debate destination for 20 minutes",quality:"harmful",next:"as06-n4",feedback:"Do not delay critical transport for nonessential debate.",delayedCritical:!0},{id:"as06-n3-bad",text:"Refuse all history from the spouse even when the patient is confused",quality:"incorrect",next:"as06-n4",feedback:"Collateral history is valuable when the patient cannot provide it."},{id:"as06-n3-wrong",text:"Let the spouse drive the ambulance",quality:"harmful",next:"as06-n4",feedback:"Only qualified personnel operate the ambulance.",delayedCritical:!0}]},{id:"as06-n4",prompt:"Which finding would most justify downgrading urgency (if truly present)?",options:[{id:"as06-n4-best",text:"None of these in this patient — persistent hypotension and confusion keep priority high",quality:"best",next:"end",feedback:"Correct. Do not downgrade while shock and altered mentation persist."},{id:"as06-n4-ok",text:"Any single smile from the patient regardless of BP",quality:"incorrect",next:"end",feedback:"Affect does not override vital-sign evidence of shock."},{id:"as06-n4-bad",text:"Insurance preference alone",quality:"incorrect",next:"end",feedback:"Clinical priority is not set by insurance."},{id:"as06-n4-wrong",text:"A bystander saying 'they look fine'",quality:"incorrect",next:"end",feedback:"Use your assessment, not casual opinions."}]}],correctSequence:["Assign high priority for shock + altered mentation","Shorten scene time; detailed exam en route","Manage family without delaying care","Do not downgrade while instability persists"],keyTakeaway:"Transport priority follows patient condition — unstable vitals mean load-and-go after life threats."}),(0,t.sc)({id:"operations-01",title:"Ambulance Positioning & Scene Safety",category:"operations",difficulty:"foundational",source:t.NATIONAL,dispatch:"MVC on a two-lane highway, unknown injuries. PD ETA 5 minutes.",scene:"Daytime. Moderate traffic. Disabled vehicle in the right lane. You are first EMS unit.",presentation:"From approach: vehicle with rear damage, occupants still inside, traffic streaming past.",startNodeId:"ops01-n1",nodes:[{id:"ops01-n1",prompt:"Where should you position the ambulance initially?",options:[{id:"ops01-n1-best",text:"Uphill/upwind when relevant, create a protective barrier (fend-off position) between traffic and the work area, leave egress, use lights thoughtfully",quality:"best",next:"ops01-n2",feedback:"Correct. Position to shield providers and patients while preserving an exit path."},{id:"ops01-n1-ok",text:"Park in a blind curve on the opposite shoulder with no warning to traffic",quality:"harmful",next:"ops01-n2",feedback:"Poor positioning invites secondary crashes.",delayedCritical:!0},{id:"ops01-n1-bad",text:"Block both directions completely without coordinating with PD when alternatives exist",quality:"incorrect",next:"ops01-n2",feedback:"Coordinate traffic control; avoid creating worse hazards when possible."},{id:"ops01-n1-wrong",text:"Leave the ambulance in drive unattended in the travel lane",quality:"harmful",next:"ops01-n2",feedback:"Secure the vehicle; never leave it uncontrolled in traffic.",delayedCritical:!0}]},{id:"ops01-n2",prompt:"Before exiting into traffic, what personal protective action is essential?",options:[{id:"ops01-n2-best",text:"High-visibility ANSI/ISEA class vest/jacket as required, eyewear as needed, scan for traffic, exit away from moving lanes when possible",quality:"best",next:"ops01-n3",feedback:"Correct. Visibility and traffic awareness reduce struck-by injuries."},{id:"ops01-n2-ok",text:"Dark clothing at dusk with earbuds in both ears",quality:"harmful",next:"ops01-n3",feedback:"Stay visible and able to hear hazards.",delayedCritical:!0},{id:"ops01-n2-bad",text:"Stand in the active lane to 'slow traffic with hand signals' alone without training/authority",quality:"incorrect",next:"ops01-n3",feedback:"Use proper traffic control resources; do not improvise in live lanes."},{id:"ops01-n2-wrong",text:"Ignore oncoming traffic once parked",quality:"incorrect",next:"ops01-n3",feedback:"Situational awareness continues for the whole call.",delayedCritical:!0}]},{id:"ops01-n3",prompt:"A second vehicle nearly hits your unit. Best operational response?",options:[{id:"ops01-n3-best",text:"Increase scene protection: request PD/DOT for traffic control, adjust positioning if safe, keep personnel out of live lanes",quality:"best",next:"ops01-n4",feedback:"Correct. Escalate traffic control rather than accepting ongoing struck-by risk."},{id:"ops01-n3-ok",text:"Chase the near-miss driver personally",quality:"harmful",next:"ops01-n4",feedback:"Do not abandon the scene or create new hazards.",delayedCritical:!0},{id:"ops01-n3-bad",text:"Move all patients into the travel lane for 'visibility'",quality:"harmful",next:"ops01-n4",feedback:"Keep patients and providers in the protected work zone.",delayedCritical:!0},{id:"ops01-n3-wrong",text:"Turn off all lights so traffic 'won't notice you'",quality:"incorrect",next:"ops01-n4",feedback:"Use lighting per SOP to warn traffic while avoiding unnecessary dazzle."}]},{id:"ops01-n4",prompt:"Key principle of ambulance operations on roadways?",options:[{id:"ops01-n4-best",text:"Your crew's safety enables patient care — never trade provider safety for a few seconds of access",quality:"best",next:"end",feedback:"Correct. Safe positioning and PPE are part of EMS operations, not optional extras."},{id:"ops01-n4-ok",text:"Speed of parking matters more than barrier protection",quality:"incorrect",next:"end",feedback:"Deliberate protective positioning comes first."},{id:"ops01-n4-bad",text:"Highway calls never need reflective vests",quality:"incorrect",next:"end",feedback:"High-visibility apparel is standard for traffic incidents."},{id:"ops01-n4-wrong",text:"Only fire apparatus can create a block — ambulances never consider positioning",quality:"incorrect",next:"end",feedback:"Ambulances also position for safety within their role."}]}],correctSequence:["Park to create a protective barrier with egress","Wear high-visibility PPE; scan traffic","Escalate traffic control if struck-by risk persists","Provider safety enables care"],keyTakeaway:"On roadways, position the ambulance as a shield, wear high-visibility gear, and never work casually in live lanes."}),(0,t.sc)({id:"operations-02",title:"START Triage Basics",category:"operations",difficulty:"application",source:t.NATIONAL,dispatch:"Bus vs. truck MCI. Multiple casualties. You are assigned triage.",scene:"Highway shoulder. Command establishing. More than 10 patients visible. Limited initial resources.",presentation:"You must rapidly categorize patients using START (Simple Triage and Rapid Treatment) concepts.",startNodeId:"ops02-n1",nodes:[{id:"ops02-n1",prompt:"First START action for ambulatory patients who can walk to a designated area?",options:[{id:"ops02-n1-best",text:"Direct walking wounded to a green (minor) area for later assessment",quality:"best",next:"ops02-n2",feedback:"Correct. Ability to walk initially sorts many patients as minor (green) for delayed care."},{id:"ops02-n1-ok",text:"Declare every walking patient expectant (black) automatically",quality:"incorrect",next:"ops02-n2",feedback:"Walking wounded are typically minor, not expectant."},{id:"ops02-n1-bad",text:"Provide a full secondary exam to each walker before moving anyone",quality:"incorrect",next:"ops02-n2",feedback:"START is rapid — detailed exams come later.",delayedCritical:!0},{id:"ops02-n1-wrong",text:"Ignore all walking patients forever",quality:"incorrect",next:"ops02-n2",feedback:"They still need later assessment and may worsen."}]},{id:"ops02-n2",prompt:"Non-walking adult: not breathing. After airway opened, still apneic. START category?",options:[{id:"ops02-n2-best",text:"Expectant / deceased (black) in START adult algorithm when apnea persists after airway positioning",quality:"best",next:"ops02-n3",feedback:"Correct. In START, persistent apnea after simple airway opening is black/expectant when resources are overwhelmed."},{id:"ops02-n2-ok",text:"Immediate (red) and begin prolonged single-patient ALS on scene while ignoring others",quality:"incorrect",next:"ops02-n3",feedback:"MCI triage limits initial care so more salvageable patients can be reached.",delayedCritical:!0},{id:"ops02-n2-bad",text:"Minor (green)",quality:"incorrect",next:"ops02-n3",feedback:"Apnea is never minor."},{id:"ops02-n2-wrong",text:"Delayed (yellow) without checking breathing",quality:"incorrect",next:"ops02-n3",feedback:"Breathing assessment is required in START."}]},{id:"ops02-n3",prompt:"Adult: breathing >30/min after airway check, or radial pulse absent / CRT >2 sec, or cannot follow commands. Category?",options:[{id:"ops02-n3-best",text:"Immediate (red)",quality:"best",next:"ops02-n4",feedback:"Correct. RPM failures (Respirations, Perfusion, Mental status) triage to immediate."},{id:"ops02-n3-ok",text:"Minor (green)",quality:"incorrect",next:"ops02-n4",feedback:"These findings indicate immediate priority."},{id:"ops02-n3-bad",text:"No category — START does not use mental status",quality:"incorrect",next:"ops02-n4",feedback:"Ability to follow commands is part of START mental-status check."},{id:"ops02-n3-wrong",text:"Automatically black regardless of breathing",quality:"incorrect",next:"ops02-n4",feedback:"Breathing patients with RPM failure are red, not black."}]},{id:"ops02-n4",prompt:"Adult who cannot walk but has normal RPM — category?",options:[{id:"ops02-n4-best",text:"Delayed (yellow)",quality:"best",next:"end",feedback:"Correct. Non-ambulatory with adequate RPM is delayed."},{id:"ops02-n4-ok",text:"Immediate (red) solely because they cannot walk",quality:"incorrect",next:"end",feedback:"Inability to walk alone does not equal red if RPM is intact."},{id:"ops02-n4-bad",text:"Expectant (black)",quality:"incorrect",next:"end",feedback:"Intact RPM means delayed, not expectant."},{id:"ops02-n4-wrong",text:"Skip tagging to save time",quality:"incorrect",next:"end",feedback:"Tagging communicates priority to the next providers.",delayedCritical:!0}]}],correctSequence:["Send walking wounded to green","Persistent apnea after airway → black in START","RPM failure → red","Non-walker with intact RPM → yellow"],keyTakeaway:"START sorts by walk → breathe → RPM so limited rescuers help the most salvageable patients first."}),(0,t.sc)({id:"operations-03",title:"Landing Zone Basics",category:"operations",difficulty:"application",source:t.NATIONAL,dispatch:"Critical trauma patient; air medical requested. You are asked to set up an LZ.",scene:"Rural field near a two-lane road at dusk. Wires along the road. Soft ground in one corner.",presentation:"Patient packaging ongoing. Helicopter 8 minutes out. You must brief and prepare the LZ.",startNodeId:"ops03-n1",nodes:[{id:"ops03-n1",prompt:"Ideal LZ characteristics for a helicopter?",options:[{id:"ops03-n1-best",text:"Level, firm, free of wires/debris/loose objects, adequate size, marked, with wind direction known and radio contact",quality:"best",next:"ops03-n2",feedback:"Correct. Safe LZs are clear, marked, and communicated to the aircraft."},{id:"ops03-n1-ok",text:"Directly under power lines for easy landmarking",quality:"harmful",next:"ops03-n2",feedback:"Wires are a leading LZ hazard — avoid them.",delayedCritical:!0},{id:"ops03-n1-bad",text:"A soft muddy depression filled with loose trash",quality:"harmful",next:"ops03-n2",feedback:"Debris becomes projectiles; soft ground risks dynamic rollover/settling issues.",delayedCritical:!0},{id:"ops03-n1-wrong",text:"Any driveway regardless of obstacles because helicopters can 'hover forever'",quality:"incorrect",next:"ops03-n2",feedback:"Choose an appropriate site; do not assume the aircraft can safely ignore hazards."}]},{id:"ops03-n2",prompt:"As the aircraft approaches, how should ground personnel behave?",options:[{id:"ops03-n2-best",text:"Secure loose items, stay clear of the rotor disc unless directed, approach only when signaled — usually from the front/downhill as instructed",quality:"best",next:"ops03-n3",feedback:"Correct. Never approach without crew direction; protect against rotor wash and blades."},{id:"ops03-n2-ok",text:"Run under the tail rotor to 'help faster'",quality:"harmful",next:"ops03-n3",feedback:"Tail rotor strikes are deadly — never approach from the rear.",delayedCritical:!0},{id:"ops03-n2-bad",text:"Hold IV poles and blankets high overhead in rotor wash",quality:"harmful",next:"ops03-n3",feedback:"Secure and lower equipment; loose objects fly.",delayedCritical:!0},{id:"ops03-n2-wrong",text:"Shine lasers or high-beam lights into the cockpit",quality:"harmful",next:"ops03-n3",feedback:"Do not blind the pilots; mark the LZ appropriately.",delayedCritical:!0}]},{id:"ops03-n3",prompt:"What information is most useful in an LZ radio brief?",options:[{id:"ops03-n3-best",text:"Location description, LZ hazards (wires/trees/slope), wind, patient weight/status summary, and how the LZ is marked",quality:"best",next:"ops03-n4",feedback:"Correct. Pilots need hazards and wind as much as patient details."},{id:"ops03-n3-ok",text:"Only the patient's favorite sports team",quality:"incorrect",next:"ops03-n4",feedback:"Keep the brief operational and clinical."},{id:"ops03-n3-bad",text:"Hide wire hazards so the crew is not 'worried'",quality:"harmful",next:"ops03-n4",feedback:"Always disclose hazards.",delayedCritical:!0},{id:"ops03-n3-wrong",text:"No radio contact is needed if you can wave",quality:"incorrect",next:"ops03-n4",feedback:"Establish communications with the aircraft/command."}]},{id:"ops03-n4",prompt:"Patient loaded; aircraft departing. Your role?",options:[{id:"ops03-n4-best",text:"Keep personnel clear until rotors are safe/aircraft departed; secure the scene; complete documentation and ground transport tasks as assigned",quality:"best",next:"end",feedback:"Correct. Stay clear during departure — rotor hazards remain."},{id:"ops03-n4-ok",text:"Stand directly behind the tail to 'feel the wind'",quality:"harmful",next:"end",feedback:"Never occupy the tail-rotor area.",delayedCritical:!0},{id:"ops03-n4-bad",text:"Chase the helicopter in a personal vehicle down the highway",quality:"incorrect",next:"end",feedback:"Unnecessary and dangerous."},{id:"ops03-n4-wrong",text:"Leave loose scene tape and trash for the next rotor wash event",quality:"incorrect",next:"end",feedback:"Police the LZ of debris."}]}],correctSequence:["Select clear, level, marked LZ away from wires","Approach aircraft only when directed; never via tail","Brief hazards, wind, marking, patient summary","Stay clear during departure"],keyTakeaway:"LZ safety: clear hazards, mark and brief the site, and never approach the aircraft without crew direction."}),(0,t.sc)({id:"operations-04",title:"Radio Report Structure",category:"operations",difficulty:"foundational",source:t.NATIONAL,dispatch:"You are transporting a stroke alert candidate. Hospital asks for a radio report.",scene:"En route, lights and siren. Partner driving. You have a concise patient summary ready.",presentation:"72 y/o female, last known well 45 minutes ago, right-sided weakness, speech difficulty, SpO₂ 97% on O₂, BP 178/96, glucose checked normal per protocol.",vitals:{hr:88,rr:16,spo2:97,bp:"178/96",glucose:"normal range",gcs:"14"},startNodeId:"ops04-n1",nodes:[{id:"ops04-n1",prompt:"Best opening for a hospital radio report?",options:[{id:"ops04-n1-best",text:"Identify unit, ETA, age/sex, chief concern, and priority (e.g., possible stroke alert)",quality:"best",next:"ops04-n2",feedback:"Correct. Lead with who you are, when you arrive, and why it matters."},{id:"ops04-n1-ok",text:"Read the entire PCR including billing address first",quality:"incorrect",next:"ops04-n2",feedback:"Keep radio reports concise and clinical."},{id:"ops04-n1-bad",text:"Use the patient's full name and Social Security number on an open channel",quality:"incorrect",next:"ops04-n2",feedback:"Minimize unnecessary identifiers on radio; share what is needed for care.",delayedCritical:!0},{id:"ops04-n1-wrong",text:"Say nothing because 'they will see us soon'",quality:"incorrect",next:"ops04-n2",feedback:"Early notification prepares stroke resources.",delayedCritical:!0}]},{id:"ops04-n2",prompt:"Which clinical content is most important next?",options:[{id:"ops04-n2-best",text:"Last known well time, key neuro deficits, pertinent vitals/glucose, treatments, and current trends",quality:"best",next:"ops04-n3",feedback:"Correct. Time last known well and deficit pattern drive stroke preparation."},{id:"ops04-n2-ok",text:"Only that the patient 'looks sick' with no details",quality:"incorrect",next:"ops04-n3",feedback:"Specific findings enable team readiness."},{id:"ops04-n2-bad",text:"A 10-minute story about traffic with no patient data",quality:"incorrect",next:"ops04-n3",feedback:"Stay on clinical content."},{id:"ops04-n2-wrong",text:"Guess a definitive hospital diagnosis as fact",quality:"incorrect",next:"ops04-n3",feedback:"Report findings and suspected stroke signs — not overconfident labels."}]},{id:"ops04-n3",prompt:"Radio traffic is congested. How do you keep the report effective?",options:[{id:"ops04-n3-best",text:"Be brief, pause for questions, confirm receipt of critical elements (ETA, LKW, deficits)",quality:"best",next:"ops04-n4",feedback:"Correct. Clarity beats length on a busy channel."},{id:"ops04-n3-ok",text:"Shout continuously without listening for acknowledgment",quality:"incorrect",next:"ops04-n4",feedback:"Listen for confirmation and questions."},{id:"ops04-n3-bad",text:"Use unprofessional codes or jokes about the patient",quality:"incorrect",next:"ops04-n4",feedback:"Remain professional — others can hear."},{id:"ops04-n3-wrong",text:"Invent vital signs you did not measure",quality:"harmful",next:"ops04-n4",feedback:"Never fabricate clinical data.",delayedCritical:!0}]},{id:"ops04-n4",prompt:"After the radio report, what still matters at bedside handoff?",options:[{id:"ops04-n4-best",text:"Update any changes since the radio call and give a structured face-to-face MIST/SAMPLE-style handoff",quality:"best",next:"end",feedback:"Correct. Radio reports can go stale — close the loop in person."},{id:"ops04-n4-ok",text:"Leave without speaking because radio already happened",quality:"incorrect",next:"end",feedback:"Bedside handoff remains essential.",delayedCritical:!0},{id:"ops04-n4-bad",text:"Contradict your report with unrelated speculation",quality:"incorrect",next:"end",feedback:"Be consistent and accurate."},{id:"ops04-n4-wrong",text:"Hide medications you assisted with",quality:"harmful",next:"end",feedback:"Always report treatments and times.",delayedCritical:!0}]}],correctSequence:["Open with unit, ETA, demographics, priority","Give LKW, deficits, vitals/glucose, treatments","Keep it brief; confirm critical items","Update changes at bedside handoff"],keyTakeaway:"Radio reports: unit/ETA/priority first, then time-critical clinical facts — update again at the bedside."}),(0,t.sc)({id:"operations-05",title:"BSI and Infection Control",category:"operations",difficulty:"foundational",source:t.NATIONAL,dispatch:"Unresponsive patient with possible overdose. Vomitus on clothing. Unknown medical history.",scene:"Small bathroom. Limited space. Fluid on floor. Partner preparing suction.",presentation:"Gurgling respirations, soiled airway, needle paraphernalia nearby.",startNodeId:"ops05-n1",nodes:[{id:"ops05-n1",prompt:"Before patient contact, what BSI is most appropriate?",options:[{id:"ops05-n1-best",text:"Gloves at minimum; add eye protection/mask/gown as exposure risk rises (splash, airway, blood)",quality:"best",next:"ops05-n2",feedback:"Correct. Scale PPE to the task and exposure risk."},{id:"ops05-n1-ok",text:"No gloves because you 'know this patient'",quality:"harmful",next:"ops05-n2",feedback:"BSI is not optional based on familiarity.",delayedCritical:!0},{id:"ops05-n1-bad",text:"Reuse blood-soiled gloves between patients without changing",quality:"harmful",next:"ops05-n2",feedback:"Change contaminated gloves; avoid cross-contamination.",delayedCritical:!0},{id:"ops05-n1-wrong",text:"Only wash hands after needlesticks, never before care",quality:"incorrect",next:"ops05-n2",feedback:"Hand hygiene belongs before and after patient contact."}]},{id:"ops05-n2",prompt:"You sustain a needlestick from debris while moving the patient. Immediate action?",options:[{id:"ops05-n2-best",text:"Encourage bleeding, wash with soap and water, notify supervisor/designated officer, seek medical evaluation per exposure plan",quality:"best",next:"ops05-n3",feedback:"Correct. Follow the agency exposure-control plan promptly."},{id:"ops05-n2-ok",text:"Ignore it and tell no one",quality:"harmful",next:"ops05-n3",feedback:"Unreported exposures delay prophylaxis and documentation.",delayedCritical:!0},{id:"ops05-n2-bad",text:"Suck the wound and continue without washing",quality:"harmful",next:"ops05-n3",feedback:"Do not suck wounds; wash and report.",delayedCritical:!0},{id:"ops05-n2-wrong",text:"Throw the needle into the regular trash unmarked",quality:"harmful",next:"ops05-n3",feedback:"Use sharps containers; never loose sharps in trash.",delayedCritical:!0}]},{id:"ops05-n3",prompt:"After the call, infection-control priorities include:",options:[{id:"ops05-n3-best",text:"Remove PPE correctly, hand hygiene, disinfect equipment/surfaces, bag contaminated linen per policy",quality:"best",next:"ops05-n4",feedback:"Correct. Post-call decontamination protects the next patient and crew."},{id:"ops05-n3-ok",text:"Wipe blood with a dry napkin only and skip disinfection",quality:"incorrect",next:"ops05-n4",feedback:"Use proper EPA-appropriate disinfectants per policy."},{id:"ops05-n3-bad",text:"Wear the same gloves to write the report, eat, and hug family",quality:"harmful",next:"ops05-n4",feedback:"Remove PPE before leaving the clinical workspace.",delayedCritical:!0},{id:"ops05-n3-wrong",text:"Store used sharps in a pants pocket for later",quality:"harmful",next:"ops05-n4",feedback:"Immediate sharps disposal only.",delayedCritical:!0}]},{id:"ops05-n4",prompt:"Core BSI principle for EMTs?",options:[{id:"ops05-n4-best",text:"Assume every patient can transmit infection — use standard precautions consistently",quality:"best",next:"end",feedback:"Correct. Standard precautions protect you and your patients on every call."},{id:"ops05-n4-ok",text:"PPE only for patients who 'look infectious'",quality:"incorrect",next:"end",feedback:"Many infections are not obvious — use standard precautions always."},{id:"ops05-n4-bad",text:"Hand hygiene is outdated",quality:"incorrect",next:"end",feedback:"Hand hygiene remains foundational."},{id:"ops05-n4-wrong",text:"Only ALS providers need exposure plans",quality:"incorrect",next:"end",feedback:"All EMS personnel follow exposure-control policies."}]}],correctSequence:["Scale PPE to exposure risk","Report and care for needlesticks per plan","Decontaminate and doff PPE correctly after the call","Use standard precautions every time"],keyTakeaway:"BSI is standard precautions on every call — right PPE, careful sharps handling, and post-call disinfection."}),(0,t.sc)({id:"medical-legal-01",title:"Consent and Informed Refusal",category:"medical_legal",difficulty:"application",source:t.NATIONAL,dispatch:"48 y/o with chest discomfort. Patient is alert and talking when you arrive.",scene:"Home. Spouse present. No hazards.",presentation:"Alert, oriented ×4, understands questions. Mild chest pressure. Wants to 'wait it out' and refuses transport.",vitals:{hr:92,rr:18,spo2:96,bp:"150/88",gcs:"15"},startNodeId:"ml01-n1",nodes:[{id:"ml01-n1",prompt:"The patient refuses transport. What must you assess first?",options:[{id:"ml01-n1-best",text:"Decision-making capacity: oriented, understands risks/benefits/alternatives, and can explain their choice",quality:"best",next:"ml01-n2",feedback:"Correct. Valid refusal requires an adult with decision-making capacity."},{id:"ml01-n1-ok",text:"Nothing — anyone who says no is automatically released without assessment",quality:"harmful",next:"ml01-n2",feedback:"You must assess capacity and explain risks before accepting refusal.",delayedCritical:!0},{id:"ml01-n1-bad",text:"Force treatment immediately without talking because chest pain always voids rights",quality:"harmful",next:"ml01-n2",feedback:"Alert capacitated adults can refuse — even if you disagree clinically.",delayedCritical:!0},{id:"ml01-n1-wrong",text:"Only ask the spouse; ignore the patient",quality:"incorrect",next:"ml01-n2",feedback:"The capacitated patient is the decision-maker."}]},{id:"ml01-n2",prompt:"Patient demonstrates capacity. Best next step for refusal?",options:[{id:"ml01-n2-best",text:"Explain risks of refusal (including death/disability), benefits of transport, offer alternatives, document thoroughly, encourage 911 if worsens",quality:"best",next:"ml01-n3",feedback:"Correct. Informed refusal includes risk discussion and clear documentation."},{id:"ml01-n2-ok",text:"Have them sign a blank form without explanation",quality:"incorrect",next:"ml01-n3",feedback:"A signature without information is not informed refusal.",delayedCritical:!0},{id:"ml01-n2-bad",text:"Threaten to call police to arrest them for refusing",quality:"incorrect",next:"ml01-n3",feedback:"Do not coerce with false legal threats."},{id:"ml01-n2-wrong",text:"Leave immediately without vitals, advice, or documentation",quality:"harmful",next:"ml01-n3",feedback:"Assess, advise, and document before clearing.",delayedCritical:!0}]},{id:"ml01-n3",prompt:"During discussion the patient becomes newly confused and hypotensive. What changes?",options:[{id:"ml01-n3-best",text:"Capacity is now in doubt — treat under emergency/implied consent principles and transport",quality:"best",next:"ml01-n4",feedback:"Correct. Loss of capacity plus emergency condition allows emergency care."},{id:"ml01-n3-ok",text:"Still honor the earlier refusal without reassessing",quality:"harmful",next:"ml01-n4",feedback:"Refusal is not valid if capacity is lost and an emergency exists.",delayedCritical:!0},{id:"ml01-n3-bad",text:"Ask an uninvolved neighbor to refuse on their behalf",quality:"incorrect",next:"ml01-n4",feedback:"Neighbors are not automatic decision-makers."},{id:"ml01-n3-wrong",text:"Wait an hour without intervening to 'see what happens'",quality:"harmful",next:"ml01-n4",feedback:"Treat the emergency.",delayedCritical:!0}]},{id:"ml01-n4",prompt:"Best documentation elements for refusal encounters?",options:[{id:"ml01-n4-best",text:"Capacity assessment, risks explained, patient questions, witnesses, signature/refusal form, advice to call back, vitals/findings",quality:"best",next:"end",feedback:"Correct. Thorough documentation protects the patient record and the provider."},{id:"ml01-n4-ok",text:"Only 'pt refused' with no details",quality:"incorrect",next:"end",feedback:"Details matter legally and clinically."},{id:"ml01-n4-bad",text:"Alter the chart later to hide that risks were not explained",quality:"harmful",next:"end",feedback:"Never falsify records.",delayedCritical:!0},{id:"ml01-n4-wrong",text:"No documentation if the patient was polite",quality:"incorrect",next:"end",feedback:"Document every refusal."}]}],correctSequence:["Assess decision-making capacity","Explain risks/benefits; document informed refusal","If capacity lost with emergency, treat/transport","Document capacity, risks, advice, and signatures"],keyTakeaway:"Capacitated adults may refuse — but only after risks are explained and capacity is confirmed."}),(0,t.sc)({id:"medical-legal-02",title:"Implied Consent — Unresponsive Patient",category:"medical_legal",difficulty:"foundational",source:t.NATIONAL,dispatch:"Unknown medical, unresponsive adult in a store aisle. No family on scene.",scene:"Retail store. Staff present. AED available. Patient collapsed minutes ago.",presentation:"Unresponsive, snoring, possible weak pulse. No wallet ID located yet.",startNodeId:"ml02-n1",nodes:[{id:"ml02-n1",prompt:"May you treat this unresponsive adult without verbal consent?",options:[{id:"ml02-n1-best",text:"Yes — implied consent assumes a reasonable person would want emergency care when unable to consent",quality:"best",next:"ml02-n2",feedback:"Correct. Unresponsive patients are treated under implied consent."},{id:"ml02-n1-ok",text:"No — you must wait for a signed form before opening the airway",quality:"harmful",next:"ml02-n2",feedback:"Delaying emergency care for paperwork harms the patient.",delayedCritical:!0},{id:"ml02-n1-bad",text:"Only if a store manager guesses what the patient would want",quality:"incorrect",next:"ml02-n2",feedback:"Implied consent does not require a manager's permission."},{id:"ml02-n1-wrong",text:"Never treat without a relative present",quality:"incorrect",next:"ml02-n2",feedback:"Emergency care proceeds without family if needed.",delayedCritical:!0}]},{id:"ml02-n2",prompt:"A bystander claims the patient 'hates doctors' and demands you stop. Best response?",options:[{id:"ml02-n2-best",text:"Continue emergency care; a random bystander cannot refuse for an unresponsive patient without legal authority",quality:"best",next:"ml02-n3",feedback:"Correct. Do not stop life-saving care based on unverified third-party claims."},{id:"ml02-n2-ok",text:"Immediately stop all care and leave",quality:"harmful",next:"ml02-n3",feedback:"Abandonment risk — continue indicated emergency care.",delayedCritical:!0},{id:"ml02-n2-bad",text:"Ask the bystander to take the patient home in their car",quality:"harmful",next:"ml02-n3",feedback:"Unresponsive patients need EMS care and transport.",delayedCritical:!0},{id:"ml02-n2-wrong",text:"Argue for several minutes without managing the airway",quality:"incorrect",next:"ml02-n3",feedback:"Airway/breathing come first while you address concerns briefly.",delayedCritical:!0}]},{id:"ml02-n3",prompt:"Patient regains consciousness and capacitatedly refuses further care. What now?",options:[{id:"ml02-n3-best",text:"Reassess capacity, explain what happened and risks of refusal, then proceed with informed consent or informed refusal process",quality:"best",next:"ml02-n4",feedback:"Correct. When capacity returns, consent rules shift back to expressed consent/refusal."},{id:"ml02-n3-ok",text:"Forcibly restrain and treat forever because implied consent never ends",quality:"harmful",next:"ml02-n4",feedback:"Implied consent covers the emergency while incapacitated — not indefinite forced care after capacity returns.",delayedCritical:!0},{id:"ml02-n3-bad",text:"Ignore capacity and accept refusal from anyone nearby",quality:"incorrect",next:"ml02-n4",feedback:"Assess the patient directly."},{id:"ml02-n3-wrong",text:"Hide that you already treated them",quality:"incorrect",next:"ml02-n4",feedback:"Be honest about care already provided."}]},{id:"ml02-n4",prompt:"Implied consent most clearly applies when:",options:[{id:"ml02-n4-best",text:"A patient is unresponsive or otherwise unable to consent and has an emergency condition requiring care",quality:"best",next:"end",feedback:"Correct. Emergency + inability to consent = implied consent."},{id:"ml02-n4-ok",text:"A capacitated adult calmly refuses and you disagree",quality:"incorrect",next:"end",feedback:"That is not implied consent — that is a refusal situation."},{id:"ml02-n4-bad",text:"Any minor scrape with no urgency",quality:"incorrect",next:"end",feedback:"Implied consent targets emergency inability to consent."},{id:"ml02-n4-wrong",text:"Only after hospital admission paperwork",quality:"incorrect",next:"end",feedback:"Field emergency care uses implied consent when needed."}]}],correctSequence:["Treat unresponsive emergencies under implied consent","Do not stop care for unverified bystander refusals","When capacity returns, use expressed consent/refusal","Know when implied consent applies"],keyTakeaway:"Unresponsive emergency patients are treated under implied consent until they can decide for themselves."}),(0,t.sc)({id:"medical-legal-03",title:"DNR Recognition",category:"medical_legal",difficulty:"application",source:t.NATIONAL,dispatch:"Nursing facility, cardiac arrest. Staff says there is a DNR.",scene:"Long-term care room. Nurse present with paperwork. Patient pulseless, apneic.",presentation:"Unresponsive, no breathing, no pulse. Nurse hands you a document while CPR has not yet started.",startNodeId:"ml03-n1",nodes:[{id:"ml03-n1",prompt:"You are handed a paper. What should you verify before withholding resuscitation?",options:[{id:"ml03-n1-best",text:"Valid, apparent state-recognized DNR/POLST for this patient, properly executed per local rules — then follow it",quality:"best",next:"ml03-n2",feedback:"Correct. Honor valid out-of-hospital DNR/POLST orders after identity and validity checks per protocol."},{id:"ml03-n1-ok",text:"A sticky note that says 'no CPR' with no identifiers or signatures",quality:"incorrect",next:"ml03-n2",feedback:"Informal notes are not valid DNR orders.",delayedCritical:!0},{id:"ml03-n1-bad",text:"A relative's verbal statement alone with no documentation when policy requires a form",quality:"incorrect",next:"ml03-n2",feedback:"Follow local requirements — usually a recognized form/bracelet/order."},{id:"ml03-n1-wrong",text:"Any document in the room regardless of patient name",quality:"harmful",next:"ml03-n2",feedback:"Confirm it belongs to this patient.",delayedCritical:!0}]},{id:"ml03-n2",prompt:"No valid DNR is present and the patient is in arrest. Action?",options:[{id:"ml03-n2-best",text:"Begin resuscitation per protocol while continuing to look for valid orders",quality:"best",next:"ml03-n3",feedback:"Correct. Without a valid order, provide emergency care."},{id:"ml03-n2-ok",text:"Withhold CPR based on age alone",quality:"harmful",next:"ml03-n3",feedback:"Age is not a DNR.",delayedCritical:!0},{id:"ml03-n2-bad",text:"Wait 20 minutes for a fax that might arrive",quality:"harmful",next:"ml03-n3",feedback:"Do not delay resuscitation for speculative paperwork.",delayedCritical:!0},{id:"ml03-n2-wrong",text:"Ask bystanders to vote",quality:"incorrect",next:"ml03-n3",feedback:"Follow legal orders and protocols, not polls."}]},{id:"ml03-n3",prompt:"A valid DNR is confirmed mid-resuscitation. Best action?",options:[{id:"ml03-n3-best",text:"Stop resuscitation efforts per the order and provide comfort-focused care as allowed; document times and decision",quality:"best",next:"ml03-n4",feedback:"Correct. Once a valid DNR is confirmed, honor it and document."},{id:"ml03-n3-ok",text:"Continue full ACLS indefinitely because you already started",quality:"incorrect",next:"ml03-n4",feedback:"Valid orders should be honored when recognized."},{id:"ml03-n3-bad",text:"Hide the DNR from your partner",quality:"harmful",next:"ml03-n4",feedback:"Share valid orders with the team.",delayedCritical:!0},{id:"ml03-n3-wrong",text:"Destroy the document",quality:"harmful",next:"ml03-n4",feedback:"Preserve and document legal orders.",delayedCritical:!0}]},{id:"ml03-n4",prompt:"Family arrives upset that a DNR exists. Your role?",options:[{id:"ml03-n4-best",text:"Explain compassionately that you must follow valid legal orders; involve supervisors/medical direction as needed; do not argue cruelly",quality:"best",next:"end",feedback:"Correct. Be empathetic while complying with lawful orders and policy."},{id:"ml03-n4-ok",text:"Ignore the DNR because family is louder",quality:"incorrect",next:"end",feedback:"Valid patient orders are not overridden by volume."},{id:"ml03-n4-bad",text:"Mock the family's grief",quality:"harmful",next:"end",feedback:"Remain professional and compassionate.",delayedCritical:!0},{id:"ml03-n4-wrong",text:"Make a new DNR on a napkin for a different patient",quality:"harmful",next:"end",feedback:"Never fabricate legal orders.",delayedCritical:!0}]}],correctSequence:["Verify valid patient-specific DNR/POLST","Resuscitate if no valid order","Honor a confirmed valid DNR and document","Communicate compassionately with family; follow law/policy"],keyTakeaway:"Honor valid DNR/POLST after identity checks — without one, resuscitate."}),(0,t.sc)({id:"medical-legal-04",title:"Negligence and Duty",category:"medical_legal",difficulty:"foundational",source:t.NATIONAL,dispatch:"Classroom-style review embedded in a call QA scenario after a delayed airway case.",scene:"Post-call review with a preceptor. You discuss what legally constitutes negligence.",presentation:"A previous crew allegedly ignored an obvious obstructed airway for a prolonged period.",startNodeId:"ml04-n1",nodes:[{id:"ml04-n1",prompt:"Which elements are commonly required to prove negligence?",options:[{id:"ml04-n1-best",text:"Duty to act, breach of duty, damages/harm, and causation linking breach to harm",quality:"best",next:"ml04-n2",feedback:"Correct. Negligence generally needs duty, breach, damages, and causation."},{id:"ml04-n1-ok",text:"Only that the patient disliked the EMT's personality",quality:"incorrect",next:"ml04-n2",feedback:"Personality conflict alone is not negligence."},{id:"ml04-n1-bad",text:"A perfect outcome is required on every call or it is negligence",quality:"incorrect",next:"ml04-n2",feedback:"Bad outcomes can occur despite appropriate care."},{id:"ml04-n1-wrong",text:"Negligence never applies to EMS",quality:"incorrect",next:"ml04-n2",feedback:"EMS providers can be held to a standard of care."}]},{id:"ml04-n2",prompt:"You are on duty and dispatched. What is 'duty to act'?",options:[{id:"ml04-n2-best",text:"An obligation to respond and provide care within your scope and protocols while on duty for that service",quality:"best",next:"ml04-n3",feedback:"Correct. On-duty EMS typically has a duty to act once assigned/dispatched per agency rules."},{id:"ml04-n2-ok",text:"A requirement to perform surgery outside your scope",quality:"incorrect",next:"ml04-n3",feedback:"Duty is within scope of practice — not beyond it."},{id:"ml04-n2-bad",text:"Permission to abandon a patient after starting care without transfer",quality:"harmful",next:"ml04-n3",feedback:"Abandonment is a serious breach once care has begun.",delayedCritical:!0},{id:"ml04-n2-wrong",text:"Only a duty to drive fast with no patient care",quality:"incorrect",next:"ml04-n3",feedback:"Duty includes appropriate assessment and care."}]},{id:"ml04-n3",prompt:"Which is the best example of breach of duty at EMT level?",options:[{id:"ml04-n3-best",text:"Failing to open an obviously obstructed airway or provide indicated BVM support that a similarly trained EMT would provide",quality:"best",next:"ml04-n4",feedback:"Correct. Breach compares your actions to the expected standard of care."},{id:"ml04-n3-ok",text:"Following protocol and documenting carefully",quality:"incorrect",next:"ml04-n4",feedback:"That supports meeting the standard of care."},{id:"ml04-n3-bad",text:"Asking for ALS when the patient is critical",quality:"incorrect",next:"ml04-n4",feedback:"Requesting appropriate resources is good care."},{id:"ml04-n3-wrong",text:"Wearing gloves for BSI",quality:"incorrect",next:"ml04-n4",feedback:"PPE is expected, not a breach."}]},{id:"ml04-n4",prompt:"Best practical defense against negligence claims?",options:[{id:"ml04-n4-best",text:"Practice within protocols/scope, communicate, reassess, and document accurately and contemporaneously",quality:"best",next:"end",feedback:"Correct. Good care plus good documentation is your best protection."},{id:"ml04-n4-ok",text:"Falsify charts to look perfect",quality:"harmful",next:"end",feedback:"Fraud makes everything worse.",delayedCritical:!0},{id:"ml04-n4-bad",text:"Never write anything down",quality:"incorrect",next:"end",feedback:"Absence of documentation harms continuity and legal defense."},{id:"ml04-n4-wrong",text:"Ignore medical direction",quality:"incorrect",next:"end",feedback:"Follow lawful medical direction and protocols."}]}],correctSequence:["Know duty, breach, damages, causation","On-duty response creates duty to act within scope","Breach = failure to meet expected EMT standard","Follow protocols and document well"],keyTakeaway:"Negligence = duty + breach + harm caused by the breach — meet the standard and document it."}),(0,t.sc)({id:"medical-legal-05",title:"HIPAA and Field Privacy",category:"medical_legal",difficulty:"foundational",source:t.NATIONAL,dispatch:"You transported a local elected official with a possible overdose. Media is on scene at the hospital.",scene:"ED ambulance bay. Reporters asking questions. Your partner still has the PCR open on a screen.",presentation:"Patient already handed off. Crew is cleaning the unit. Phones are out.",startNodeId:"ml05-n1",nodes:[{id:"ml05-n1",prompt:"A reporter asks for the patient's name and diagnosis. Best response?",options:[{id:"ml05-n1-best",text:"Decline to share protected health information; refer media to the agency PIO/public information process",quality:"best",next:"ml05-n2",feedback:"Correct. Do not disclose PHI to the media."},{id:"ml05-n1-ok",text:"Confirm the overdose details because the person is famous",quality:"harmful",next:"ml05-n2",feedback:"Fame does not waive privacy.",delayedCritical:!0},{id:"ml05-n1-bad",text:"Trade information for a quote about how skilled you are",quality:"harmful",next:"ml05-n2",feedback:"Never barter PHI.",delayedCritical:!0},{id:"ml05-n1-wrong",text:"Post the PCR photo on social media 'for education'",quality:"harmful",next:"ml05-n2",feedback:"Social media posts can violate HIPAA.",delayedCritical:!0}]},{id:"ml05-n2",prompt:"When is sharing patient information generally permitted?",options:[{id:"ml05-n2-best",text:"For treatment, payment, and health-care operations — including handoff to receiving clinicians who need it for care",quality:"best",next:"ml05-n3",feedback:"Correct. PHI may be shared for treatment with the care team; minimize unnecessary disclosure."},{id:"ml05-n2-ok",text:"With any curious coworker who is not involved in care",quality:"incorrect",next:"ml05-n3",feedback:"Need-to-know applies — idle gossip is not allowed."},{id:"ml05-n2-bad",text:"On a podcast using full identifiers without authorization",quality:"harmful",next:"ml05-n3",feedback:"Unauthorized public disclosure is a violation.",delayedCritical:!0},{id:"ml05-n2-wrong",text:"Never, even to the ED physician accepting the patient",quality:"incorrect",next:"ml05-n3",feedback:"Treatment-related handoffs are appropriate."}]},{id:"ml05-n3",prompt:"Your partner leaves a PCR visible on a screen facing the hallway. Action?",options:[{id:"ml05-n3-best",text:"Shield/close the screen, store records securely, and remind the team about minimum necessary disclosure",quality:"best",next:"ml05-n4",feedback:"Correct. Prevent incidental exposure of PHI."},{id:"ml05-n3-ok",text:"Increase font size so more people can read it",quality:"harmful",next:"ml05-n4",feedback:"That increases unauthorized access.",delayedCritical:!0},{id:"ml05-n3-bad",text:"Email the PCR to your personal account for 'later studying'",quality:"harmful",next:"ml05-n4",feedback:"Do not move PHI to unsecured personal accounts.",delayedCritical:!0},{id:"ml05-n3-wrong",text:"Read the chart aloud in the cafeteria for fun",quality:"harmful",next:"ml05-n4",feedback:"Public discussion of PHI is inappropriate.",delayedCritical:!0}]},{id:"ml05-n4",prompt:"Core HIPAA field takeaway for EMTs?",options:[{id:"ml05-n4-best",text:"Protect PHI: share for care on a need-to-know basis, secure records/devices, and avoid public/social disclosure",quality:"best",next:"end",feedback:"Correct. Privacy is part of professional practice."},{id:"ml05-n4-ok",text:"HIPAA means you cannot give a radio report to the hospital",quality:"incorrect",next:"end",feedback:"Treatment communications are allowed; keep them relevant."},{id:"ml05-n4-bad",text:"Privacy rules never apply in EMS",quality:"incorrect",next:"end",feedback:"EMS handles PHI and must protect it."},{id:"ml05-n4-wrong",text:"Only paper records matter; phones are exempt",quality:"incorrect",next:"end",feedback:"Electronic devices and photos are covered too."}]}],correctSequence:["Do not disclose PHI to media; use PIO channels","Share for treatment with need-to-know clinicians","Secure screens/records from public view","Protect PHI in all field and online settings"],keyTakeaway:"Share patient information for care on a need-to-know basis — never for gossip, media, or social media."})];e.s(["allScenarios",0,a,"getScenario",0,function(e){return a.find(t=>t.id===e)},"scenariosByCategory",0,function(e){return a.filter(t=>t.category===e)}],52947)}]);